),
depots AS (
  SELECT
    'BACK_OFFICE' AS source_mouvement,
    o.ID AS id_operation,
    o.DATE_OPERATION,
    DATEADD(
      WEEK,
      DATEDIFF(WEEK, CAST('1900-01-01' AS DATETIME2), CAST(o.DATE_OPERATION AS DATETIME2)),
      0
    ) AS semaine_debut,
    ca.ID_ADHERENT,
    MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))) AS montant_depot,
    h.ID_DEVISE
  FROM dbo.OPERATIONS AS o
  INNER JOIN dbo.HDPM AS h
    ON h.ID_OPERATION = o.ID
  INNER JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.id = h.ID_COMPTE
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND o.ID_TYPE_OPERATION = 'DEPO'
    AND ISNULL(o.ANNULE, 0) = 0
    AND UPPER(ISNULL(h.SENS, '')) IN ('C', 'CREDIT')
    AND (
      @id_devise_reporting IS NULL OR h.ID_DEVISE = @id_devise_reporting
    )
  GROUP BY
    o.ID,
    o.DATE_OPERATION,
    DATEADD(
      WEEK,
      DATEDIFF(WEEK, CAST('1900-01-01' AS DATETIME2), CAST(o.DATE_OPERATION AS DATETIME2)),
      0
    ),
    ca.ID_ADHERENT,
    h.ID_DEVISE
  UNION ALL
  SELECT
    'API_MOBILE',
    oa.CODE,
    oa.DATE_OPERATION,
    DATEADD(
      WEEK,
      DATEDIFF(WEEK, CAST('1900-01-01' AS DATETIME2), CAST(oa.DATE_OPERATION AS DATETIME2)),
      0
    ),
    ca.ID_ADHERENT,
    MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))),
    h.ID_DEVISE
  FROM dbo.OPERATIONS_API AS oa
  INNER JOIN dbo.HDPM_API AS h
    ON h.ID_OPERATION = oa.CODE
  INNER JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.id = h.ID_COMPTE
  WHERE
    oa.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND oa.ID_TYPE_OPERATION = 'MOB_DEPO'
    AND ISNULL(oa.ANNULE, 0) = 0
    AND UPPER(ISNULL(h.SENS, '')) IN ('C', 'CREDIT')
    AND (
      @id_devise_reporting IS NULL OR h.ID_DEVISE = @id_devise_reporting
    )
  GROUP BY
    oa.CODE,
    oa.DATE_OPERATION,
    DATEADD(
      WEEK,
      DATEDIFF(WEEK, CAST('1900-01-01' AS DATETIME2), CAST(oa.DATE_OPERATION AS DATETIME2)),
      0
    ),
    ca.ID_ADHERENT,
    h.ID_DEVISE
), depots_semaine AS (
  SELECT
    ID_ADHERENT AS ID_ADHERENT,
    semaine_debut AS semaine_debut,
    COUNT(DISTINCT id_operation) AS nb_depots_semaine,
    SUM(montant_depot) AS volume_depots_semaine
  FROM depots
  GROUP BY
    ID_ADHERENT,
    semaine_debut
)
SELECT
  ecv.code_client,
  ecv.num_manuel,
  ecv.nom_client,
  ecv.prenoms_client,
  ecv.code_categorie_client,
  ecv.categorie_client,
  ecv.code_type_client,
  ecv.type_client,
  ecv.telephone,
  ecv.code_agence,
  ecv.nom_agence,
  ds.semaine_debut,
  DATEADD(DAY, 6, ds.semaine_debut) AS semaine_fin,
  ds.nb_depots_semaine,
  CASE
    WHEN ds.nb_depots_semaine BETWEEN 3 AND 5
    THEN '3 a 5 depots par semaine'
    WHEN ds.nb_depots_semaine >= 6
    THEN '6 depots et plus par semaine'
  END AS categorie_frequence,
  ds.volume_depots_semaine
FROM depots_semaine AS ds
LEFT JOIN base_clients AS ecv
  ON ecv.id_client = ds.ID_ADHERENT
WHERE
  ds.nb_depots_semaine >= 3
ORDER BY
  ds.nb_depots_semaine DESC,
  ds.volume_depots_semaine DESC,
  ds.semaine_debut,
  ecv.code_client;

/*
 93. Clients avec depots par tranche USD/CDF sur la periode
 Export : 93_cycle_epargne_clients_avec_depots_par_tranche_usd_cdf_sur_la_periode
 Objectif : reperer les clients qui effectuent des depots dans les tranches de montant sensibles definies pour USD et CDF.
 Lecture : USD est classe en 10-24.99, 25-49.99, 50-99.99, 100 et plus. CDF est classe en 125000-199999 et 200000 et plus. Les depots inferieurs aux seuils ne sortent pas.
 Niveau d'importance de la requete : 10
 Usage operationnel : reperer les clients qui effectuent des depots dans les tranches de montant sensibles definies pour USD et CDF.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
