gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
)
SELECT
  DATEFROMPARTS(YEAR(t.DATE_ECHEANCE), MONTH(t.DATE_ECHEANCE), 1) AS mois_echeance,
  ecv.code_agence_demande,
  ecv.nom_agence_demande,
  ecv.produit,
  ecv.code_devise,
  COUNT(DISTINCT ecv.id_pret) AS nb_prets_concernes,
  COUNT(DISTINCT t.ID) AS nb_echeances,
  SUM(ISNULL(t.CAPITAL, 0)) AS capital_attendu,
  SUM(ISNULL(t.INTERET, 0)) AS interet_attendu,
  SUM(ISNULL(t.COMMISSION, 0)) AS commission_attendue,
  SUM(ISNULL(t.EPARGNE, 0)) AS epargne_attendue,
  SUM(
    ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)
  ) AS total_attendu
FROM base_credits AS ecv
INNER JOIN dbo.TABAMOR AS t
  ON t.ID_CYCLE_PRET = ecv.id_cycle_pret
WHERE
  ecv.date_effet <= @date_fin
  AND (
    ecv.date_solde IS NULL OR ecv.date_solde > @date_fin
  )
  AND (
    ecv.date_perte IS NULL OR ecv.date_perte > @date_fin
  )
  AND (
    ecv.date_cloture_cycle IS NULL OR ecv.date_cloture_cycle > @date_fin
  )
  AND ecv.date_debut_cycle <= @date_fin
  AND t.DATE_ECHEANCE > @date_fin
  AND t.DATE_ECHEANCE <= DATEADD(YEAR, 1, @date_fin)
GROUP BY
  DATEFROMPARTS(YEAR(t.DATE_ECHEANCE), MONTH(t.DATE_ECHEANCE), 1),
  ecv.code_agence_demande,
  ecv.nom_agence_demande,
  ecv.id_produit,
  ecv.produit,
  ecv.code_devise
ORDER BY
  mois_echeance,
  nom_agence_demande,
  produit;

/*
 101. Dashboard retention et renouvellement mensuel
 Export : 101_cycle_credit_dashboard_retention_et_renouvellement_mensuel
 Objectif : mesurer la retention globale et la retention a 90 jours des clients dont un prêt arrive a solde.
 Lecture : un client est retenu s'il obtient un nouveau prêt apres DATE_SOLDE; la retention90Days limite ce nouveau prêt aux 90 jours suivant le solde.
 Niveau d'importance de la requete : 10
 Usage operationnel : mesurer la retention globale et la retention a 90 jours des clients dont un prêt arrive a solde.
 Periodicite recommandee : Mensuel
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
), prets_soldes AS (
  SELECT
    p.ID AS id_pret_solde,
    p.DATE_SOLDE AS DATE_SOLDE,
    ISNULL(p.MONTANT, 0) AS montant_pret_solde,
    ecv.id_client AS id_client,
    ecv.code_client AS code_client,
    ecv.code_agence_demande AS code_agence_demande,
    ecv.nom_agence_demande AS nom_agence_demande,
    ecv.id_produit AS id_produit,
    ecv.produit AS produit,
    ecv.code_devise AS code_devise
  FROM dbo.PRETS AS p
  INNER JOIN dbo.DOSSIERS_CREDIT AS d
    ON d.ID = p.ID_DOSSIER_CREDIT
  INNER JOIN dbo.DEMANDES_CREDIT AS dc
    ON dc.ID = d.ID_DEMANDE
  INNER JOIN credits_uniques AS ecv
    ON ecv.id_pret = p.ID AND ecv.rn = 1
  WHERE
    p.DATE_SOLDE BETWEEN @date_debut AND @date_fin
), renouvellement AS (
  SELECT
    ps.*,
    np.id_nouveau_pret AS id_nouveau_pret,
    np.date_nouveau_pret AS date_nouveau_pret,
    DATEDIFF(DAY, CAST(ps.DATE_SOLDE AS DATETIME2), CAST(np.date_nouveau_pret AS DATETIME2)) AS delai_renouvellement_jours
  FROM prets_soldes AS ps OUTER APPLY (
    SELECT
    TOP 1
      p2.ID AS id_nouveau_pret,
      COALESCE(p2.DATE_DECAISSEMENT, p2.DATE_EFFET) AS date_nouveau_pret
    FROM dbo.DEMANDES_CREDIT AS dc2
    INNER JOIN dbo.DOSSIERS_CREDIT AS d2
      ON d2.ID_DEMANDE = dc2.ID
    INNER JOIN dbo.PRETS AS p2
      ON p2.ID_DOSSIER_CREDIT = d2.ID
    WHERE
      dc2.ID_ADHERENT = ps.id_client
      AND p2.ID <> ps.id_pret_solde
      AND COALESCE(p2.DATE_DECAISSEMENT, p2.DATE_EFFET) > ps.DATE_SOLDE
    ORDER BY
      COALESCE(p2.DATE_DECAISSEMENT, p2.DATE_EFFET)
  ) AS np
)
SELECT
  DATEFROMPARTS(YEAR(DATE_SOLDE), MONTH(DATE_SOLDE), 1) AS mois_solde,
  code_agence_demande,
  nom_agence_demande,
  produit,
  code_devise,
  COUNT(DISTINCT id_client) AS nb_clients_arrives_echeance,
  COUNT(DISTINCT id_pret_solde) AS nb_prets_soldes,
  SUM(montant_pret_solde) AS montant_prets_soldes,
  COUNT(DISTINCT CASE WHEN NOT id_nouveau_pret IS NULL THEN id_client END) AS nb_clients_renouveles,
  COUNT(
    DISTINCT CASE WHEN delai_renouvellement_jours BETWEEN 1 AND 90 THEN id_client END
  ) AS nb_clients_renouveles_90j,
  CASE
    WHEN COUNT(DISTINCT id_client) = 0
    THEN 0
    ELSE ROUND(
      100.0 * COUNT(DISTINCT CASE WHEN NOT id_nouveau_pret IS NULL THEN id_client END) / COUNT(DISTINCT id_client),
      2
    )
  END AS retention_pct,
  CASE
    WHEN COUNT(DISTINCT id_client) = 0
    THEN 0
    ELSE ROUND(
      100.0 * COUNT(
        DISTINCT CASE WHEN delai_renouvellement_jours BETWEEN 1 AND 90 THEN id_client END
      ) / COUNT(DISTINCT id_client),
      2
    )
  END AS retention_90j_pct,
  AVG(CAST(delai_renouvellement_jours AS FLOAT)) AS delai_moyen_renouvellement_jours
FROM renouvellement
GROUP BY
  DATEFROMPARTS(YEAR(DATE_SOLDE), MONTH(DATE_SOLDE), 1),
  code_agence_demande,
  nom_agence_demande,
  id_produit,
  produit,
  code_devise
ORDER BY
  mois_solde,
  nom_agence_demande,
  produit;

/*
 102. Dashboard vintage PAR par cohorte de decaissement
 Export : 102_cycle_credit_dashboard_vintage_par_par_cohorte_de_decaissement
 Objectif : suivre la qualite des cohortes de prêts decaisses et leur exposition PAR a @date_fin.
 Lecture : la cohorte correspond au mois de décaissement. Le résultat donne l'age de la cohorte en mois, l'encours restant et les montants PAR30/PAR90 observés a @date_fin.
 Niveau d'importance de la requete : 10
 Usage operationnel : suivre la qualite des cohortes de prêts decaisses et leur exposition PAR a @date_fin.
 Periodicite recommandee : Mensuel
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), remboursements_echeance AS (
  SELECT
    r.ID_TABAMORT AS ID_TABAMORT,
    SUM(
      ISNULL(r.CAPITAL, 0) + ISNULL(r.INTERET, 0) + ISNULL(r.COMMISSION, 0) + ISNULL(r.EPARGNE, 0)
    ) AS total_rembourse
  FROM dbo.REMBOURS_CRD AS r
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = r.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    r.ID_TABAMORT
), retard_pret AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    MAX(
      CASE
        WHEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) - ISNULL(re.total_rembourse, 0) > 0.01
        THEN DATEDIFF(DAY, CAST(t.DATE_ECHEANCE AS DATETIME2), CAST(@date_fin AS DATETIME2))
        ELSE 0
      END
    ) AS jours_retard
  FROM dbo.CYCLES_PRET AS cp
  INNER JOIN dbo.TABAMOR AS t
    ON t.ID_CYCLE_PRET = cp.ID
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE < @date_fin
  GROUP BY
    cp.ID_PRET
), credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
), base AS (
  SELECT
    DATEFROMPARTS(
      YEAR(COALESCE(ecv.date_decaissement, ecv.date_effet)),
      MONTH(COALESCE(ecv.date_decaissement, ecv.date_effet)),
      1
    ) AS cohorte_decaissement,
    DATEDIFF(
      MONTH,
      CAST(DATEFROMPARTS(
        YEAR(COALESCE(ecv.date_decaissement, ecv.date_effet)),
        MONTH(COALESCE(ecv.date_decaissement, ecv.date_effet)),
        1
      ) AS DATETIME2),
      CAST(DATEFROMPARTS(YEAR(@date_fin), MONTH(@date_fin), 1) AS DATETIME2)
    ) AS age_cohorte_mois,
    ecv.code_agence_demande AS code_agence_demande,
    ecv.nom_agence_demande AS nom_agence_demande,
    ecv.id_produit AS id_produit,
    ecv.produit AS produit,
    ecv.code_devise AS code_devise,
    ecv.id_pret AS id_pret,
    ISNULL(ecv.mtt_pret, 0) AS montant_initial,
    ISNULL(ep.mtt_encours, 0) AS mtt_encours,
    ISNULL(rp.jours_retard, 0) AS jours_retard
  FROM credits_uniques AS ecv
  LEFT JOIN encours_pret AS ep
    ON ep.ID_PRET = ecv.id_pret
  LEFT JOIN retard_pret AS rp
    ON rp.ID_PRET = ecv.id_pret
  WHERE
    COALESCE(ecv.date_decaissement, ecv.date_effet) BETWEEN @date_debut AND @date_fin
    AND ecv.rn = 1
)
SELECT
  cohorte_decaissement,
  age_cohorte_mois,
  code_agence_demande,
  nom_agence_demande,
  produit,
  code_devise,
  COUNT(DISTINCT id_pret) AS nb_prets_decaisse,
  SUM(montant_initial) AS montant_initial_cohorte,
  SUM(mtt_encours) AS encours_restant,
  SUM(CASE WHEN jours_retard > 30 THEN mtt_encours ELSE 0 END) AS par_30_plus,
  SUM(CASE WHEN jours_retard > 90 THEN mtt_encours ELSE 0 END) AS par_90_plus,
  CASE
    WHEN SUM(montant_initial) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(CASE WHEN jours_retard > 30 THEN mtt_encours ELSE 0 END) / SUM(montant_initial),
      2
    )
  END AS par_30_sur_initial_pct,
  CASE
    WHEN SUM(montant_initial) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(CASE WHEN jours_retard > 90 THEN mtt_encours ELSE 0 END) / SUM(montant_initial),
      2
    )
  END AS par_90_sur_initial_pct
FROM base
GROUP BY
  cohorte_decaissement,
  age_cohorte_mois,
  code_agence_demande,
  nom_agence_demande,
  id_produit,
  produit,
  code_devise
ORDER BY
  cohorte_decaissement,
  nom_agence_demande,
  produit;

/*
 103. Dashboard epargne solde et comptes par mois produit et agence
 Export : 103_cycle_epargne_dashboard_epargne_solde_et_comptes_par_mois_produit_et_agence
 Objectif : alimenter les courbes de solde epargne, nombre de comptes et solde moyen par produit/agence.
 Lecture : calcule le solde comptable a chaque fin de mois avec la CTE locale mouvements_comptables. Les comptes clotures avant la date de situation mensuelle sont exclus.
 Niveau d'importance de la requete : 10
 Usage operationnel : alimenter les courbes de solde epargne, nombre de comptes et solde moyen par produit/agence.
 Periodicite recommandee : Mensuel
 */
WITH mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
mois AS (
  SELECT
    EOMONTH(CAST(@date_debut AS DATE)) AS date_situation
  UNION ALL
  SELECT
    EOMONTH(CAST(DATEADD(MONTH, 1, date_situation) AS DATE))
  FROM mois
  WHERE
    EOMONTH(CAST(DATEADD(MONTH, 1, date_situation) AS DATE)) <= EOMONTH(CAST(@date_fin AS DATE))
), comptes_epargne AS (
  SELECT
    c.ID AS id_compte,
    c.NUM_CPTE AS NUM_CPTE,
    c.LIBELLE AS libelle_compte,
    c.DATE_OUVERTURE AS DATE_OUVERTURE,
    c.ID_POINT_SERVICE AS id_agence_compte,
    ps.CODE AS code_agence_compte,
    ps.NOM AS nom_agence_compte,
    ca.ID_ADHERENT AS id_client,
    ca.TYPE_CPTE_ADH AS type_compte_adherent,
    dv.CODE AS code_devise,
    pe.ID AS id_produit_epargne,
    ISNULL(pe.LIBELLE, c.LIBELLE) AS produit_epargne
  FROM dbo.COMPTES AS c
  INNER JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.id = c.ID
  LEFT JOIN dbo.COMPTES_ADHERENT_INFO AS cai
    ON cai.id = c.ID
  LEFT JOIN dbo.PRODUITS_EPG AS pe
    ON pe.ID = cai.ID_PRODUIT_EPG
  LEFT JOIN dbo.DEVISES AS dv
    ON dv.ID = c.ID_DEVISE
  LEFT JOIN dbo.POINTS_SERVICE AS ps
    ON ps.ID = c.ID_POINT_SERVICE
  WHERE
    ca.TYPE_CPTE_ADH IN ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
), soldes_mensuels AS (
  SELECT
    m.date_situation AS date_situation,
    ce.id_compte AS id_compte,
    SUM(CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END * ISNULL(h.MONTANT_OPERATION, 0)) AS solde_compte
  FROM mois AS m
  INNER JOIN comptes_epargne AS ce
    ON ce.DATE_OUVERTURE <= m.date_situation
  LEFT JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = ce.id_compte AND h.DATE_OPERATION <= m.date_situation
  WHERE
    NOT EXISTS(
      SELECT
        1
      FROM dbo.CLOTURE_COMPTE AS cc
      WHERE
        cc.ID_COMPTE = ce.id_compte AND cc.DATE_CLOTURE <= m.date_situation
    )
  GROUP BY
    m.date_situation,
    ce.id_compte
)
SELECT
  sm.date_situation,
  DATEFROMPARTS(YEAR(sm.date_situation), MONTH(sm.date_situation), 1) AS mois,
  ce.code_agence_compte,
  ce.nom_agence_compte,
  ce.produit_epargne,
  ce.type_compte_adherent,
  ce.code_devise,
  COUNT(DISTINCT ce.id_compte) AS nb_comptes,
  COUNT(DISTINCT ce.id_client) AS nb_clients,
  SUM(ISNULL(sm.solde_compte, 0)) AS solde_epargne,
  CASE
    WHEN COUNT(DISTINCT ce.id_compte) = 0
    THEN 0
    ELSE ROUND(SUM(ISNULL(sm.solde_compte, 0)) / COUNT(DISTINCT ce.id_compte), 2)
  END AS solde_moyen_compte
FROM soldes_mensuels AS sm
INNER JOIN comptes_epargne AS ce
  ON ce.id_compte = sm.id_compte
GROUP BY
  sm.date_situation,
  DATEFROMPARTS(YEAR(sm.date_situation), MONTH(sm.date_situation), 1),
  ce.id_agence_compte,
  ce.code_agence_compte,
  ce.nom_agence_compte,
  ce.id_produit_epargne,
  ce.produit_epargne,
  ce.type_compte_adherent,
  ce.code_devise
ORDER BY
  sm.date_situation,
  ce.nom_agence_compte,
  ce.produit_epargne OPTION(
    MAXRECURSION 0
);

/*
 104. Dashboard PAR par tranche de montant initial du credit
 Export : 104_cycle_credit_dashboard_par_par_tranche_de_montant_initial_du_credit
 Objectif : alimenter les visuels PAR par intervalle de montant initial et comparer le risque selon la taille du credit.
 Lecture : classe les prêts actifs a @date_fin par tranches de montant initial puis calcule PAR1, PAR30 et PAR90 sur l'encours.
 Niveau d'importance de la requete : 10
 Usage operationnel : alimenter les visuels PAR par intervalle de montant initial et comparer le risque selon la taille du credit.
 Periodicite recommandee : Mensuel
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), remboursements_echeance AS (
  SELECT
    r.ID_TABAMORT AS ID_TABAMORT,
    SUM(
      ISNULL(r.CAPITAL, 0) + ISNULL(r.INTERET, 0) + ISNULL(r.COMMISSION, 0) + ISNULL(r.EPARGNE, 0)
    ) AS total_rembourse
  FROM dbo.REMBOURS_CRD AS r
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = r.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    r.ID_TABAMORT
), retard_pret AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    MAX(
      CASE
        WHEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) - ISNULL(re.total_rembourse, 0) > 0.01
        THEN DATEDIFF(DAY, CAST(t.DATE_ECHEANCE AS DATETIME2), CAST(@date_fin AS DATETIME2))
        ELSE 0
      END
    ) AS jours_retard
  FROM dbo.CYCLES_PRET AS cp
  INNER JOIN dbo.TABAMOR AS t
    ON t.ID_CYCLE_PRET = cp.ID
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE < @date_fin
  GROUP BY
    cp.ID_PRET
), base AS (
  SELECT
    ecv.code_agence_demande AS code_agence_demande,
    ecv.nom_agence_demande AS nom_agence_demande,
    ecv.id_produit AS id_produit,
    ecv.produit AS produit,
    ecv.code_devise AS code_devise,
    ecv.id_pret AS id_pret,
    ecv.id_client AS id_client,
    ISNULL(ecv.mtt_pret, 0) AS montant_initial,
    ISNULL(ep.mtt_encours, 0) AS mtt_encours,
    ISNULL(rp.jours_retard, 0) AS jours_retard,
    CASE
      WHEN ISNULL(ecv.mtt_pret, 0) < 10000
      THEN 'Moins de 10K'
      WHEN ISNULL(ecv.mtt_pret, 0) < 15000
      THEN '10K a 15K'
      WHEN ISNULL(ecv.mtt_pret, 0) < 30000
      THEN '15K a 30K'
      WHEN ISNULL(ecv.mtt_pret, 0) < 50000
      THEN '30K a 50K'
      ELSE '50K et plus'
    END AS tranche_montant_initial
  FROM base_credits AS ecv
  LEFT JOIN encours_pret AS ep
    ON ep.ID_PRET = ecv.id_pret
  LEFT JOIN retard_pret AS rp
    ON rp.ID_PRET = ecv.id_pret
  WHERE
    ecv.date_effet <= @date_fin
    AND (
      ecv.date_solde IS NULL OR ecv.date_solde > @date_fin
    )
    AND (
      ecv.date_perte IS NULL OR ecv.date_perte > @date_fin
    )
    AND (
      ecv.date_cloture_cycle IS NULL OR ecv.date_cloture_cycle > @date_fin
    )
    AND ecv.date_debut_cycle <= @date_fin
    AND ISNULL(ep.mtt_encours, 0) > 0
)
SELECT
  @date_fin AS date_situation,
  code_agence_demande,
  nom_agence_demande,
  produit,
  code_devise,
  tranche_montant_initial,
  COUNT(DISTINCT id_client) AS nb_clients,
  COUNT(DISTINCT id_pret) AS nb_prets,
  SUM(montant_initial) AS montant_initial_total,
  SUM(mtt_encours) AS encours_total,
  SUM(CASE WHEN jours_retard > 0 THEN mtt_encours ELSE 0 END) AS par_1_plus,
  SUM(CASE WHEN jours_retard > 30 THEN mtt_encours ELSE 0 END) AS par_30_plus,
  SUM(CASE WHEN jours_retard > 90 THEN mtt_encours ELSE 0 END) AS par_90_plus,
  CASE
    WHEN SUM(mtt_encours) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(CASE WHEN jours_retard > 0 THEN mtt_encours ELSE 0 END) / SUM(mtt_encours),
      2
    )
  END AS par_1_pct,
  CASE
    WHEN SUM(mtt_encours) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(CASE WHEN jours_retard > 30 THEN mtt_encours ELSE 0 END) / SUM(mtt_encours),
      2
    )
  END AS par_30_pct,
  CASE
    WHEN SUM(mtt_encours) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(CASE WHEN jours_retard > 90 THEN mtt_encours ELSE 0 END) / SUM(mtt_encours),
      2
    )
  END AS par_90_pct
FROM base
GROUP BY
  code_agence_demande,
  nom_agence_demande,
  id_produit,
  produit,
  code_devise,
  tranche_montant_initial
ORDER BY
  code_devise,
  nom_agence_demande,
  produit,
  CASE tranche_montant_initial
    WHEN 'Moins de 10K'
    THEN 1
    WHEN '10K a 15K'
    THEN 2
    WHEN '15K a 30K'
    THEN 3
    WHEN '30K a 50K'
    THEN 4
    ELSE 5
  END;

/*
 105. Dashboard concentration top 10 pourcent des encours
 Export : 105_cycle_credit_dashboard_concentration_top_10_pourcent_des_encours
 Objectif : mesurer la concentration du portefeuille sur les plus gros encours par agence, produit et devise.
 Lecture : classe les prêts actifs par encours decroissant dans chaque groupe agence/produit/devise et isole le premier decile pour calculer sa part dans l'encours.
 Niveau d'importance de la requete : 10
 Usage operationnel : mesurer la concentration du portefeuille sur les plus gros encours par agence, produit et devise.
 Periodicite recommandee : Mensuel
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), base AS (
  SELECT
    ecv.code_agence_demande AS code_agence_demande,
    ecv.nom_agence_demande AS nom_agence_demande,
    ecv.id_produit AS id_produit,
    ecv.produit AS produit,
    ecv.code_devise AS code_devise,
    ecv.id_pret AS id_pret,
    ecv.id_client AS id_client,
    ecv.code_client AS code_client,
    ecv.nom_client AS nom_client,
    ecv.prenoms_client AS prenoms_client,
    ISNULL(ep.mtt_encours, 0) AS mtt_encours,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.code_agence_demande, ecv.id_produit, ecv.code_devise
      ORDER BY ISNULL(ep.mtt_encours, 0) DESC
    ) AS rang_encours,
    COUNT(*) OVER (PARTITION BY ecv.code_agence_demande, ecv.id_produit, ecv.code_devise) AS nb_prets_groupe
  FROM base_credits AS ecv
  INNER JOIN encours_pret AS ep
    ON ep.ID_PRET = ecv.id_pret
  WHERE
    ecv.date_effet <= @date_fin
    AND (
      ecv.date_solde IS NULL OR ecv.date_solde > @date_fin
    )
    AND (
      ecv.date_perte IS NULL OR ecv.date_perte > @date_fin
    )
    AND (
      ecv.date_cloture_cycle IS NULL OR ecv.date_cloture_cycle > @date_fin
    )
    AND ecv.date_debut_cycle <= @date_fin
    AND ISNULL(ep.mtt_encours, 0) > 0
)
SELECT
  @date_fin AS date_situation,
  code_agence_demande,
  nom_agence_demande,
  produit,
  code_devise,
  COUNT(DISTINCT id_pret) AS nb_prets_actifs,
  SUM(mtt_encours) AS encours_total,
  SUM(
    CASE
      WHEN rang_encours <= CEILING(nb_prets_groupe * 0.10)
      THEN mtt_encours
      ELSE 0
    END
  ) AS encours_top_10_pct,
  COUNT(
    DISTINCT CASE WHEN rang_encours <= CEILING(nb_prets_groupe * 0.10) THEN id_pret END
  ) AS nb_prets_top_10_pct,
  CASE
    WHEN SUM(mtt_encours) = 0
    THEN 0
    ELSE ROUND(
      100.0 * SUM(
        CASE
          WHEN rang_encours <= CEILING(nb_prets_groupe * 0.10)
          THEN mtt_encours
          ELSE 0
        END
      ) / SUM(mtt_encours),
      2
    )
  END AS part_top_10_pct
FROM base
GROUP BY
  code_agence_demande,
  nom_agence_demande,
  id_produit,
  produit,
  code_devise
ORDER BY
  part_top_10_pct DESC,
  encours_total DESC;

/*
 106. Dashboard couverture credit par epargne et garanties
 Export : 106_cycle_credit_dashboard_couverture_credit_par_epargne_et_garanties
 Objectif : rapprocher l'encours et les arrieres credit avec l'epargne, les cautions et les garanties disponibles.
 Lecture : l'epargne client provient des soldes de la CTE locale mouvements_comptables a @date_fin; les cautions et garanties sont rattachees au pret ou a la demande de credit.
 Niveau d'importance de la requete : 10
 Usage operationnel : rapprocher l'encours et les arrieres credit avec l'epargne, les cautions et les garanties disponibles.
 Periodicite recommandee : Mensuel, ou avant comite credit important
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), remboursements_echeance AS (
  SELECT
    r.ID_TABAMORT AS ID_TABAMORT,
    SUM(
      ISNULL(r.CAPITAL, 0) + ISNULL(r.INTERET, 0) + ISNULL(r.COMMISSION, 0) + ISNULL(r.EPARGNE, 0)
    ) AS total_rembourse
  FROM dbo.REMBOURS_CRD AS r
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = r.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    r.ID_TABAMORT
), arrieres_pret AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    SUM(
      CASE
        WHEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) - ISNULL(re.total_rembourse, 0) > 0.01
        THEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) - ISNULL(re.total_rembourse, 0)
        ELSE 0
      END
    ) AS montant_arriere
  FROM dbo.CYCLES_PRET AS cp
  INNER JOIN dbo.TABAMOR AS t
    ON t.ID_CYCLE_PRET = cp.ID
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE < @date_fin
  GROUP BY
    cp.ID_PRET
), epargne_client AS (
  SELECT
    ca.ID_ADHERENT AS id_client,
    SUM(CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END * ISNULL(h.MONTANT_OPERATION, 0)) AS solde_epargne
  FROM dbo.COMPTES_ADHERENT AS ca
  INNER JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = ca.id
  WHERE
    h.DATE_OPERATION <= @date_fin
    AND ca.TYPE_CPTE_ADH IN ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
  GROUP BY
    ca.ID_ADHERENT
), cautions_pret AS (
  SELECT
    c.ID_PRET AS ID_PRET,
    SUM(ISNULL(cfd.MONTANT, 0) * CASE WHEN cfd.SENS = 'D' THEN -1 ELSE 1 END) AS solde_caution
  FROM dbo.CAUTIONS AS c
  LEFT JOIN dbo.CAUTIONS_FINANCIERE_DETAIL AS cfd
    ON cfd.ID_CAUTION_FIN = c.ID AND cfd.DATE_EFFET <= @date_fin
  GROUP BY
    c.ID_PRET
), garanties_demande AS (
  SELECT
    g.ID_DEMANDE_CREDIT AS ID_DEMANDE_CREDIT,
    SUM(ISNULL(g.VALEUR, 0)) AS valeur_garantie
  FROM dbo.GARANTIES AS g
  GROUP BY
    g.ID_DEMANDE_CREDIT
)
SELECT
  @date_fin AS date_situation,
  ecv.code_agence_demande,
  ecv.nom_agence_demande,
  ecv.produit,
  ecv.code_devise,
  ecv.code_client,
  ecv.nom_client,
  ecv.prenoms_client,
  ecv.numero_pret,
  ecv.mtt_pret AS montant_initial,
  ISNULL(ep.mtt_encours, 0) AS mtt_encours,
  ISNULL(ap.montant_arriere, 0) AS montant_arriere,
  ISNULL(ec.solde_epargne, 0) AS solde_epargne_client,
  ISNULL(cp.solde_caution, 0) AS solde_caution,
  ISNULL(gd.valeur_garantie, 0) AS valeur_garantie,
  CASE
    WHEN ISNULL(ap.montant_arriere, 0) <= ISNULL(ec.solde_epargne, 0)
    THEN ISNULL(ap.montant_arriere, 0)
    ELSE ISNULL(ec.solde_epargne, 0)
  END AS arriere_couvert_par_epargne,
  CASE
    WHEN ISNULL(ep.mtt_encours, 0) <= ISNULL(ec.solde_epargne, 0) + ISNULL(cp.solde_caution, 0) + ISNULL(gd.valeur_garantie, 0)
    THEN ISNULL(ep.mtt_encours, 0)
    ELSE ISNULL(ec.solde_epargne, 0) + ISNULL(cp.solde_caution, 0) + ISNULL(gd.valeur_garantie, 0)
  END AS principal_couvert,
  ISNULL(ep.mtt_encours, 0) - (
    ISNULL(ec.solde_epargne, 0) + ISNULL(cp.solde_caution, 0) + ISNULL(gd.valeur_garantie, 0)
  ) AS exposition_nette_non_couverte
FROM base_credits AS ecv
LEFT JOIN encours_pret AS ep
  ON ep.ID_PRET = ecv.id_pret
LEFT JOIN arrieres_pret AS ap
  ON ap.ID_PRET = ecv.id_pret
LEFT JOIN epargne_client AS ec
  ON ec.id_client = ecv.id_client
LEFT JOIN cautions_pret AS cp
  ON cp.ID_PRET = ecv.id_pret
LEFT JOIN garanties_demande AS gd
  ON gd.ID_DEMANDE_CREDIT = ecv.ID_DEMANDE
WHERE
  ecv.date_effet <= @date_fin
  AND (
    ecv.date_solde IS NULL OR ecv.date_solde > @date_fin
  )
  AND (
    ecv.date_perte IS NULL OR ecv.date_perte > @date_fin
  )
  AND (
    ecv.date_cloture_cycle IS NULL OR ecv.date_cloture_cycle > @date_fin
  )
  AND ecv.date_debut_cycle <= @date_fin
  AND ISNULL(ep.mtt_encours, 0) > 0
ORDER BY
  exposition_nette_non_couverte DESC,
  mtt_encours DESC;

/*
 107. Dashboard provision trois derniers mois par client agence produit
 Export : 107_cycle_credit_dashboard_provision_trois_derniers_mois_par_client_agence_produit
 Objectif : reproduire les visuels de provision par client, branche, produit et tranche de montant sur les trois derniers mois.
 Lecture : calcule le solde de provision par prêt a chaque fin de mois, sur les trois fins de mois jusqu'a @date_fin.
 Niveau d'importance de la requete : 10
 Usage operationnel : reproduire les visuels de provision par client, branche, produit et tranche de montant sur les trois derniers mois.
 Periodicite recommandee : Mensuel, a la cloture du portefeuille credit
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
mois AS (
  SELECT
    EOMONTH(CAST(@date_fin AS DATE)) AS date_situation
  UNION ALL
  SELECT
    EOMONTH(CAST(DATEADD(MONTH, -1, date_situation) AS DATE))
  FROM mois
  WHERE
    EOMONTH(CAST(DATEADD(MONTH, -1, date_situation) AS DATE)) >= EOMONTH(CAST(DATEADD(MONTH, -2, @date_fin) AS DATE))
), provisions AS (
  SELECT
    m.date_situation AS date_situation,
    pc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN pc.SENS = 'C' THEN 1 ELSE -1 END * ISNULL(pc.MONTANT, 0)) AS mtt_provision
  FROM mois AS m
  INNER JOIN dbo.PROVISIONS_CRD AS pc
    ON 1 = 1
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = pc.ID_OPERATION
    AND o.DATE_OPERATION <= m.date_situation
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    m.date_situation,
    pc.ID_PRET
), credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
)
SELECT
  p.date_situation,
  cu.code_agence_demande,
  cu.nom_agence_demande,
  cu.produit,
  cu.code_devise,
  cu.code_client,
  cu.nom_client,
  cu.prenoms_client,
  cu.numero_pret,
  cu.mtt_pret AS montant_initial,
  CASE
    WHEN ISNULL(cu.mtt_pret, 0) < 10000
    THEN 'Moins de 10K'
    WHEN ISNULL(cu.mtt_pret, 0) < 15000
    THEN '10K a 15K'
    WHEN ISNULL(cu.mtt_pret, 0) < 30000
    THEN '15K a 30K'
    WHEN ISNULL(cu.mtt_pret, 0) < 50000
    THEN '30K a 50K'
    ELSE '50K et plus'
  END AS tranche_montant_initial,
  p.mtt_provision
FROM provisions AS p
INNER JOIN credits_uniques AS cu
  ON cu.id_pret = p.ID_PRET AND cu.rn = 1
WHERE
  ISNULL(p.mtt_provision, 0) <> 0
ORDER BY
  p.date_situation DESC,
  p.mtt_provision DESC,
  cu.code_client OPTION(
    MAXRECURSION 0
);

/*
 108. Dashboard duree et echeances restantes des prets actifs
 Export : 108_cycle_credit_dashboard_duree_et_echeances_restantes_des_prets_actifs
 Objectif : alimenter les graphes sur la duree moyenne, le nombre total d'echeances et les echeances restantes.
 Lecture : le total d'echeances vient de TABAMOR; les echeances restantes sont celles dont DATE_ECHEANCE est posterieure a @date_fin pour les prêts actifs.
 Niveau d'importance de la requete : 10
 Usage operationnel : alimenter les graphes sur la duree moyenne, le nombre total d'echeances et les echeances restantes.
 Periodicite recommandee : Mensuel
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
