 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
), nombres AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1
  FROM nombres
  WHERE n < 255
)
SELECT
  c.code_client,
  c.num_manuel,
  LTRIM(RTRIM(CONCAT(ISNULL(c.nom_client, ''), ' ', ISNULL(c.prenoms_client, '')))) AS nom_complet,
  c.sexe,
  c.telephone AS Phone_Brut,
  CASE WHEN d.Tel_chiffres LIKE '243%' THEN 'Oui' ELSE 'Non' END AS Phone_243,
  CASE
    WHEN n.Phone_normalise = @PHONE_STAFF
    THEN 'NUMERO STAFF'
    WHEN n.Phone_normalise IS NULL
    THEN NULL
    WHEN LEN(n.Phone_normalise) = 12
    AND LEFT(n.Phone_normalise, 3) = '243'
    AND SUBSTRING(n.Phone_normalise, 4, 1) IN ('8', '9')
    THEN n.Phone_normalise
    ELSE 'A VERIFIER'
  END AS Phone_Prefixe,
  CASE
    WHEN c.telephone IS NULL OR LTRIM(RTRIM(c.telephone)) = ''
    THEN 'VIDE'
    WHEN n.Phone_normalise = @PHONE_STAFF
    THEN 'STAFF'
    WHEN LEN(n.Phone_normalise) = 12
    AND LEFT(n.Phone_normalise, 3) = '243'
    AND SUBSTRING(n.Phone_normalise, 4, 1) IN ('8', '9')
    THEN 'OK'
    ELSE 'A VERIFIER'
  END AS Statut_phone,
  CASE WHEN n.Phone_normalise = @PHONE_STAFF THEN 'Oui' ELSE 'Non' END AS Is_phone_staff,
  d.Tel_chiffres,
  CASE
    WHEN c.telephone IS NULL OR LTRIM(RTRIM(c.telephone)) = ''
    THEN 'Telephone vide'
    WHEN n.Phone_normalise = @PHONE_STAFF
    THEN 'Numero staff utilise a la place du numero client'
    WHEN d.Tel_chiffres IS NULL OR d.Tel_chiffres = ''
    THEN 'Aucun chiffre trouve'
    WHEN d.Tel_chiffres IN ('243')
    THEN 'Numero incomplet'
    WHEN LEN(n.Phone_normalise) = 12
    AND LEFT(n.Phone_normalise, 3) = '243'
    AND SUBSTRING(n.Phone_normalise, 4, 1) IN ('8', '9')
    THEN 'Telephone normalise'
    ELSE 'Format telephone invalide'
  END AS Commentaire_phone,
  c.type_piece_identite,
  c.numero_piece_identite,
  c.type_client,
  c.categorie_client,
  c.gestionnaire,
  c.client_perfect,
  c.collecteur
FROM base_clients AS c CROSS APPLY (
  SELECT
    (
      SELECT
        '' + SUBSTRING(ISNULL(c.telephone, ''), v.n, 1)
      FROM nombres AS v
      WHERE
        v.n <= LEN(ISNULL(c.telephone, ''))
        AND SUBSTRING(ISNULL(c.telephone, ''), v.n, 1) LIKE '[0-9]'
      ORDER BY
        v.n
      FOR XML
        PATH(''),
        TYPE
    ).value('.', 'varchar(50)') AS Tel_chiffres
) AS d CROSS APPLY (
  SELECT
    CASE
      WHEN d.Tel_chiffres IS NULL OR d.Tel_chiffres = ''
      THEN NULL
      WHEN LEFT(d.Tel_chiffres, 4) = '2430'
      THEN '243' + SUBSTRING(d.Tel_chiffres, 5, 50)
      WHEN LEFT(d.Tel_chiffres, 1) = '0'
      THEN '243' + SUBSTRING(d.Tel_chiffres, 2, 50)
      WHEN LEFT(d.Tel_chiffres, 3) = '243'
      THEN d.Tel_chiffres
      ELSE '243' + d.Tel_chiffres
    END AS Phone_normalise
) AS n
ORDER BY
  Statut_phone,
  Is_phone_staff DESC,
  c.code_client
OPTION (MAXRECURSION 255);
/*
 Section exports sources Streamlit par cycle
 Principe : executer le SELECT du cycle, exporter le resultat en Excel/CSV, puis televerser le fichier dans Streamlit apres avoir choisi le meme cycle.
 Les alias reprennent les colonnes attendues par credit_app/cycles.py quand elles existent dans Perfect Vision.
 */;

/*
 123. Source Streamlit - Cycle credit
 Export : 123_cycle_credit_streamlit
 Objectif : produire un fichier large par pret/dossier pour alimenter les analyses du cycle credit dans Streamlit.
 Lecture : une ligne represente le dernier cycle connu du pret, enrichi avec client, produit, agence, encours estime, echeances dues et statut de remboursement.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle credit dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle credit
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
), encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), remboursements_echeance AS (
  SELECT
    rc.ID_TABAMORT AS ID_TABAMORT,
    SUM(
      ISNULL(rc.CAPITAL, 0) + ISNULL(rc.INTERET, 0) + ISNULL(rc.COMMISSION, 0) + ISNULL(rc.PENALITE, 0)
    ) AS montant_rembourse
  FROM dbo.REMBOURS_CRD AS rc
  LEFT JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = rc.ID_OPERATION_CRD
  LEFT JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    rc.ID_TABAMORT
), echeances AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    COUNT(CASE WHEN t.DATE_ECHEANCE <= @date_fin THEN 1 END) AS nb_echeances_echues,
    SUM(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
        THEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0)
        ELSE 0
      END
    ) AS montant_attendu_echu,
    SUM(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
        THEN ISNULL(re.montant_rembourse, 0)
        ELSE 0
      END
    ) AS montant_rembourse_echu,
    MIN(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
        AND ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) > ISNULL(re.montant_rembourse, 0)
        THEN t.DATE_ECHEANCE
      END
    ) AS premiere_echeance_impayee,
    SUM(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
        AND ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) > ISNULL(re.montant_rembourse, 0)
        THEN 1
        ELSE 0
      END
    ) AS nb_echeances_impayees
  FROM dbo.CYCLES_PRET AS cp
  LEFT JOIN dbo.TABAMOR AS t
    ON t.ID_CYCLE_PRET = cp.ID
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  GROUP BY
    cp.ID_PRET
)
SELECT
  'credit' AS cycle_activite,
  cu.code_client,
  LTRIM(RTRIM(CONCAT(ISNULL(cu.nom_client, ''), ' ', ISNULL(cu.prenoms_client, '')))) AS nom_client,
  cu.numero_dossier,
  cu.numero_pret,
  cu.numero_contrat,
  cu.code_agence_demande AS code_agence,
  cu.nom_agence_demande AS agence,
  cu.gestionnaire_pret AS agent_credit,
  cu.produit AS type_produit,
  cu.objet_fin AS activite_economique,
  cu.secteur_activite,
  cu.date_demande,
  d.DATE_DECISION AS date_decision,
  cu.date_decaissement AS date_operation,
  cu.date_effet,
  cu.date_solde,
  cu.date_perte,
  cu.DATE_REECH AS date_reechelonnement,
  dem.MONTANT_DEMANDE AS montant_demande,
  COALESCE(d.MONTANT_ACCORDE, cu.mtt_pret) AS montant_accorde,
  cu.mtt_pret AS montant_pret,
  ISNULL(ep.mtt_encours, 0) AS solde_final,
  cu.code_devise AS devise,
  CAST(NULL AS FLOAT) AS revenu_mensuel,
  CAST(NULL AS FLOAT) AS charge_mensuelle,
  CAST(NULL AS FLOAT) AS score_credit,
  d.ETAT_DOSSIER AS statut_dossier,
  CASE
    WHEN ISNULL(e.nb_echeances_impayees, 0) > 0
    THEN 'En retard'
    WHEN NOT cu.date_solde IS NULL AND cu.date_solde <= @date_fin
    THEN 'Solde'
    WHEN NOT cu.date_perte IS NULL AND cu.date_perte <= @date_fin
    THEN 'Perte'
    ELSE 'A jour'
  END AS statut_remboursement,
  CASE
    WHEN e.premiere_echeance_impayee IS NULL
    THEN 0
    ELSE DATEDIFF(DAY, CAST(e.premiere_echeance_impayee AS DATETIME2), CAST(@date_fin AS DATETIME2))
  END AS retard_jours,
  ISNULL(e.nb_echeances_echues, 0) AS nb_echeances_echues,
  ISNULL(e.nb_echeances_impayees, 0) AS nb_echeances_impayees,
  ISNULL(e.montant_attendu_echu, 0) AS montant_attendu_echu,
  ISNULL(e.montant_rembourse_echu, 0) AS montant_rembourse_echu,
  ISNULL(e.montant_attendu_echu, 0) - ISNULL(e.montant_rembourse_echu, 0) AS montant_impaye_estime,
  d.TAUX_CAUTION AS garantie,
  cu.taux AS taux_interet,
  cu.nb_echeance AS duree_credit_mois,
  cu.periodicite,
  cu.type_client,
  cu.code_type_client,
  cu.telephone,
  cu.sexe,
  cu.zone AS zone_geographique,
  CONCAT('Source Perfect Vision; statut=', ISNULL(d.ETAT_DOSSIER, 'Non renseigne')) AS commentaire
FROM credits_uniques AS cu
LEFT JOIN dbo.DOSSIERS_CREDIT AS d
  ON d.ID = cu.id_dossier
LEFT JOIN dbo.DEMANDES_CREDIT AS dem
  ON dem.ID = d.ID_DEMANDE
LEFT JOIN encours_pret AS ep
  ON ep.ID_PRET = cu.id_pret
LEFT JOIN echeances AS e
  ON e.ID_PRET = cu.id_pret
WHERE
  cu.rn = 1
  AND COALESCE(cu.date_decaissement, cu.date_effet, d.DATE_DECISION, cu.date_demande) BETWEEN @date_debut AND @date_fin
ORDER BY
  COALESCE(cu.date_decaissement, cu.date_effet, d.DATE_DECISION, cu.date_demande) DESC,
  cu.nom_agence_demande,
  cu.code_client;

/*
 124. Source Streamlit - Cycle epargne
 Export : 124_cycle_epargne_streamlit
 Objectif : produire un fichier compte/mouvement pour alimenter les analyses du cycle epargne dans Streamlit.
 Lecture : une ligne represente un compte epargne et, s'il existe, un mouvement de la periode; les comptes sans mouvement restent visibles avec date_operation nulle.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle epargne dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle epargne
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
mouvements_periode AS (
  SELECT
    h.DATE_OPERATION,
    h.DATE_VALEUR,
    h.MONTANT_OPERATION,
    h.NUM_TRANSACTION,
    h.NUMERO_RECU,
    h.SENS,
    h.ID_COMPTE,
    h.ID_TYPE_OPERATION
  FROM dbo.HDPM AS h
  WHERE
    h.DATE_OPERATION >= @date_debut
    AND h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'

  UNION ALL

  SELECT
    h.DATE_OPERATION,
    h.DATE_OPERATION AS DATE_VALEUR,
    h.MONTANT_OPERATION,
    h.NUM_TRANSACTION,
    h.NUMERO_RECU,
    h.SENS,
    h.ID_COMPTE,
    h.ID_TYPE_OPERATION
  FROM dbo.HDPM_API AS h
  WHERE
    h.DATE_OPERATION >= @date_debut
    AND h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
),
soldes_source AS (
  SELECT
    h.ID_COMPTE,
    SUM(
      CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END
      * ISNULL(h.MONTANT_OPERATION, 0)
    ) AS solde_compte
  FROM dbo.HDPM AS h
  WHERE
    h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  GROUP BY
    h.ID_COMPTE

  UNION ALL

  SELECT
    h.ID_COMPTE,
    SUM(
      CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END
      * ISNULL(h.MONTANT_OPERATION, 0)
    ) AS solde_compte
  FROM dbo.HDPM_API AS h
  WHERE
    h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  GROUP BY
    h.ID_COMPTE
),
comptes_epargne_uniques AS (
  SELECT
    eev.*,
    ROW_NUMBER() OVER (
      PARTITION BY eev.id_compte
      ORDER BY
        CASE WHEN eev.date_cloture IS NULL THEN 0 ELSE 1 END,
        eev.date_cloture DESC,
        eev.date_last_modified DESC,
        eev.id_client
    ) AS rn_compte_reporting
  FROM base_epargnes AS eev
), soldes_compte AS (
  SELECT
    ss.ID_COMPTE AS id_compte,
    SUM(ss.solde_compte) AS solde_compte
  FROM soldes_source AS ss
  GROUP BY
    ss.ID_COMPTE
)
SELECT
  'epargne' AS cycle_activite,
  eev.num_compte,
  eev.code_client,
  LTRIM(RTRIM(CONCAT(ISNULL(eev.nom_client, ''), ' ', ISNULL(eev.prenoms_client, '')))) AS nom_client,
  eev.produit AS type_produit,
  eev.type_compte,
  eev.type_client,
  h.DATE_OPERATION AS date_operation,
  h.DATE_VALEUR AS date_valeur,
  CASE
    WHEN h.SENS = 'C'
    THEN 'Depot'
    WHEN h.SENS = 'D'
    THEN 'Retrait'
    ELSE h.ID_TYPE_OPERATION
  END AS type_operation,
  ABS(ISNULL(h.MONTANT_OPERATION, 0)) AS montant_operation,
  h.SENS AS sens_operation,
  ISNULL(sc.solde_compte, 0) AS solde_compte,
  eev.gestionnaire AS agent_credit,
  eev.collecteur,
  eev.telephone,
  eev.sexe,
  eev.zone AS zone_geographique,
  eev.status_compte AS statut_compte,
  eev.code_agence_compte AS code_agence,
  eev.nom_agence_compte AS agence,
  eev.code_devise,
  eev.date_ouverture,
  eev.date_cloture,
  h.NUM_TRANSACTION AS numero_reference,
  h.NUMERO_RECU AS numero_recu,
  eev.type_piece_identite,
  eev.numero_piece_identite,
  eev.categorie_client,
  eev.code_type_client
FROM comptes_epargne_uniques AS eev
LEFT JOIN soldes_compte AS sc
  ON sc.id_compte = eev.id_compte
LEFT JOIN mouvements_periode AS h
  ON h.ID_COMPTE = eev.id_compte
WHERE
  eev.rn_compte_reporting = 1
  AND eev.date_ouverture <= @date_fin
  AND (
    eev.date_cloture IS NULL OR eev.date_cloture >= @date_debut
  )
ORDER BY
  eev.nom_agence_compte,
  eev.code_client,
  eev.num_compte,
  h.DATE_OPERATION;

/*
 125. Source Streamlit - Cycle CRM clients
 Export : 125_cycle_crm_clients_streamlit
 Objectif : produire un fichier client complet pour les analyses CRM, KYC, segmentation et qualite de donnees.
 Lecture : une ligne represente un client Perfect, enrichi par la derniere activite epargne/credit visible avant @date_fin.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle CRM clients dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle CRM clients
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
derniere_operation_client AS (
  SELECT
    eev.id_client AS id_client,
    MAX(h.DATE_OPERATION) AS derniere_operation_epargne,
    COUNT(h.ID) AS nb_mouvements_epargne
  FROM base_epargnes AS eev
  LEFT JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = eev.id_compte
    AND h.DATE_OPERATION <= @date_fin
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  GROUP BY
    eev.id_client
), credits_client AS (
  SELECT
    ecv.id_client AS id_client,
    COUNT(DISTINCT ecv.id_pret) AS nb_credits,
    MAX(COALESCE(ecv.date_decaissement, ecv.date_effet)) AS derniere_date_credit
  FROM base_credits AS ecv
  WHERE
    COALESCE(ecv.date_decaissement, ecv.date_effet) <= @date_fin
  GROUP BY
    ecv.id_client
)
SELECT
  'crm_clients' AS cycle_activite,
  ecv.code_client,
  ecv.num_manuel,
  LTRIM(RTRIM(CONCAT(ISNULL(ecv.nom_client, ''), ' ', ISNULL(ecv.prenoms_client, '')))) AS nom_client,
  ecv.gestionnaire AS agent_credit,
  CAST(NULL AS VARCHAR(255)) AS [Origine du Prospect],
  ecv.email AS [E-mail],
  ecv.telephone,
  COALESCE(
    doc.derniere_operation_epargne,
    cc.derniere_date_credit,
    ecv.date_last_modified,
    ecv.date_adhesion
  ) AS date_operation,
  ecv.zone AS zone_geographique,
  ecv.categorie_client AS categorie,
  CAST(NULL AS FLOAT) AS revenu_mensuel,
  ecv.numero_piece_identite AS [Numero de la piece d'identite],
  ecv.type_piece_identite,
  CAST(NULL AS VARCHAR(20)) AS Locked,
  CAST(NULL AS VARCHAR(20)) AS [Rejet des mails],
  CAST(NULL AS VARCHAR(20)) AS [Mode Desabonne],
  ecv.sexe,
  ecv.civilite,
  ecv.statut_matrimonial,
  ecv.date_naissance,
  ecv.date_adhesion,
  ecv.age_adhesion AS age,
  ecv.profession AS activite_economique,
  ecv.type_client,
  ecv.code_type_client,
  ecv.code_categorie_client,
  ecv.adresse,
  ecv.ville,
  ecv.code_agence,
  ecv.nom_agence AS agence,
  ISNULL(doc.nb_mouvements_epargne, 0) AS nb_mouvements_epargne,
  ISNULL(cc.nb_credits, 0) AS nb_credits,
  ecv.client_perfect,
  ecv.client_tontine,
  ecv.collecteur,
  ecv.zone_collecte
FROM base_clients AS ecv
LEFT JOIN derniere_operation_client AS doc
  ON doc.id_client = ecv.id_client
LEFT JOIN credits_client AS cc
  ON cc.id_client = ecv.id_client
WHERE
  ecv.date_adhesion <= @date_fin
  AND (
    ecv.date_depart IS NULL OR ecv.date_depart >= @date_debut
  )
ORDER BY
  ecv.nom_agence,
  ecv.code_client;

/*
 126. Source Streamlit - Cycle operations depots et retraits
 Export : 126_cycle_operations_depot_retrait_streamlit
 Objectif : produire un fichier transactionnel depots/retraits directement exploitable dans le cycle operations_depot_retrait.
 Lecture : une ligne represente une operation client back-office ou API mobile, avec client, compte, utilisateur, validation et equilibre comptable.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle operations depot/retrait dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle operations depot/retrait
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
equilibre_back AS (
  SELECT
    h.ID_OPERATION AS ID_OPERATION,
    CASE
      WHEN ABS(
        SUM(
          CASE
            WHEN h.SENS = 'D'
            THEN ISNULL(h.MONTANT_OPERATION, 0)
            ELSE -ISNULL(h.MONTANT_OPERATION, 0)
          END
        )
      ) <= 0.01
      THEN 1
      ELSE 0
    END AS equilibre_comptable_ok
  FROM dbo.HDPM AS h
  GROUP BY
    h.ID_OPERATION
), equilibre_api AS (
  SELECT
    h.ID_OPERATION AS ID_OPERATION,
    CASE
      WHEN ABS(
        SUM(
          CASE
            WHEN h.SENS = 'D'
            THEN ISNULL(h.MONTANT_OPERATION, 0)
            ELSE -ISNULL(h.MONTANT_OPERATION, 0)
          END
        )
      ) <= 0.01
      THEN 1
      ELSE 0
    END AS equilibre_comptable_ok
  FROM dbo.HDPM_API AS h
  GROUP BY
    h.ID_OPERATION
), mouvements AS (
  SELECT
    'BACK_OFFICE' AS source_mouvement,
    o.ID AS operation_id,
    o.DATE_OPERATION AS date_operation,
    o.DATE_SAISIE AS date_saisie,
    o.DATE_VALIDATION AS date_validation,
    o.ID_TYPE_OPERATION AS type_operation,
    CASE
      WHEN o.ID_TYPE_OPERATION = 'DEPO'
      THEN 'Depot'
      WHEN o.ID_TYPE_OPERATION = 'RETR'
      THEN 'Retrait'
      ELSE o.ID_TYPE_OPERATION
    END AS type_mouvement,
    MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))) AS montant_operation,
    h.ID_DEVISE,
    d.CODE AS code_devise,
    o.ID_POINT_SERVICE,
    o.ID_UTILISATEUR,
    o.NUM_TRANSACTION AS numero_reference,
    o.NUMERO_RECU AS numero_recu,
    h.ID_COMPTE AS compte_id,
    ca.ID_ADHERENT AS client_id,
    ISNULL(o.ANNULE, 0) AS annule,
    eb.equilibre_comptable_ok
  FROM dbo.OPERATIONS AS o
  INNER JOIN dbo.HDPM AS h
    ON h.ID_OPERATION = o.ID
  INNER JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.id = h.ID_COMPTE
  LEFT JOIN dbo.DEVISES AS d
    ON d.ID = h.ID_DEVISE
  LEFT JOIN equilibre_back AS eb
    ON eb.ID_OPERATION = o.ID
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND o.ID_TYPE_OPERATION IN ('DEPO', 'RETR')
  GROUP BY
    o.ID,
    o.DATE_OPERATION,
    o.DATE_SAISIE,
    o.DATE_VALIDATION,
    o.ID_TYPE_OPERATION,
    h.ID_DEVISE,
    d.CODE,
    o.ID_POINT_SERVICE,
    o.ID_UTILISATEUR,
    o.NUM_TRANSACTION,
    o.NUMERO_RECU,
    h.ID_COMPTE,
    ca.ID_ADHERENT,
    o.ANNULE,
    eb.equilibre_comptable_ok
  UNION ALL
  SELECT
    'API_MOBILE',
    oa.CODE,
    oa.DATE_OPERATION,
    oa.DATE_SAISIE,
    oa.DATE_VALIDATION,
    oa.ID_TYPE_OPERATION,
    CASE
      WHEN oa.ID_TYPE_OPERATION = 'MOB_DEPO'
      THEN 'Depot mobile'
      WHEN oa.ID_TYPE_OPERATION = 'MOB_RETR'
      THEN 'Retrait mobile'
      ELSE oa.ID_TYPE_OPERATION
    END,
    MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))),
    h.ID_DEVISE,
    d.CODE,
    oa.ID_POINT_SERVICE,
    oa.ID_UTILISATEUR,
    oa.NUM_TRANSACTION,
    oa.NUMERO_RECU,
    h.ID_COMPTE,
    ca.ID_ADHERENT,
    ISNULL(oa.ANNULE, 0),
    ea.equilibre_comptable_ok
  FROM dbo.OPERATIONS_API AS oa
  INNER JOIN dbo.HDPM_API AS h
    ON h.ID_OPERATION = oa.CODE
  INNER JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.id = h.ID_COMPTE
  LEFT JOIN dbo.DEVISES AS d
    ON d.ID = h.ID_DEVISE
  LEFT JOIN equilibre_api AS ea
    ON ea.ID_OPERATION = oa.CODE
  WHERE
    oa.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND oa.ID_TYPE_OPERATION IN ('MOB_DEPO', 'MOB_RETR')
  GROUP BY
    oa.CODE,
    oa.DATE_OPERATION,
    oa.DATE_SAISIE,
    oa.DATE_VALIDATION,
    oa.ID_TYPE_OPERATION,
    h.ID_DEVISE,
    d.CODE,
    oa.ID_POINT_SERVICE,
    oa.ID_UTILISATEUR,
    oa.NUM_TRANSACTION,
    oa.NUMERO_RECU,
    h.ID_COMPTE,
    ca.ID_ADHERENT,
    oa.ANNULE,
    ea.equilibre_comptable_ok
)
SELECT
  'operations_depot_retrait' AS cycle_activite,
  m.date_operation,
  m.date_saisie,
  m.type_operation,
  m.type_mouvement,
  m.source_mouvement,
  m.montant_operation,
  m.code_devise,
  ps.NOM AS agence,
  u.LOGIN AS operateur,
  m.numero_reference,
  m.numero_recu,
  eev.num_compte,
  ecv.code_client,
  LTRIM(RTRIM(CONCAT(ISNULL(ecv.nom_client, ''), ' ', ISNULL(ecv.prenoms_client, '')))) AS nom_client,
  ecv.type_client,
  ecv.code_type_client,
  ecv.telephone,
  m.annule,
  CASE WHEN m.date_validation IS NULL THEN 1 ELSE 0 END AS operation_non_validee,
  CASE WHEN CAST(m.date_saisie AS DATE) > m.date_operation THEN 1 ELSE 0 END AS saisie_tardive,
  m.equilibre_comptable_ok,
  (
    CASE
      WHEN ecv.telephone IS NULL OR LTRIM(RTRIM(ecv.telephone)) = ''
      THEN 1
      ELSE 0
    END + CASE
      WHEN ecv.numero_piece_identite IS NULL OR LTRIM(RTRIM(ecv.numero_piece_identite)) = ''
      THEN 1
      ELSE 0
    END + CASE WHEN ecv.adresse IS NULL OR LTRIM(RTRIM(ecv.adresse)) = '' THEN 1 ELSE 0 END
  ) AS kyc_missing_count
FROM mouvements AS m
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = m.ID_POINT_SERVICE
LEFT JOIN dbo.UTILISATEURS AS u
  ON u.id = m.ID_UTILISATEUR
LEFT JOIN base_clients AS ecv
  ON ecv.id_client = m.client_id
LEFT JOIN base_epargnes AS eev
  ON eev.id_compte = m.compte_id
ORDER BY
  m.date_operation,
  m.source_mouvement,
  m.operation_id;

/*
 127. Source Streamlit - Cycle caisse et guichet
 Export : 127_cycle_caisse_et_guichet_streamlit
 Objectif : produire un fichier operationnel de caisse pour les analyses du cycle caisse.
 Lecture : une ligne represente un mouvement de caisse avec caisse, agence, caissier, encaisse de fin de jour et ecart de billetage lorsqu'il existe.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle caisse et guichet dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle caisse et guichet
 */
WITH operations_caisse_unifiees AS (
SELECT oc.ID, o.DATE_OPERATION, oc.SENS_OPERATION, oc.MONTANT, o.DESCRIPTION,
        ca.ID_CAISSE, ca.ID_POINT_SERVICE, ca.ID_DEVISE, oc.ID_CAISSE_AGENCE, oc.version ,
        tc.ID_CAISSE_AGENCE as ID_CONTRE_PARTIE, oc.ID_OPERATION, oc.ID_TYPE_OPERATION,
        o.NUM_TRANSACTION, o.ID_UTILISATEUR, o.DATE_SAISIE, o.DATE_VALIDATION
FROM OPERATIONS_CAIS oc 
inner join OPERATIONS o on (oc.ID_OPERATION = o.id) 
inner join CAISSES_AGENCE ca on (oc.ID_CAISSE_AGENCE = ca.ID)
left join TRANSFERTS_CAISSE tc on (oc.ID = tc.ID_OPERATION_CAIS)

UNION

SELECT oc.CODE, oc.DATE_OPERATION, oc.SENS_OPERATION, oc.MONTANT, o.DESCRIPTION,
        ca.ID_CAISSE, ca.ID_POINT_SERVICE, ca.ID_DEVISE, oc.ID_CAISSE_AGENCE,  1 as version,
        oc.ID_CONTRE_PARTIE, o.CODE as ID_OPERATION, oc.TYPE_OPERATION as ID_TYPE_OPERATION,
        o.NUM_TRANSACTION, u.ID as ID_UTILISATEUR, o.DATE_SAISIE, o.DATE_VALIDATION
FROM OPERATIONS_CAIS_API oc 
inner join CAISSES_AGENCE ca on (oc.ID_CAISSE_AGENCE = ca.ID)
inner join OPERATIONS_API o on (oc.ID_OPERATION = o.ID)
left join APP_USERS au on (au.ID = oc.ID_APP_USER)
left join UTILISATEURS u on (u.LOGIN = au.USERNAME)
),
billetage_arrete AS (
  SELECT
    acd.ID_ARRETE_CAISSE AS ID_ARRETE_CAISSE,
    SUM(ISNULL(acd.NBRE_PIECE, 0) * ISNULL(acd.PIECE, 0)) AS total_billetage
  FROM dbo.ARRETES_CAISSE_DET AS acd
  GROUP BY
    acd.ID_ARRETE_CAISSE
)
SELECT
  'caisse' AS cycle_activite,
  ps.NOM AS agence,
  ps.CODE AS code_agence,
  u.LOGIN AS caissier,
  ocv.DATE_OPERATION AS date_operation,
  ocv.ID_TYPE_OPERATION AS type_operation,
  ABS(ISNULL(ocv.MONTANT, 0)) AS montant_operation,
  c.LIBELLE AS libelle_caisse,
  dv.CODE AS devise,
  ocv.SENS_OPERATION,
  ac.SOLDE AS encaisse_fin_jour,
  ISNULL(ac.SOLDE, 0) - ISNULL(ba.total_billetage, 0) AS ecart_caisse,
  ocv.NUM_TRANSACTION AS numero_reference,
  ocv.DATE_SAISIE,
  ocv.DATE_VALIDATION,
  CASE WHEN ocv.ID_CONTRE_PARTIE IS NULL THEN 0 ELSE 1 END AS mouvement_transfert
FROM operations_caisse_unifiees AS ocv
LEFT JOIN dbo.CAISSES AS c
  ON c.ID = ocv.ID_CAISSE
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = ocv.ID_DEVISE
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = ocv.ID_POINT_SERVICE
LEFT JOIN dbo.UTILISATEURS AS u
  ON u.id = ocv.ID_UTILISATEUR
LEFT JOIN dbo.ARRETES_CAISSE AS ac
  ON ac.ID_CAISSE_AGENCE = ocv.ID_CAISSE_AGENCE
  AND ac.DATE_ARRETE = ocv.DATE_OPERATION
LEFT JOIN billetage_arrete AS ba
  ON ba.ID_ARRETE_CAISSE = ac.ID
WHERE
  ocv.DATE_OPERATION BETWEEN @date_debut AND @date_fin
ORDER BY
  ocv.DATE_OPERATION,
  ps.NOM,
  c.LIBELLE,
  ocv.ID_TYPE_OPERATION;

/*
 128. Source Streamlit - Cycle tresorerie et banque
 Export : 128_cycle_tresorerie_et_banque_streamlit
 Objectif : produire un fichier de mouvements de tresorerie/banque exploitable dans Streamlit.
 Lecture : s'appuie sur la CTE locale mouvements_comptables et les comptes dont le numero ou le libelle evoque banque, tresorerie ou caisse; ajuster le filtre selon le plan comptable local.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle tresorerie et banque dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle tresorerie et banque
 */
WITH mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
soldes_compte AS (
  SELECT
    h.ID_COMPTE AS ID_COMPTE,
    SUM(CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END * ISNULL(h.MONTANT_OPERATION, 0)) AS solde_banque
  FROM mouvements_comptables AS h
  WHERE
    h.DATE_OPERATION <= @date_fin
  GROUP BY
    h.ID_COMPTE
)
SELECT
  'tresorerie' AS cycle_activite,
  c.NUM_CPTE AS compte_bancaire,
  c.LIBELLE AS banque,
  h.DATE_OPERATION AS date_operation,
  ABS(ISNULL(h.MONTANT_OPERATION, 0)) AS montant_operation,
  dv.CODE AS devise,
  ISNULL(sc.solde_banque, 0) AS solde_banque,
  CAST(NULL AS FLOAT) AS ecart_rapprochement,
  h.SENS AS sens_operation,
  jo.LIBELLE AS journal,
  h.NUM_TRANSACTION AS numero_reference,
  h.NUMERO_RECU AS numero_recu,
  ps.NOM AS agence,
  h.DESCRIPTION AS commentaire
FROM mouvements_comptables AS h
LEFT JOIN dbo.COMPTES AS c
  ON c.ID = h.ID_COMPTE
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = h.ID_DEVISE
LEFT JOIN dbo.JOURNAUX_OPERATION AS jo
  ON jo.ID = h.ID_JOURNAL
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = h.ID_POINT_SERVICE
LEFT JOIN soldes_compte AS sc
  ON sc.ID_COMPTE = h.ID_COMPTE
WHERE
  h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
  AND (
    c.NUM_CPTE LIKE '5%'
    OR UPPER(ISNULL(c.LIBELLE, '')) LIKE '%BANQ%'
    OR UPPER(ISNULL(c.LIBELLE, '')) LIKE '%TRESOR%'
    OR UPPER(ISNULL(c.LIBELLE, '')) LIKE '%CAISSE%'
  )
ORDER BY
  h.DATE_OPERATION,
  c.NUM_CPTE,
  h.ID_OPERATION;

/*
 129. Source Streamlit - Cycle comptable et financier
 Export : 129_cycle_comptable_et_financier_streamlit
 Objectif : produire un journal comptable detaille pour les analyses du cycle comptable.
 Lecture : une ligne represente une ecriture HDPM/HDPM_API avec debit, credit, journal, compte et point de service.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle comptable et financier dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle comptable et financier
 */
WITH mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
)
SELECT
  'comptable' AS cycle_activite,
  h.ID AS reference_ecriture,
  jo.LIBELLE AS journal,
  c.NUM_CPTE AS compte_comptable,
  c.LIBELLE AS libelle_compte,
  h.DATE_OPERATION AS date_operation,
  CASE WHEN h.SENS = 'D' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END AS montant_debit,
  CASE WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END AS montant_credit,
  ps.NOM AS centre_cout,
  ps.CODE AS code_centre_cout,
  dv.CODE AS devise,
  h.ID_TYPE_OPERATION AS type_operation,
  typ.CLE_LIBELLE AS libelle_type_operation,
  h.NUM_TRANSACTION AS numero_reference,
  h.NUMERO_RECU AS numero_recu,
  h.DESCRIPTION AS commentaire,
  h.SENS AS sens_operation
FROM mouvements_comptables AS h
LEFT JOIN dbo.COMPTES AS c
  ON c.ID = h.ID_COMPTE
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = h.ID_DEVISE
LEFT JOIN dbo.JOURNAUX_OPERATION AS jo
  ON jo.ID = h.ID_JOURNAL
LEFT JOIN dbo.TYPES_OPERATION AS typ
  ON typ.ID = h.ID_TYPE_OPERATION
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = h.ID_POINT_SERVICE
WHERE
  h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
ORDER BY
  h.DATE_OPERATION,
  jo.LIBELLE,
  c.NUM_CPTE,
  h.ID;

/*
 130. Source Streamlit - Cycle ressources humaines et administration
 Export : 130_cycle_ressources_humaines_et_administration_streamlit
 Objectif : produire un fichier RH de base pour suivre effectifs, entrees, departs et rattachements.
 Lecture : une ligne represente un employe; le salaire reste nul si la paie n'est pas rattachee de facon fiable dans Perfect Vision.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle ressources humaines et administration dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle ressources humaines
 */
SELECT
  'rh_admin' AS cycle_activite,
  ps.NOM AS agence,
  CAST(NULL AS VARCHAR(255)) AS fonction,
  e.DATE_EMBAUCHE AS date_entree,
  CASE
    WHEN NOT e.DATE_DEPART IS NULL AND e.DATE_DEPART <= @date_fin
    THEN 'Sorti'
    ELSE 'Actif'
  END AS statut_agent,
  CAST(NULL AS FLOAT) AS salaire,
  e.NUM_MATRICULE,
  e.NUM_MANUEL,
  p.NOM,
  p.PRENOMS,
  CASE
    WHEN p.SEXE = 'SEXE_M'
    THEN 'Masculin'
    WHEN p.SEXE = 'SEXE_F'
    THEN 'Feminin'
    ELSE p.SEXE
  END AS sexe,
  p.DATE_NAISSANCE,
  e.ANCIENNETE,
  e.DATE_DEPART,
  de.DATE_DEBUT_PREAVIS,
  de.DUREE AS duree_preavis,
  u.LOGIN AS login_utilisateur,
  u.ACTIF AS utilisateur_actif
FROM dbo.EMPLOYES AS e
LEFT JOIN dbo.PERSONNES AS p
  ON p.ID = e.ID_PERSONNE
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = e.ID_AGENCE_PAIE
LEFT JOIN dbo.UTILISATEURS AS u
  ON u.id = e.ID_UTILISATEUR
LEFT JOIN dbo.DEPARTS_EMPLOYE AS de
  ON de.ID_EMPLOYE = e.ID
WHERE
  COALESCE(e.DATE_EMBAUCHE, e.DATE_DEPART, de.DATE_DEPART) <= @date_fin
  AND (
    e.DATE_DEPART IS NULL OR e.DATE_DEPART >= @date_debut
  )
ORDER BY
  ps.NOM,
  statut_agent,
  p.NOM,
  p.PRENOMS;

/*
 131. Source Streamlit - Cycle securite du systeme d'information
 Export : 131_cycle_securite_systeme_information_streamlit
 Objectif : produire un fichier utilisateurs/profils pour les analyses de securite SI.
 Lecture : une ligne represente un utilisateur et son profil/domaine lorsqu'il est renseigne; verifier les comptes actifs, expires, verrouilles ou sans profil.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle securite du systeme d'information dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle securite SI
 */
SELECT
  'si' AS cycle_activite,
  COALESCE(pf.LIBELLE, 'Sans profil') AS profil_acces,
  CAST(NULL AS DATE) AS date_activation,
  u.DATE_EXPIRATION AS date_revocation,
  COALESCE(pud.ID_DOMAINE, 'Perfect Vision') AS application_source,
  CAST(u.NIVEAU_SECURITE AS VARCHAR(255)) AS niveau_habilitation,
  u.LOGIN,
  u.NOM,
  u.PRENOM,
  u.EMAIL,
  u.ACTIF,
  u.CONNEXION_MULTIPLE,
  u.REINIT_MOT_DE_PASSE,
  u.VERROUILLE_JUSQUA,
  u.NIVEAU_VALIDATION_CREDIT,
  u.PLAFOND_MONTANT_DMD,
  CASE
    WHEN ISNULL(u.ACTIF, 0) = 0
    THEN 'Inactif'
    WHEN NOT u.DATE_EXPIRATION IS NULL AND u.DATE_EXPIRATION < @date_fin
    THEN 'Expire'
    WHEN NOT u.VERROUILLE_JUSQUA IS NULL AND u.VERROUILLE_JUSQUA > GETDATE()
    THEN 'Verrouille'
    WHEN pf.ID IS NULL
    THEN 'Actif sans profil visible'
    ELSE 'Actif'
  END AS statut_acces
FROM dbo.UTILISATEURS AS u
LEFT JOIN dbo.PROFILS_UTILISATEUR_DOMAINES AS pud
  ON pud.ID_UTILISATEUR = u.id
LEFT JOIN dbo.PROFILS AS pf
  ON pf.ID = pud.ID_PROFIL
ORDER BY
  statut_acces,
  u.LOGIN,
  application_source,
  profil_acces;

/*
 132. Source Streamlit - Cycle sauvegarde et continuite d'activite
 Export : 132_cycle_sauvegarde_et_continuite_activite_streamlit
 Objectif : produire un fichier proxy de continuite a partir des executions batch connues dans Perfect Vision.
 Lecture : Perfect Vision ne contient pas toujours les journaux de sauvegarde; ce SELECT exploite BATCH_JOB_EXECUTION comme indicateur technique a completer par les preuves de sauvegarde externes.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle sauvegarde et continuite d'activite dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle sauvegarde et continuite
 */
SELECT
  'continuite' AS cycle_activite,
  CAST(COALESCE(bje.START_TIME, bje.CREATE_TIME) AS DATE) AS date_sauvegarde,
  bji.JOB_NAME AS type_sauvegarde,
  'BATCH_JOB_EXECUTION' AS support_sauvegarde,
  bje.STATUS AS statut_test_reprise,
  CASE
    WHEN UPPER(ISNULL(bje.STATUS, '')) IN ('FAILED', 'STOPPED', 'UNKNOWN')
    THEN 1
    ELSE 0
  END AS incident_majeur,
  bje.JOB_EXECUTION_ID AS reference_execution,
  bje.START_TIME,
  bje.END_TIME,
  DATEDIFF(MINUTE, CAST(bje.START_TIME AS DATETIME2), CAST(bje.END_TIME AS DATETIME2)) AS duree_minutes,
  bje.EXIT_CODE,
  CAST(bje.EXIT_MESSAGE AS VARCHAR(2500)) AS commentaire,
  bje.LAST_UPDATED
FROM dbo.BATCH_JOB_EXECUTION AS bje
LEFT JOIN dbo.BATCH_JOB_INSTANCE AS bji
  ON bji.JOB_INSTANCE_ID = bje.JOB_INSTANCE_ID
WHERE
  CAST(COALESCE(bje.START_TIME, bje.CREATE_TIME) AS DATE) BETWEEN @date_debut AND @date_fin
ORDER BY
  COALESCE(bje.START_TIME, bje.CREATE_TIME) DESC,
  bji.JOB_NAME;

/*
 133. Source Streamlit - Cycle Likelemba
 Export : 133_cycle_likelemba_streamlit
 Objectif : produire un fichier consolide Likelemba/Tontine et credits Likelemba pour analyses de groupe, discipline de cycle et activite de collecte.
 Lecture : combine les credits dont le produit evoque Likelemba avec les cycles tontine; les colonnes non applicables sont laissees nulles.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle Likelemba dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle Likelemba
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
credits_likelemba AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
  WHERE
    UPPER(ISNULL(ecv.produit, '')) LIKE '%LIKELEMBA%'
), operations_tontine AS (
  SELECT
    ot.ID_CYCLE AS ID_CYCLE,
    COUNT(*) AS nb_operations_tontine,
    SUM(CASE WHEN ot.SENS_OPERATION = 'C' THEN ISNULL(ot.MONTANT, 0) ELSE 0 END) AS montant_entrees_tontine,
    SUM(CASE WHEN ot.SENS_OPERATION = 'D' THEN ISNULL(ot.MONTANT, 0) ELSE 0 END) AS montant_sorties_tontine
  FROM dbo.OPERATIONS_TNT AS ot
  LEFT JOIN dbo.OPERATIONS AS o
    ON o.ID = ot.ID_OPERATION
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND ISNULL(ot.ANNULE, 0) = 0
  GROUP BY
    ot.ID_CYCLE
)
SELECT
  'likelemba_credit' AS source_likelemba,
  'likelemba' AS cycle_activite,
  CASE WHEN cl.code_categorie_client = 'GPE' THEN cl.nom_client ELSE NULL END AS nom_groupe,
  cl.mtt_pret AS montant_demande,
  cl.mtt_pret AS montant_accorde,
  CAST(NULL AS FLOAT) AS revenu_mensuel,
  CAST(NULL AS FLOAT) AS charge_mensuelle,
  CAST(NULL AS INTEGER) AS retard_jours,
  CAST(NULL AS FLOAT) AS garantie,
  cl.objet_fin AS activite_economique,
  cl.date_demande,
  CASE
    WHEN NOT cl.date_solde IS NULL AND cl.date_solde <= @date_fin
    THEN 'Solde'
    WHEN NOT cl.date_perte IS NULL AND cl.date_perte <= @date_fin
    THEN 'Perte'
    ELSE 'Actif'
  END AS statut_dossier,
  CASE
    WHEN NOT cl.date_solde IS NULL AND cl.date_solde <= @date_fin
    THEN 'Solde'
    ELSE 'En remboursement'
  END AS statut_remboursement,
  cl.code_agence_demande AS code_agence,
  cl.nom_agence_demande AS agence,
  cl.gestionnaire_pret AS agent_credit,
  cl.produit AS type_produit,
  cl.code_client,
  cl.nom_client,
  cl.prenoms_client,
  cl.code_devise,
  CAST(NULL AS VARCHAR(255)) AS commentaire
FROM credits_likelemba AS cl
WHERE
  cl.rn = 1
  AND COALESCE(cl.date_decaissement, cl.date_effet, cl.date_demande) BETWEEN @date_debut AND @date_fin
UNION ALL
SELECT
  'tontine_cycle',
  'likelemba',
  ecv.nom_client,
  ct.MISE,
  ct.MISE,
  CAST(NULL AS FLOAT),
  CAST(NULL AS FLOAT),
  CASE
    WHEN ct.DATE_FIN < @date_fin AND ct.DATE_CLOTURE IS NULL
    THEN DATEDIFF(DAY, CAST(ct.DATE_FIN AS DATETIME2), CAST(@date_fin AS DATETIME2))
    ELSE 0
  END,
  CAST(NULL AS FLOAT),
  ecv.profession,
  ct.DATE_DEBUT,
  CASE
    WHEN NOT ct.DATE_CLOTURE IS NULL
    THEN 'Cycle cloture'
    WHEN ct.DATE_FIN < @date_fin
    THEN 'Cycle depasse non cloture'
    ELSE 'Cycle actif'
  END,
  CASE
    WHEN NOT ct.DATE_CLOTURE IS NULL
    THEN 'Solde'
    WHEN ct.DATE_FIN < @date_fin
    THEN 'En retard'
    ELSE 'A jour'
  END,
  ps.CODE,
  ps.NOM,
  ecv.collecteur,
  pt.LIBELLE,
  ecv.code_client,
  ecv.nom_client,
  ecv.prenoms_client,
  dv.CODE,
  CONCAT(
    'Operations tontine periode=',
    ISNULL(ot.nb_operations_tontine, 0),
    '; entrees=',
    ISNULL(ot.montant_entrees_tontine, 0),
    '; sorties=',
    ISNULL(ot.montant_sorties_tontine, 0)
  )
FROM dbo.CYCLES_TNT AS ct
LEFT JOIN operations_tontine AS ot
  ON ot.ID_CYCLE = ct.ID
LEFT JOIN dbo.PRODUITS_TNT AS pt
  ON pt.ID = ct.ID_PRODUIT_TNT
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = pt.ID_DEVISE
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = ct.ID_POINT_SERVICE
LEFT JOIN base_clients AS ecv
  ON ecv.id_client = ct.ID_TADHERENT
WHERE
  ct.DATE_DEBUT <= @date_fin
  AND (
    ct.DATE_CLOTURE IS NULL OR ct.DATE_CLOTURE >= @date_debut
  )
  AND (
    ct.DATE_FIN IS NULL OR ct.DATE_FIN >= @date_debut
  )
ORDER BY
  source_likelemba,
  agence,
  code_client,
  date_demande;

/*
 134. Source Streamlit - Cycle Money Provider
 Export : 134_cycle_money_provider_streamlit
 Objectif : produire un fichier transactionnel Money Provider pour les analyses du cycle money_provider.
 Lecture : une ligne represente une operation mobile issue de OPERATIONS_MOB_WS ou MOB_OPERATIONS, enrichie avec agent, client et compte lorsque disponibles.
 Niveau d'importance de la requete : 9
 Usage operationnel : Alimenter le fichier socle du cycle Money Provider dans Streamlit.
 Periodicite recommandee : A chaque televersement du cycle Money Provider
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
operations_mobile AS (
  SELECT
    'OPERATIONS_MOB_WS' AS source_operation,
    CAST(omw.ID AS VARCHAR(255)) AS id_operation_mobile,
    o.DATE_OPERATION,
    omw.SENS_OPERATION,
    omw.MONTANT,
    omw.MONTANT_COMMISSION,
    omw.NUMERO_RECU,
    omw.ID_COMPTE_EPG AS id_compte_client,
    omw.ID_COMPTE AS id_compte_provider,
    omw.ID_MOB_COMPTE,
    omw.ID_DEVISE,
    omw.ID_TYPE_OPERATION,
    o.NUM_TRANSACTION,
    o.DESCRIPTION
  FROM dbo.OPERATIONS_MOB_WS AS omw
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = omw.ID_OPERATION
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin AND ISNULL(o.ANNULE, 0) = 0
  UNION ALL
  SELECT
    'MOB_OPERATIONS',
    CAST(mo.ID AS VARCHAR(255)),
    o.DATE_OPERATION,
    mo.SENS_OPERATION,
    mo.MONTANT,
    CAST(NULL AS FLOAT),
    o.NUMERO_RECU,
    CAST(NULL AS VARCHAR(255)),
    mc.ID_COMPTE,
    mo.ID_MOB_COMPTE,
    mo.ID_DEVISE,
    mo.ID_TYPE_OPERATION,
    o.NUM_TRANSACTION,
    o.DESCRIPTION
  FROM dbo.MOB_OPERATIONS AS mo
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = mo.ID_OPERATION
  LEFT JOIN dbo.MOB_COMPTES AS mc
    ON mc.ID = mo.ID_MOB_COMPTE
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin AND ISNULL(o.ANNULE, 0) = 0
)
SELECT
  'money_provider' AS cycle_activite,
  om.DATE_OPERATION AS date_operation,
  om.ID_TYPE_OPERATION AS type_operation,
  ABS(ISNULL(om.MONTANT, 0)) AS montant_operation,
  om.NUM_TRANSACTION AS numero_reference,
  eev.telephone AS telephone,
  COALESCE(eev.nom_agence_compte, ma.CODE_AGENCE) AS agence,
  CONCAT(ma.NOM, ' ', ma.PRENOMS) AS operateur,
  CAST(NULL AS VARCHAR(255)) AS tresorier,
  om.source_operation AS journal_transaction,
  CAST(NULL AS FLOAT) AS solde_initial,
  CAST(NULL AS FLOAT) AS solde_final,
  om.DESCRIPTION AS commentaire,
  om.SENS_OPERATION,
  om.MONTANT_COMMISSION AS montant_commission,
  dv.CODE AS code_devise,
  om.NUMERO_RECU AS numero_recu,
  eev.code_client,
  LTRIM(RTRIM(CONCAT(ISNULL(eev.nom_client, ''), ' ', ISNULL(eev.prenoms_client, '')))) AS nom_client,
  eev.type_client,
  eev.num_compte AS num_compte_client,
  cp.NUM_CPTE AS num_compte_provider,
  ma.CODE_AGENCE AS code_agence_agent_mobile
FROM operations_mobile AS om
LEFT JOIN dbo.MOB_COMPTES AS mc
  ON mc.ID = om.ID_MOB_COMPTE
LEFT JOIN dbo.MOB_AGENTS AS ma
  ON ma.ID = mc.ID_AGENT
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = om.ID_DEVISE
LEFT JOIN base_epargnes AS eev
  ON eev.id_compte = om.id_compte_client
LEFT JOIN dbo.COMPTES AS cp
  ON cp.ID = om.id_compte_provider
ORDER BY
  om.DATE_OPERATION,
  om.source_operation,
  om.ID_TYPE_OPERATION,
  om.id_operation_mobile;

/*
 135. Caisses sans arrete quotidien sur la periode
 Export : 135_cycle_caisse_et_guichet_caisses_sans_arrete_quotidien_sur_la_periode
 Objectif : verifier que chaque caisse agence/devise dispose d'un arrete journalier sur la periode, en priorisant les caisses qui ont eu des mouvements.
 Lecture : construit le calendrier entre @date_debut et @date_fin, croise avec les caisses agence, puis signale les jours sans ARRETES_CAISSE. Les mouvements de la CTE locale operations_caisse_unifiees donnent la criticite du manquement.
 Niveau d'importance de la requete : 10
 Usage operationnel : verifier que chaque caisse agence/devise dispose d'un arrete journalier sur la periode, en priorisant les caisses qui ont eu des mouvements.
 Periodicite recommandee : Quotidien en caisse, avec synthese hebdomadaire
 */
WITH operations_caisse_unifiees AS (
SELECT oc.ID, o.DATE_OPERATION, oc.SENS_OPERATION, oc.MONTANT, o.DESCRIPTION,
        ca.ID_CAISSE, ca.ID_POINT_SERVICE, ca.ID_DEVISE, oc.ID_CAISSE_AGENCE, oc.version ,
        tc.ID_CAISSE_AGENCE as ID_CONTRE_PARTIE, oc.ID_OPERATION, oc.ID_TYPE_OPERATION,
        o.NUM_TRANSACTION, o.ID_UTILISATEUR, o.DATE_SAISIE, o.DATE_VALIDATION
FROM OPERATIONS_CAIS oc 
inner join OPERATIONS o on (oc.ID_OPERATION = o.id) 
inner join CAISSES_AGENCE ca on (oc.ID_CAISSE_AGENCE = ca.ID)
left join TRANSFERTS_CAISSE tc on (oc.ID = tc.ID_OPERATION_CAIS)

UNION

SELECT oc.CODE, oc.DATE_OPERATION, oc.SENS_OPERATION, oc.MONTANT, o.DESCRIPTION,
        ca.ID_CAISSE, ca.ID_POINT_SERVICE, ca.ID_DEVISE, oc.ID_CAISSE_AGENCE,  1 as version,
        oc.ID_CONTRE_PARTIE, o.CODE as ID_OPERATION, oc.TYPE_OPERATION as ID_TYPE_OPERATION,
        o.NUM_TRANSACTION, u.ID as ID_UTILISATEUR, o.DATE_SAISIE, o.DATE_VALIDATION
FROM OPERATIONS_CAIS_API oc 
inner join CAISSES_AGENCE ca on (oc.ID_CAISSE_AGENCE = ca.ID)
inner join OPERATIONS_API o on (oc.ID_OPERATION = o.ID)
left join APP_USERS au on (au.ID = oc.ID_APP_USER)
left join UTILISATEURS u on (u.LOGIN = au.USERNAME)
),
calendrier AS (
  SELECT
    @date_debut AS date_controle
  UNION ALL
  SELECT
    DATEADD(DAY, 1, date_controle)
  FROM calendrier
  WHERE
    date_controle < @date_fin
), mouvements_jour AS (
  SELECT
    CAST(ocv.DATE_OPERATION AS DATE) AS date_controle,
    ocv.ID_CAISSE_AGENCE AS ID_CAISSE_AGENCE,
    COUNT(*) AS nb_mouvements_caisse,
    SUM(ABS(ISNULL(ocv.MONTANT, 0))) AS montant_mouvements_caisse,
    SUM(
      CASE
        WHEN UPPER(ISNULL(ocv.SENS_OPERATION, '')) IN ('C', 'CREDIT', 'ENTREE', 'ENTREE_CAISSE')
        THEN ABS(ISNULL(ocv.MONTANT, 0))
        ELSE 0
      END
    ) AS total_entrees_caisse,
    SUM(
      CASE
        WHEN UPPER(ISNULL(ocv.SENS_OPERATION, '')) IN ('D', 'DEBIT', 'SORTIE', 'SORTIE_CAISSE')
        THEN ABS(ISNULL(ocv.MONTANT, 0))
        ELSE 0
      END
    ) AS total_sorties_caisse
  FROM operations_caisse_unifiees AS ocv
  WHERE
    CAST(ocv.DATE_OPERATION AS DATE) BETWEEN @date_debut AND @date_fin
    AND NOT ocv.ID_CAISSE_AGENCE IS NULL
  GROUP BY
    CAST(ocv.DATE_OPERATION AS DATE),
    ocv.ID_CAISSE_AGENCE
), arretes_jour AS (
  SELECT
    ac.DATE_ARRETE AS date_controle,
    ac.ID_CAISSE_AGENCE AS ID_CAISSE_AGENCE,
    COUNT(*) AS nb_arretes,
    MAX(ac.ID) AS dernier_id_arrete,
    SUM(ISNULL(ac.SOLDE, 0)) AS solde_arrete,
    SUM(ISNULL(ac.SOLDE_TRANSFERT, 0)) AS solde_transfert_arrete
  FROM dbo.ARRETES_CAISSE AS ac
  WHERE
    ac.DATE_ARRETE BETWEEN @date_debut AND @date_fin
  GROUP BY
    ac.DATE_ARRETE,
    ac.ID_CAISSE_AGENCE
)
SELECT
  cal.date_controle,
  ps.CODE AS code_agence,
  ps.NOM AS nom_agence,
  c.LIBELLE AS caisse,
  dv.CODE AS code_devise,
  ca.BILLETAGE AS billetage_requis,
  ISNULL(mj.nb_mouvements_caisse, 0) AS nb_mouvements_caisse,
  ISNULL(mj.montant_mouvements_caisse, 0) AS montant_mouvements_caisse,
  ISNULL(mj.total_entrees_caisse, 0) AS total_entrees_caisse,
  ISNULL(mj.total_sorties_caisse, 0) AS total_sorties_caisse,
  ISNULL(aj.nb_arretes, 0) AS nb_arretes,
  aj.dernier_id_arrete,
  aj.solde_arrete,
  aj.solde_transfert_arrete,
  CASE
    WHEN ISNULL(mj.nb_mouvements_caisse, 0) > 0
    THEN 10
    WHEN ISNULL(ca.BILLETAGE, 0) = 1
    THEN 7
    ELSE 5
  END AS priorite_controle,
  CASE
    WHEN ISNULL(mj.nb_mouvements_caisse, 0) > 0
    THEN 'Mouvements sans arrete de caisse'
    WHEN ISNULL(ca.BILLETAGE, 0) = 1
    THEN 'Caisse avec billetage sans arrete'
    ELSE 'Aucun arrete renseigne'
  END AS statut_cloture
FROM calendrier AS cal
CROSS JOIN dbo.CAISSES_AGENCE AS ca
LEFT JOIN dbo.CAISSES AS c
  ON c.ID = ca.ID_CAISSE
LEFT JOIN dbo.POINTS_SERVICE AS ps
  ON ps.ID = ca.ID_POINT_SERVICE
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = ca.ID_DEVISE
LEFT JOIN mouvements_jour AS mj
  ON mj.date_controle = cal.date_controle AND mj.ID_CAISSE_AGENCE = ca.ID
LEFT JOIN arretes_jour AS aj
  ON aj.date_controle = cal.date_controle AND aj.ID_CAISSE_AGENCE = ca.ID
WHERE
  ISNULL(aj.nb_arretes, 0) = 0 AND ISNULL(c.INACTIF, 0) = 0
ORDER BY
  cal.date_controle,
  priorite_controle DESC,
  ps.CODE,
  c.LIBELLE,
  dv.CODE OPTION(
    MAXRECURSION 0
);

/*
 136. Remboursements credit encaisses mais non imputes correctement au pret
 Export : 136_cycle_credit_remboursements_credit_encaisses_mais_non_imputes_correctement_au_pret
 Objectif : identifier les remboursements credit visibles dans OPERATIONS_CRD mais absents, incomplets ou incoherents dans la ventilation REMBOURS_CRD.
 Lecture : en microfinance, ce controle protege le client et le portefeuille credit. Un remboursement encaisse mais mal impute peut laisser le client en retard, fausser le PAR et provoquer un suivi de recouvrement injustifie.
 Niveau d'importance de la requete : 10
 Usage operationnel : identifier les remboursements credit visibles dans OPERATIONS_CRD mais absents, incomplets ou incoherents dans la ventilation REMBOURS_CRD.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
ventilation_remboursement AS (
  SELECT
    rc.ID_OPERATION_CRD AS ID_OPERATION_CRD,
    COUNT(*) AS nb_lignes_imputation,
    COUNT(DISTINCT rc.ID_TABAMORT) AS nb_echeances_imputees,
    MIN(t.DATE_ECHEANCE) AS premiere_echeance_imputee,
    MAX(t.DATE_ECHEANCE) AS derniere_echeance_imputee,
    SUM(ISNULL(rc.CAPITAL, 0)) AS capital_impute,
    SUM(ISNULL(rc.INTERET, 0)) AS interet_impute,
    SUM(ISNULL(rc.COMMISSION, 0)) AS commission_imputee,
    SUM(ISNULL(rc.EPARGNE, 0)) AS epargne_imputee,
    SUM(ISNULL(rc.PENALITE, 0)) AS penalite_imputee,
    SUM(
      ISNULL(rc.CAPITAL, 0) + ISNULL(rc.INTERET, 0) + ISNULL(rc.COMMISSION, 0) + ISNULL(rc.EPARGNE, 0) + ISNULL(rc.PENALITE, 0)
    ) AS total_impute
  FROM dbo.REMBOURS_CRD AS rc
  LEFT JOIN dbo.TABAMOR AS t
    ON t.ID = rc.ID_TABAMORT
  GROUP BY
    rc.ID_OPERATION_CRD
), operations_remboursement AS (
  SELECT
    oc.ID AS id_operation_credit,
    o.ID AS id_operation,
    o.DATE_OPERATION AS DATE_OPERATION,
    o.DATE_SAISIE AS DATE_SAISIE,
    o.DATE_VALIDATION AS DATE_VALIDATION,
    o.NUM_TRANSACTION AS NUM_TRANSACTION,
    o.NUMERO_RECU AS NUMERO_RECU,
    o.DESCRIPTION AS DESCRIPTION,
    o.ID_TYPE_OPERATION AS ID_TYPE_OPERATION,
    o.ID_UTILISATEUR AS ID_UTILISATEUR,
    o.ID_UTILISATEUR_VALIDE AS ID_UTILISATEUR_VALIDE,
    ISNULL(o.ANNULE, 0) AS operation_annulee,
    oc.SENS_OPERATION AS SENS_OPERATION,
    COALESCE(NULLIF(oc.MONTANT_TOTAL, 0), oc.MONTANT, 0) AS montant_operation_credit,
    oc.MONTANT AS montant_operation_base,
    oc.MONTANT_TOTAL AS MONTANT_TOTAL,
    oc.IMPAYE AS impaye_apres_operation,
    oc.REMB_ANTICIPER AS remboursement_anticipe,
    oc.ID_PRET AS ID_PRET,
    oc.ID_COMPTE_CREDIT AS ID_COMPTE_CREDIT,
    COALESCE(oc.ID_DEVISE, oc.devise, p.ID_DEVISE) AS id_devise,
    p.NUMERO_PRET AS NUMERO_PRET,
    p.NUMERO_CONTRAT AS NUMERO_CONTRAT,
    p.DATE_DECAISSEMENT AS DATE_DECAISSEMENT,
    p.DATE_EFFET AS DATE_EFFET,
    p.DATE_SOLDE AS DATE_SOLDE,
    p.MONTANT AS montant_initial_pret,
    dc.ID_ADHERENT AS ID_ADHERENT
  FROM dbo.OPERATIONS_CRD AS oc
  LEFT JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  LEFT JOIN dbo.PRETS AS p
    ON p.ID = oc.ID_PRET
  LEFT JOIN dbo.DOSSIERS_CREDIT AS d
    ON d.ID = p.ID_DOSSIER_CREDIT
  LEFT JOIN dbo.DEMANDES_CREDIT AS dc
    ON dc.ID = d.ID_DEMANDE
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND UPPER(ISNULL(oc.SENS_OPERATION, '')) IN ('C', 'CREDIT')
)
SELECT
  opr.DATE_OPERATION AS date_remboursement,
  opr.DATE_SAISIE,
  opr.DATE_VALIDATION,
  opr.NUM_TRANSACTION,
  opr.NUMERO_RECU,
  opr.ID_TYPE_OPERATION AS type_operation,
  opr.SENS_OPERATION,
  opr.NUMERO_PRET,
  opr.NUMERO_CONTRAT,
  opr.DATE_DECAISSEMENT,
  opr.DATE_EFFET,
  opr.DATE_SOLDE,
  opr.montant_initial_pret,
  dv.CODE AS code_devise,
  ecv.code_client,
  ecv.nom_client,
  ecv.prenoms_client,
  ecv.code_type_client,
  ecv.type_client,
  cc.NUM_CPTE AS numero_compte_credit,
  opr.montant_operation_credit,
  ISNULL(vr.total_impute, 0) AS total_impute,
  opr.montant_operation_credit - ISNULL(vr.total_impute, 0) AS ecart_non_impute,
  ISNULL(vr.capital_impute, 0) AS capital_impute,
  ISNULL(vr.interet_impute, 0) AS interet_impute,
  ISNULL(vr.commission_imputee, 0) AS commission_imputee,
  ISNULL(vr.epargne_imputee, 0) AS epargne_imputee,
  ISNULL(vr.penalite_imputee, 0) AS penalite_imputee,
  ISNULL(vr.nb_lignes_imputation, 0) AS nb_lignes_imputation,
  ISNULL(vr.nb_echeances_imputees, 0) AS nb_echeances_imputees,
  vr.premiere_echeance_imputee,
  vr.derniere_echeance_imputee,
  opr.impaye_apres_operation,
  opr.remboursement_anticipe,
  opr.DESCRIPTION,
  CASE
    WHEN opr.ID_PRET IS NULL
    THEN 'Remboursement sans pret rattache'
    WHEN opr.DATE_VALIDATION IS NULL
    THEN 'Remboursement non valide'
    WHEN ISNULL(vr.nb_lignes_imputation, 0) = 0
    THEN 'Remboursement sans ventilation REMBOURS_CRD'
    WHEN ISNULL(vr.nb_echeances_imputees, 0) = 0
    THEN 'Remboursement sans echeance rattachee'
    WHEN ABS(opr.montant_operation_credit - ISNULL(vr.total_impute, 0)) > 0.01
    THEN 'Ecart entre montant encaisse et montant impute'
    ELSE 'Imputation a verifier'
  END AS statut_imputation
FROM operations_remboursement AS opr
LEFT JOIN ventilation_remboursement AS vr
  ON vr.ID_OPERATION_CRD = opr.id_operation_credit
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = opr.id_devise
LEFT JOIN dbo.COMPTES AS cc
  ON cc.ID = opr.ID_COMPTE_CREDIT
LEFT JOIN base_clients AS ecv
  ON ecv.id_client = opr.ID_ADHERENT
WHERE
  opr.ID_PRET IS NULL
  OR opr.DATE_VALIDATION IS NULL
  OR ISNULL(vr.nb_lignes_imputation, 0) = 0
  OR ISNULL(vr.nb_echeances_imputees, 0) = 0
  OR ABS(opr.montant_operation_credit - ISNULL(vr.total_impute, 0)) > 0.01
ORDER BY
  ABS(opr.montant_operation_credit - ISNULL(vr.total_impute, 0)) DESC,
  opr.DATE_OPERATION,
  ecv.code_client,
  opr.NUMERO_PRET;

/*
 137. Depots et retraits epargne avec sens comptable incoherent
 Export : 137_cycle_epargne_depots_et_retraits_epargne_avec_sens_comptable_incoherent
 Objectif : verifier que les depots creditent le compte client et que les retraits le debitent dans les mouvements comptables.
 Lecture : rapproche OPERATIONS_EPG avec la CTE locale mouvements_comptables sur le compte client. En microfinance, une mauvaise orientation debit/credit fausse directement le solde du membre.
 Niveau d'importance de la requete : 10
 Usage operationnel : verifier que les depots creditent le compte client et que les retraits le debitent dans les mouvements comptables.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
mouvements_client AS (
  SELECT
    h.ID_OPERATION AS ID_OPERATION,
    h.ID_COMPTE AS ID_COMPTE,
    h.ID_DEVISE AS ID_DEVISE,
    SUM(CASE WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS montant_credit_client,
    SUM(CASE WHEN h.SENS = 'D' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS montant_debit_client,
    COUNT(*) AS nb_lignes_comptables_client
  FROM mouvements_comptables AS h
  WHERE
    h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
  GROUP BY
    h.ID_OPERATION,
    h.ID_COMPTE,
    h.ID_DEVISE
), operations_epargne AS (
  SELECT
    oe.ID AS id_operation_epargne,
    o.ID AS id_operation,
    o.DATE_OPERATION AS DATE_OPERATION,
    o.DATE_SAISIE AS DATE_SAISIE,
    o.DATE_VALIDATION AS DATE_VALIDATION,
    o.NUM_TRANSACTION AS NUM_TRANSACTION,
    o.NUMERO_RECU AS NUMERO_RECU,
    o.DESCRIPTION AS DESCRIPTION,
    oe.ID_TYPE_OPERATION AS ID_TYPE_OPERATION,
    UPPER(ISNULL(oe.SENS_OPERATION, '')) AS sens_attendu,
    oe.MONTANT AS MONTANT,
    oe.ID_COMPTE_EPG AS ID_COMPTE_EPG,
    oe.ID_DEVISE AS ID_DEVISE,
    oe.NOM_DEPOSANT_RETIRANT AS NOM_DEPOSANT_RETIRANT,
    oe.TELEPHONE AS TELEPHONE,
    ISNULL(o.ANNULE, 0) AS operation_annulee
  FROM dbo.OPERATIONS_EPG AS oe
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oe.ID_OPERATION
  WHERE
    o.DATE_OPERATION BETWEEN @date_debut AND @date_fin AND ISNULL(o.ANNULE, 0) = 0
)
SELECT
  oe.DATE_OPERATION,
  oe.DATE_SAISIE,
  oe.DATE_VALIDATION,
  oe.NUM_TRANSACTION,
  oe.NUMERO_RECU,
  oe.ID_TYPE_OPERATION AS type_operation,
  oe.sens_attendu,
  dv.CODE AS code_devise,
  eev.code_client,
  eev.nom_client,
  eev.prenoms_client,
  eev.type_client,
  eev.num_compte,
  eev.produit,
  oe.MONTANT AS montant_operation,
  ISNULL(mc.montant_credit_client, 0) AS montant_credit_client,
  ISNULL(mc.montant_debit_client, 0) AS montant_debit_client,
  ISNULL(mc.nb_lignes_comptables_client, 0) AS nb_lignes_comptables_client,
  oe.NOM_DEPOSANT_RETIRANT,
  oe.TELEPHONE,
  oe.DESCRIPTION,
  CASE
    WHEN mc.ID_OPERATION IS NULL
    THEN 'Aucune ligne comptable sur le compte client'
    WHEN oe.sens_attendu IN ('C', 'CREDIT')
    AND ABS(ISNULL(oe.MONTANT, 0) - ISNULL(mc.montant_credit_client, 0)) > 0.01
    THEN 'Depot non credite correctement'
    WHEN oe.sens_attendu IN ('D', 'DEBIT')
    AND ABS(ISNULL(oe.MONTANT, 0) - ISNULL(mc.montant_debit_client, 0)) > 0.01
    THEN 'Retrait non debite correctement'
    ELSE 'Sens comptable a verifier'
  END AS statut_controle
FROM operations_epargne AS oe
LEFT JOIN mouvements_client AS mc
  ON mc.ID_OPERATION = oe.id_operation
  AND mc.ID_COMPTE = oe.ID_COMPTE_EPG
  AND mc.ID_DEVISE = oe.ID_DEVISE
LEFT JOIN base_epargnes AS eev
  ON eev.id_compte = oe.ID_COMPTE_EPG
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = oe.ID_DEVISE
WHERE
  oe.sens_attendu IN ('C', 'CREDIT', 'D', 'DEBIT')
  AND (
    mc.ID_OPERATION IS NULL
    OR (
      oe.sens_attendu IN ('C', 'CREDIT')
      AND ABS(ISNULL(oe.MONTANT, 0) - ISNULL(mc.montant_credit_client, 0)) > 0.01
    )
    OR (
      oe.sens_attendu IN ('D', 'DEBIT')
      AND ABS(ISNULL(oe.MONTANT, 0) - ISNULL(mc.montant_debit_client, 0)) > 0.01
    )
  )
ORDER BY
  oe.DATE_OPERATION,
  eev.code_client,
  ABS(
    ISNULL(oe.MONTANT, 0) - CASE
      WHEN oe.sens_attendu IN ('C', 'CREDIT')
      THEN ISNULL(mc.montant_credit_client, 0)
      ELSE ISNULL(mc.montant_debit_client, 0)
    END
  ) DESC;

/*
 138. Comptes epargne avec solde negatif apres mouvement debit
 Export : 138_cycle_epargne_comptes_epargne_avec_solde_negatif_apres_mouvement_debit
 Objectif : detecter les retraits ou debits qui font passer un compte epargne client en solde negatif.
 Lecture : reconstruit le solde avant periode puis applique les mouvements de la CTE locale mouvements_comptables dans l'ordre chronologique. Sauf autorisation de decouvert, un solde negatif est un risque client et caisse.
 Niveau d'importance de la requete : 10
 Usage operationnel : detecter les retraits ou debits qui font passer un compte epargne client en solde negatif.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
comptes_epargne AS (
  SELECT
    eev.id_compte AS id_compte,
    eev.num_compte AS num_compte,
    eev.id_client AS id_client,
    eev.code_client AS code_client,
    eev.nom_client AS nom_client,
    eev.prenoms_client AS prenoms_client,
    eev.type_client AS type_client,
    eev.produit AS produit,
    eev.code_devise AS code_devise,
    pe.OPERATION_DECOUVERT AS OPERATION_DECOUVERT,
    pe.MONTANT_MAX_DECOUVERT AS MONTANT_MAX_DECOUVERT
  FROM base_epargnes AS eev
  LEFT JOIN dbo.COMPTES_ADHERENT_INFO AS cai
    ON cai.id = eev.id_compte
  LEFT JOIN dbo.PRODUITS_EPG AS pe
    ON pe.ID = cai.ID_PRODUIT_EPG
), solde_avant AS (
  SELECT
    h.ID_COMPTE AS ID_COMPTE,
    SUM(CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END * ISNULL(h.MONTANT_OPERATION, 0)) AS solde_avant_periode
  FROM mouvements_comptables AS h
  WHERE
    h.DATE_OPERATION < @date_debut
  GROUP BY
    h.ID_COMPTE
), mouvements_periode AS (
  SELECT
    h.ID AS ID,
    h.ID_COMPTE AS ID_COMPTE,
    h.DATE_OPERATION AS DATE_OPERATION,
    h.DATE_SAISIE AS DATE_SAISIE,
    h.NUM_LIGNE AS NUM_LIGNE,
    h.ID_OPERATION AS ID_OPERATION,
    h.NUM_TRANSACTION AS NUM_TRANSACTION,
    h.NUMERO_RECU AS NUMERO_RECU,
    h.ID_TYPE_OPERATION AS ID_TYPE_OPERATION,
    h.SENS AS SENS,
    h.DESCRIPTION AS DESCRIPTION,
    ISNULL(h.MONTANT_OPERATION, 0) AS montant_operation,
    CASE WHEN h.SENS = 'D' THEN -1 ELSE 1 END * ISNULL(h.MONTANT_OPERATION, 0) AS montant_signe
  FROM mouvements_comptables AS h
  WHERE
    h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
), mouvements_avec_solde AS (
  SELECT
    mp.*,
    ISNULL(sa.solde_avant_periode, 0) AS solde_avant_periode,
    ISNULL(sa.solde_avant_periode, 0) + SUM(mp.montant_signe) OVER (
      PARTITION BY mp.ID_COMPTE
      ORDER BY mp.DATE_OPERATION, ISNULL(mp.NUM_LIGNE, 0), mp.ID
      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS solde_apres_mouvement
  FROM mouvements_periode AS mp
  LEFT JOIN solde_avant AS sa
    ON sa.ID_COMPTE = mp.ID_COMPTE
)
SELECT
  mas.DATE_OPERATION,
  mas.DATE_SAISIE,
  mas.NUM_TRANSACTION,
  mas.NUMERO_RECU,
  mas.ID_TYPE_OPERATION AS type_operation,
  ce.code_client,
  ce.nom_client,
  ce.prenoms_client,
  ce.type_client,
  ce.num_compte,
  ce.produit,
  ce.code_devise,
  mas.SENS,
  mas.montant_operation,
  mas.solde_avant_periode,
  mas.solde_apres_mouvement,
  ce.OPERATION_DECOUVERT,
  ce.MONTANT_MAX_DECOUVERT,
  mas.DESCRIPTION,
  CASE
    WHEN ISNULL(ce.OPERATION_DECOUVERT, 0) = 1
    THEN 'Solde negatif avec produit autorisant potentiellement le decouvert'
    ELSE 'Solde negatif non autorise a verifier'
  END AS statut_controle
FROM mouvements_avec_solde AS mas
INNER JOIN comptes_epargne AS ce
  ON ce.id_compte = mas.ID_COMPTE
WHERE
  mas.SENS = 'D' AND mas.solde_apres_mouvement < -0.01
ORDER BY
  mas.solde_apres_mouvement,
  mas.DATE_OPERATION,
  ce.code_client;

/*
 139. Annulations non symetriques dans les mouvements comptables
 Export : 139_cycle_comptable_et_financier_annulations_non_symetriques_dans_les_mouvements_comptables
 Objectif : verifier qu'une operation d'annulation inverse exactement les mouvements comptables de l'operation initiale.
 Lecture : compare les lignes de la CTE locale mouvements_comptables pour l'operation annulee et l'operation d'annulation, par compte et devise.
 Niveau d'importance de la requete : 10
 Usage operationnel : verifier qu'une operation d'annulation inverse exactement les mouvements comptables de l'operation initiale.
 Periodicite recommandee : Hebdomadaire
 */
WITH mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
operations_annulation AS (
  SELECT
    oa.ID AS id_operation_annulation,
    oa.DATE_OPERATION AS date_annulation,
    oa.NUM_TRANSACTION AS num_transaction_annulation,
    oa.NUMERO_RECU AS numero_recu_annulation,
    oa.ID_OPERATION_ANNULE AS id_operation_origine,
    oo.DATE_OPERATION AS date_operation_origine,
    oo.NUM_TRANSACTION AS num_transaction_origine,
    oo.NUMERO_RECU AS numero_recu_origine
  FROM dbo.OPERATIONS AS oa
  LEFT JOIN dbo.OPERATIONS AS oo
    ON oo.ID = oa.ID_OPERATION_ANNULE
  WHERE
    oa.DATE_OPERATION BETWEEN @date_debut AND @date_fin
    AND NOT oa.ID_OPERATION_ANNULE IS NULL
), lignes_origine AS (
  SELECT
    h.ID_OPERATION AS ID_OPERATION,
    h.ID_COMPTE AS ID_COMPTE,
    h.ID_DEVISE AS ID_DEVISE,
    SUM(CASE WHEN h.SENS = 'D' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS debit_origine,
    SUM(CASE WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS credit_origine,
    COUNT(*) AS nb_lignes_origine
  FROM mouvements_comptables AS h
  INNER JOIN operations_annulation AS oa
    ON oa.id_operation_origine = h.ID_OPERATION
  GROUP BY
    h.ID_OPERATION,
    h.ID_COMPTE,
    h.ID_DEVISE
), lignes_annulation AS (
  SELECT
    h.ID_OPERATION AS ID_OPERATION,
    h.ID_COMPTE AS ID_COMPTE,
    h.ID_DEVISE AS ID_DEVISE,
    SUM(CASE WHEN h.SENS = 'D' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS debit_annulation,
    SUM(CASE WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS credit_annulation,
    COUNT(*) AS nb_lignes_annulation
  FROM mouvements_comptables AS h
  INNER JOIN operations_annulation AS oa
    ON oa.id_operation_annulation = h.ID_OPERATION
  GROUP BY
    h.ID_OPERATION,
    h.ID_COMPTE,
    h.ID_DEVISE
), rapprochement AS (
  SELECT
    oa.*,
    COALESCE(lo.ID_COMPTE, la.ID_COMPTE) AS id_compte,
    COALESCE(lo.ID_DEVISE, la.ID_DEVISE) AS id_devise,
    ISNULL(lo.debit_origine, 0) AS debit_origine,
    ISNULL(lo.credit_origine, 0) AS credit_origine,
    ISNULL(la.debit_annulation, 0) AS debit_annulation,
    ISNULL(la.credit_annulation, 0) AS credit_annulation,
    ISNULL(lo.nb_lignes_origine, 0) AS nb_lignes_origine,
    ISNULL(la.nb_lignes_annulation, 0) AS nb_lignes_annulation
  FROM operations_annulation AS oa
  LEFT JOIN lignes_origine AS lo
    ON lo.ID_OPERATION = oa.id_operation_origine
  FULL OUTER JOIN lignes_annulation AS la
    ON la.ID_OPERATION = oa.id_operation_annulation
    AND la.ID_COMPTE = lo.ID_COMPTE
    AND la.ID_DEVISE = lo.ID_DEVISE
)
SELECT
  r.date_annulation,
  r.num_transaction_annulation,
  r.numero_recu_annulation,
  r.date_operation_origine,
  r.num_transaction_origine,
  r.numero_recu_origine,
  c.NUM_CPTE AS numero_compte,
  c.LIBELLE AS libelle_compte,
  dv.CODE AS code_devise,
  r.debit_origine,
  r.credit_origine,
  r.debit_annulation,
  r.credit_annulation,
  r.nb_lignes_origine,
  r.nb_lignes_annulation,
  r.debit_origine - r.credit_annulation AS ecart_debit_origine_vs_credit_annulation,
  r.credit_origine - r.debit_annulation AS ecart_credit_origine_vs_debit_annulation,
  CASE
    WHEN r.id_operation_origine IS NULL
    THEN 'Operation origine introuvable'
    WHEN r.nb_lignes_origine = 0
    THEN 'Operation origine sans ecriture comptable'
    WHEN r.nb_lignes_annulation = 0
    THEN 'Annulation sans ecriture comptable'
    WHEN ABS(r.debit_origine - r.credit_annulation) > 0.01
    OR ABS(r.credit_origine - r.debit_annulation) > 0.01
    THEN 'Annulation non symetrique'
    ELSE 'Annulation a verifier'
  END AS statut_controle
FROM rapprochement AS r
LEFT JOIN dbo.COMPTES AS c
  ON c.ID = r.id_compte
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = r.id_devise
WHERE
  NOT r.id_operation_annulation IS NULL
  AND (
    r.id_operation_origine IS NULL
    OR r.nb_lignes_origine = 0
    OR r.nb_lignes_annulation = 0
    OR ABS(r.debit_origine - r.credit_annulation) > 0.01
    OR ABS(r.credit_origine - r.debit_annulation) > 0.01
  )
ORDER BY
  r.date_annulation,
  ABS(r.debit_origine - r.credit_annulation) + ABS(r.credit_origine - r.debit_annulation) DESC;

/*
 140. Equilibre comptable journalier par devise et journal
 Export : 140_cycle_comptable_et_financier_equilibre_comptable_journalier_par_devise_et_journal
 Objectif : verifier chaque jour que le total debit egale le total credit par devise et journal.
 Lecture : complete les controles par operation en donnant une vue de cloture quotidienne adaptee a une institution avec une seule agence.
 Niveau d'importance de la requete : 10
 Usage operationnel : verifier chaque jour que le total debit egale le total credit par devise et journal.
 Periodicite recommandee : Quotidien a la cloture, avec synthese mensuelle
 */
WITH mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
)
SELECT
  h.DATE_OPERATION,
  jo.CODE AS code_journal,
  jo.LIBELLE AS libelle_journal,
  dv.CODE AS code_devise,
  COUNT(*) AS nb_lignes_comptables,
  COUNT(DISTINCT h.ID_OPERATION) AS nb_operations,
  SUM(CASE WHEN h.SENS = 'D' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS total_debit,
  SUM(CASE WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0) ELSE 0 END) AS total_credit,
  SUM(
    CASE
      WHEN h.SENS = 'D'
      THEN ISNULL(h.MONTANT_OPERATION, 0)
      ELSE -ISNULL(h.MONTANT_OPERATION, 0)
    END
  ) AS ecart_debit_credit,
  'Journee comptable desequilibree par devise/journal' AS statut_controle
FROM mouvements_comptables AS h
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = h.ID_DEVISE
LEFT JOIN dbo.JOURNAUX_OPERATION AS jo
  ON jo.ID = h.ID_JOURNAL
WHERE
  h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
GROUP BY
  h.DATE_OPERATION,
  h.ID_JOURNAL,
  jo.CODE,
  jo.LIBELLE,
  h.ID_DEVISE,
  dv.CODE
HAVING
  ABS(
    SUM(
      CASE
        WHEN h.SENS = 'D'
        THEN ISNULL(h.MONTANT_OPERATION, 0)
        ELSE -ISNULL(h.MONTANT_OPERATION, 0)
      END
    )
  ) > 0.01
ORDER BY
  h.DATE_OPERATION,
  ABS(
    SUM(
      CASE
        WHEN h.SENS = 'D'
        THEN ISNULL(h.MONTANT_OPERATION, 0)
        ELSE -ISNULL(h.MONTANT_OPERATION, 0)
      END
    )
  ) DESC;

/*
 141. Mouvements sur comptes clotures bloques ou inactifs
 Export : 141_cycle_epargne_mouvements_sur_comptes_clotures_bloques_ou_inactifs
 Objectif : identifier les mouvements passes sur des comptes clients qui ne devraient plus recevoir d'operations courantes.
 Lecture : renforce le controle des comptes clotures/inactifs en ajoutant client, produit, sens, montant et motif de risque pour faciliter la regularisation.
 Niveau d'importance de la requete : 10
 Usage operationnel : identifier les mouvements passes sur des comptes clients qui ne devraient plus recevoir d'operations courantes.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
comptes_sensibles AS (
  SELECT
    c.ID AS id_compte,
    c.NUM_CPTE AS NUM_CPTE,
    c.LIBELLE AS libelle_compte,
    c.ETAT AS etat_compte,
    c.TYPE_COMPTE AS TYPE_COMPTE,
    cc.DATE_CLOTURE AS DATE_CLOTURE,
    cc.DATE_REOUVERTURE AS DATE_REOUVERTURE,
    cai.STATUT AS statut_compte,
    eev.id_client AS id_client,
    eev.code_client AS code_client,
    eev.nom_client AS nom_client,
    eev.prenoms_client AS prenoms_client,
    eev.type_client AS type_client,
    eev.produit AS produit,
    eev.code_devise AS code_devise
  FROM dbo.COMPTES AS c
  LEFT JOIN dbo.CLOTURE_COMPTE AS cc
    ON cc.ID_COMPTE = c.ID
  LEFT JOIN dbo.COMPTES_ADHERENT_INFO AS cai
    ON cai.id = c.ID
  LEFT JOIN base_epargnes AS eev
    ON eev.id_compte = c.ID
  WHERE
    NOT eev.id_compte IS NULL OR c.TYPE_COMPTE IN ('ADH', 'EPG')
)
SELECT
  h.DATE_OPERATION,
  h.DATE_SAISIE,
  h.NUM_TRANSACTION,
  h.NUMERO_RECU,
  h.ID_TYPE_OPERATION AS type_operation,
  cs.code_client,
  cs.nom_client,
  cs.prenoms_client,
  cs.type_client,
  cs.NUM_CPTE AS numero_compte,
  cs.libelle_compte,
  cs.produit,
  cs.code_devise,
  cs.etat_compte,
  cs.statut_compte,
  cs.DATE_CLOTURE,
  cs.DATE_REOUVERTURE,
  h.SENS,
  h.MONTANT_OPERATION,
  h.DESCRIPTION,
  CASE
    WHEN NOT cs.DATE_CLOTURE IS NULL
    AND cs.DATE_CLOTURE <= h.DATE_OPERATION
    AND (
      cs.DATE_REOUVERTURE IS NULL OR cs.DATE_REOUVERTURE > h.DATE_OPERATION
    )
    THEN 'Mouvement apres cloture du compte'
    WHEN NOT cs.etat_compte IS NULL AND NOT cs.etat_compte IN ('A', 'O')
    THEN 'Mouvement sur compte avec etat non actif'
    WHEN NOT cs.statut_compte IS NULL
    AND NOT UPPER(cs.statut_compte) IN ('ACTIF', 'ACTIVE', 'OUVERT', 'OUVERTE', 'OPEN')
    THEN 'Mouvement sur compte avec statut a risque'
    ELSE 'Mouvement sur compte sensible a verifier'
  END AS statut_controle
FROM mouvements_comptables AS h
INNER JOIN comptes_sensibles AS cs
  ON cs.id_compte = h.ID_COMPTE
WHERE
  h.DATE_OPERATION BETWEEN @date_debut AND @date_fin
  AND (
    (
      NOT cs.DATE_CLOTURE IS NULL
      AND cs.DATE_CLOTURE <= h.DATE_OPERATION
      AND (
        cs.DATE_REOUVERTURE IS NULL OR cs.DATE_REOUVERTURE > h.DATE_OPERATION
      )
    )
    OR (
      NOT cs.etat_compte IS NULL AND NOT cs.etat_compte IN ('A', 'O')
    )
    OR (
      NOT cs.statut_compte IS NULL
      AND NOT UPPER(cs.statut_compte) IN ('ACTIF', 'ACTIVE', 'OUVERT', 'OUVERTE', 'OPEN')
    )
  )
ORDER BY
  h.DATE_OPERATION,
  cs.code_client,
  h.MONTANT_OPERATION DESC;

/*
 142. Credits decaisses sans mouvement comptable coherent
 Export : 142_cycle_credit_credits_decaisses_sans_mouvement_comptable_coherent
 Objectif : verifier que chaque decaissement de credit dispose d'une ecriture comptable coherente sur le compte credit et d'une contrepartie.
 Lecture : un decaissement augmente l'encours du pret dans OPERATIONS_CRD. Le controle rapproche le mouvement credit avec la CTE locale mouvements_comptables.
 Niveau d'importance de la requete : 10
