 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS mtt_encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), credits_en_cours AS (
  SELECT
    ecv.id_client AS id_client,
    COUNT(DISTINCT ecv.id_pret) AS nb_credits_en_cours,
    SUM(ISNULL(ep.mtt_encours, 0)) AS mtt_encours_credit
  FROM base_credits AS ecv
  INNER JOIN encours_pret AS ep
    ON ep.ID_PRET = ecv.id_pret
  WHERE
    ecv.date_effet <= @date_fin
    AND (
      ecv.date_solde IS NULL OR ecv.date_solde > @date_fin
    )
    AND (
      ecv.date_perte IS NULL OR ecv.date_perte > @date_fin
    )
    AND (
      ecv.date_cloture_cycle IS NULL OR ecv.date_cloture_cycle > @date_fin
    )
    AND ecv.date_debut_cycle <= @date_fin
    AND ISNULL(ep.mtt_encours, 0) > 0
  GROUP BY
    ecv.id_client
), solde_dat AS (
  SELECT
    dd.ID AS id_dossier_dat,
    SUM(
      CASE
        WHEN NOT o.ID IS NULL
        THEN CASE WHEN od.SENS_OPERATION = 'D' THEN -1 ELSE 1 END * ISNULL(od.MONTANT, 0)
        ELSE 0
      END
    ) AS solde_dat_a_date,
    MAX(o.DATE_OPERATION) AS date_derniere_operation_dat
  FROM dbo.DOSSIERS_DAT AS dd
  INNER JOIN dbo.CYCLES_DAT AS cd
    ON cd.ID_DOSSIER_DAT = dd.ID
  LEFT JOIN dbo.OPERATIONS_DAT AS od
    ON od.ID_CYCLE_DAT = cd.ID
  LEFT JOIN dbo.OPERATIONS AS o
    ON o.ID = od.ID_OPERATION
    AND o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    dd.ID
), dat_clients AS (
  SELECT
    eev.id_client AS id_client,
    eev.nom_client AS nom_client,
    eev.prenoms_client AS prenoms_client,
    eev.type_client AS type_client,
    eev.telephone AS telephone,
    eev.code_devise AS code_devise,
    eev.nom_agence_compte AS agence,
    dd.ID AS id_dossier_dat,
    dd.DUREE AS duree_dat,
    dd.CAPITALISE AS capitalise,
    dd.RENOUVELE AS renouvele,
    dd.VALIDE AS dossier_dat_valide,
    cd.MONTANT AS montant_dat_initial,
    cd.DATE_DEBUT AS date_debut_cycle_dat,
    cd.DATE_FIN AS date_fin_cycle_dat,
    eev.date_ouverture AS date_ouverture_compte_dat,
    ISNULL(sd.solde_dat_a_date, 0) AS solde_dat_a_date,
    sd.date_derniere_operation_dat AS date_derniere_operation_dat
  FROM dbo.DOSSIERS_DAT AS dd
  INNER JOIN dbo.CYCLES_DAT AS cd
    ON cd.ID_DOSSIER_DAT = dd.ID
  INNER JOIN base_epargnes AS eev
    ON eev.id_compte = dd.ID_COMPTE_DAT
  LEFT JOIN solde_dat AS sd
    ON sd.id_dossier_dat = dd.ID
  WHERE
    eev.type_compte = 'DAT'
    AND eev.date_ouverture <= @date_fin
    AND (
      eev.date_cloture IS NULL OR eev.date_cloture > @date_fin
    )
    AND dd.DATE_EFFET <= @date_fin
    AND (
      dd.DATE_CLOTURE IS NULL OR dd.DATE_CLOTURE > @date_fin
    )
    AND cd.DATE_DEBUT <= @date_fin
    AND (
      cd.DATE_CLOTURE IS NULL OR cd.DATE_CLOTURE > @date_fin
    )
)
SELECT
    @date_fin AS date_situation,
    dc.id_client AS reference_client,
    dc.nom_client,
    dc.prenoms_client,
    dc.type_client,
    dc.telephone,
    dc.code_devise,
    dc.montant_dat_initial,
    dc.date_debut_cycle_dat,
    dc.date_fin_cycle_dat,
    dc.duree_dat,
    dc.dossier_dat_valide,

    CASE
        WHEN dc.date_fin_cycle_dat < @date_fin
            THEN 'DAT echu non cloture'
        WHEN dc.date_fin_cycle_dat >= @date_fin
            THEN 'DAT actif'
        ELSE 'DAT a verifier'
    END AS statut_dat
FROM dat_clients AS dc
LEFT JOIN credits_en_cours AS cec
  ON cec.id_client = dc.id_client
WHERE
  cec.id_client IS NULL
ORDER BY
  dc.solde_dat_a_date DESC,
  dc.montant_dat_initial DESC,
  dc.nom_client,
  dc.prenoms_client;

/*
145. Liste detaillee des prets avec impayes a la date de situation
 Export : 145_cycle_credit_liste_detaillee_des_prets_avec_impayes
 Objectif : restituer une ligne par pret ayant au moins une echeance echue et non totalement remboursee a @date_fin.
 Lecture : l'impaye correspond au reste planifie dans TABAMOR apres deduction des remboursements valides. Le solde du compte de remboursement vient de la CTE locale mouvements_comptables.
 Niveau d'importance de la requete : 10
 Usage operationnel : restituer une ligne par pret ayant au moins une echeance echue et non totalement remboursee a @date_fin.
 Periodicite recommandee : Hebdomadaire pour recouvrement, et a chaque date de situation
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
remboursements_echeance AS (
  SELECT
    rc.ID_TABAMORT AS ID_TABAMORT,
    SUM(ISNULL(rc.CAPITAL, 0)) AS capital_rembourse,
    SUM(ISNULL(rc.INTERET, 0)) AS interet_rembourse,
    SUM(ISNULL(rc.COMMISSION, 0)) AS commission_remboursee,
    SUM(ISNULL(rc.EPARGNE, 0)) AS epargne_remboursee
  FROM dbo.REMBOURS_CRD AS rc
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = rc.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    rc.ID_TABAMORT
), echeances_impayees AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    t.DATE_ECHEANCE AS DATE_ECHEANCE,
    CASE
      WHEN ISNULL(t.CAPITAL, 0) > ISNULL(re.capital_rembourse, 0)
      THEN ISNULL(t.CAPITAL, 0) - ISNULL(re.capital_rembourse, 0)
      ELSE 0
    END AS capital_impaye,
    CASE
      WHEN ISNULL(t.INTERET, 0) > ISNULL(re.interet_rembourse, 0)
      THEN ISNULL(t.INTERET, 0) - ISNULL(re.interet_rembourse, 0)
      ELSE 0
    END AS interet_impaye,
    CASE
      WHEN ISNULL(t.COMMISSION, 0) > ISNULL(re.commission_remboursee, 0)
      THEN ISNULL(t.COMMISSION, 0) - ISNULL(re.commission_remboursee, 0)
      ELSE 0
    END AS commission_impayee,
    CASE
      WHEN ISNULL(t.EPARGNE, 0) > ISNULL(re.epargne_remboursee, 0)
      THEN ISNULL(t.EPARGNE, 0) - ISNULL(re.epargne_remboursee, 0)
      ELSE 0
    END AS epargne_impayee
  FROM dbo.TABAMOR AS t
  INNER JOIN dbo.CYCLES_PRET AS cp
    ON cp.ID = t.ID_CYCLE_PRET
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE <= @date_fin
    AND (
      ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)
      > ISNULL(re.capital_rembourse, 0) + ISNULL(re.interet_rembourse, 0) + ISNULL(re.commission_remboursee, 0) + ISNULL(re.epargne_remboursee, 0) + 0.01
    )
), impayes_pret AS (
  SELECT
    ei.ID_PRET AS ID_PRET,
    COUNT(*) AS nb_echeances_impayees,
    MIN(ei.DATE_ECHEANCE) AS premiere_echeance_impayee,
    MAX(ei.DATE_ECHEANCE) AS derniere_echeance_impayee,
    SUM(ei.capital_impaye) AS capital_impaye,
    SUM(ei.interet_impaye) AS interet_impaye,
    SUM(ei.commission_impayee) AS commission_impayee,
    SUM(ei.epargne_impayee) AS epargne_impayee,
    SUM(ei.capital_impaye + ei.interet_impaye + ei.commission_impayee + ei.epargne_impayee) AS montant_impaye
  FROM echeances_impayees AS ei
  GROUP BY
    ei.ID_PRET
), encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), soldes_compte_remboursement AS (
  SELECT
    p.ID AS ID_PRET,
    SUM(
      CASE
        WHEN h.SENS = 'D' THEN -ISNULL(h.MONTANT_OPERATION, 0)
        WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0)
        ELSE 0
      END
    ) AS solde_compte
  FROM dbo.PRETS AS p
  LEFT JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = p.ID_COMPTE_REMB
    AND h.DATE_OPERATION <= @date_fin
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  GROUP BY
    p.ID
), credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
)
SELECT
  @date_fin AS date_situation,
  LTRIM(RTRIM(CONCAT(ISNULL(cu.nom_client, ''), ' ', ISNULL(cu.prenoms_client, '')))) AS nom_client,
  cr.NUM_CPTE AS compte_remboursement,
  cu.num_manuel,
  cu.numero_pret,
  cu.mtt_pret AS montant,
  cu.date_decaissement,
  cu.date_effet,
  cu.nb_echeance AS duree_credit_nb_echeances,
  cu.periodicite,
  DATEDIFF(MONTH, CAST(cu.date_effet AS DATETIME2), CAST(cu.date_fin_echeance AS DATETIME2)) AS duree_credit_mois,
  cu.date_fin_echeance AS date_fin,
  ISNULL(ep.encours, 0) AS encours,
  ip.montant_impaye AS impaye,
  ip.capital_impaye,
  ip.interet_impaye AS interet,
  ip.commission_impayee,
  ip.epargne_impayee,
  DATEDIFF(DAY, CAST(ip.premiere_echeance_impayee AS DATETIME2), CAST(@date_fin AS DATETIME2)) AS retard_jours,
  ISNULL(scr.solde_compte, 0) AS solde_compte,
  cu.produit,
  cu.gestionnaire_pret AS gestionnaire,
  cu.code_devise,
  ip.nb_echeances_impayees,
  ip.premiere_echeance_impayee,
  ip.derniere_echeance_impayee
FROM impayes_pret AS ip
INNER JOIN dbo.PRETS AS p
  ON p.ID = ip.ID_PRET
LEFT JOIN credits_uniques AS cu
  ON cu.id_pret = p.ID AND cu.rn = 1
LEFT JOIN dbo.COMPTES AS cr
  ON cr.ID = p.ID_COMPTE_REMB
LEFT JOIN encours_pret AS ep
  ON ep.ID_PRET = p.ID
LEFT JOIN soldes_compte_remboursement AS scr
  ON scr.ID_PRET = p.ID
WHERE
  @id_devise_reporting IS NULL OR p.ID_DEVISE = @id_devise_reporting
ORDER BY
  ip.montant_impaye DESC,
  retard_jours DESC,
  nom_client;

/*
146. Liste detaillee des clients avec echeances sur la periode
 Export : 146_cycle_credit_liste_detaillee_des_clients_avec_echeances_sur_la_periode
 Objectif : restituer une ligne par client, pret et echeance comprise entre @date_debut et @date_fin.
 Lecture : le solde est le reste a payer de l'echeance a @date_fin. Le total de l'echeance comprend capital, interet, commission et epargne planifies.
 Niveau d'importance de la requete : 10
 Usage operationnel : restituer une ligne par client, pret et echeance comprise entre @date_debut et @date_fin.
 Periodicite recommandee : Hebdomadaire pour relance, mensuel pour previsions
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
remboursements_echeance AS (
  SELECT
    rc.ID_TABAMORT AS ID_TABAMORT,
    SUM(ISNULL(rc.CAPITAL, 0)) AS capital_rembourse,
    SUM(ISNULL(rc.INTERET, 0)) AS interet_rembourse,
    SUM(ISNULL(rc.COMMISSION, 0)) AS commission_remboursee,
    SUM(ISNULL(rc.EPARGNE, 0)) AS epargne_remboursee
  FROM dbo.REMBOURS_CRD AS rc
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = rc.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    rc.ID_TABAMORT
), credits_cycles_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_cycle_pret
      ORDER BY ecv.date_last_modified DESC, ecv.id_client
    ) AS rn_cycle_reporting
  FROM base_credits AS ecv
)
SELECT
  LTRIM(RTRIM(CONCAT(ISNULL(ecv.nom_client, ''), ' ', ISNULL(ecv.prenoms_client, '')))) AS nom_client,
  ecv.telephone AS numero_telephone,
  ecv.num_manuel,
  ecv.numero_pret,
  ecv.produit,
  t.DATE_ECHEANCE AS date_echeance,
  ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) AS total_echeance,
  ISNULL(t.INTERET, 0) AS interet,
  ISNULL(t.CAPITAL, 0) AS capital,
  CASE
    WHEN
      ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)
      > ISNULL(re.capital_rembourse, 0) + ISNULL(re.interet_rembourse, 0) + ISNULL(re.commission_remboursee, 0) + ISNULL(re.epargne_remboursee, 0)
    THEN
      ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)
      - ISNULL(re.capital_rembourse, 0) - ISNULL(re.interet_rembourse, 0) - ISNULL(re.commission_remboursee, 0) - ISNULL(re.epargne_remboursee, 0)
    ELSE 0
  END AS solde,
  ISNULL(re.capital_rembourse, 0) + ISNULL(re.interet_rembourse, 0) + ISNULL(re.commission_remboursee, 0) + ISNULL(re.epargne_remboursee, 0) AS total_rembourse,
  ISNULL(t.COMMISSION, 0) AS commission,
  ISNULL(t.EPARGNE, 0) AS epargne,
  ecv.gestionnaire_pret AS gestionnaire,
  ecv.code_devise
FROM dbo.TABAMOR AS t
INNER JOIN credits_cycles_uniques AS ecv
  ON ecv.id_cycle_pret = t.ID_CYCLE_PRET
LEFT JOIN remboursements_echeance AS re
  ON re.ID_TABAMORT = t.ID
WHERE
  ecv.rn_cycle_reporting = 1
  AND
  t.DATE_ECHEANCE BETWEEN @date_debut AND @date_fin
  AND (
    @id_devise_reporting IS NULL OR ecv.id_devise = @id_devise_reporting
  )
ORDER BY
  t.DATE_ECHEANCE,
  nom_client,
  ecv.numero_pret;

/*
147. Comptes ordinaires et disponibilites des clients avec impaye ou echeance
 Export : 147_cycle_credit_comptes_ordinaires_et_disponibilites_clients
 Objectif : rapprocher les prets cibles avec les comptes courants ou d'epargne ordinaires du client, en conservant la devise propre a chaque compte.
 Lecture : une ligne represente un pret et un compte ordinaire (type DAV). Le solde comptable est calcule dans la devise du compte a @date_fin. Le montant disponible est une estimation positive du solde comptable; la colonne convertie applique @taux_usd_cdf vers la devise du credit sans effectuer de compensation comptable.
 Niveau d'importance de la requete : 10
 Usage operationnel : rapprocher les prets cibles avec les comptes courants ou d'epargne ordinaires du client, en conservant la devise propre a chaque compte.
 Periodicite recommandee : Hebdomadaire pour recouvrement et compensation a analyser
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
base_epargnes AS (
SELECT
a.*,
C.ID as id_compte,
C.NUM_CPTE as num_compte,
C.LIBELLE as libelle_compte,
C.ID_COMPTE_GENERAL as compte_general,
C.DATE_OUVERTURE as date_ouverture,
C.id_point_service as id_agence_compte,
ag.nom as nom_agence_compte, ag.code as code_agence_compte,
d.ID as id_devise,
d.SYMBOLE as devise,
d.CODE as code_devise,
d.ARRONDI as arrondi_devise,
ca.TYPE_CPTE_ADH as type_compte,
ca.CATEG_CPTE_ADH as categorie_compte,
cc.date_cloture,
cai.STATUT as status_compte,
pe.id as code_produit,
pe.LIBELLE as produit

FROM COMPTEs c
inner join DEVISES d on c.ID_DEVISE = d.id
inner join COMPTES_ADHERENT ca on ca.id = c.id
inner join POINTS_SERVICE ag on ag.id = c.ID_POINT_SERVICE
inner join base_clients as a on a.id_client = ca.ID_ADHERENT
left join CLOTURE_COMPTE cc on cc.id_compte = c.id
left join COMPTES_ADHERENT_INFO cai on cai.id = c.id
left join PRODUITS_EPG pe on pe.id = cai.ID_PRODUIT_EPG

where a.client_perfect = 1
and ca.TYPE_CPTE_ADH in ('CAU', 'DAT', 'PLN', 'DAV', 'TNT')
),
base_credits AS (
SELECT
a.*,
C.ID as id_pret, c.ID_DOSSIER_CREDIT as id_dossier, ca.ID_DEMANDE,
CY.ID as id_cycle_pret,
C.NUMERO_PRET as numero_pret,
C.NUMERO_CONTRAT as numero_contrat,
C.ID_COMPTE_CREDIT as id_compte_credit,
cpteC.NUM_CPTE as num_compte_credit,
C.ID_COMPTE_SAIN as id_compte_sain,
cpteS.NUM_CPTE as num_compte_sain,
ae.NOM + ' ' + ae.PRENOMS as gestionnaire_pret,
ca.NUM_DOSSIER as numero_dossier,
dd.REF_DEMANDE as reference_demande,
dd.NUM_DEMANDE as numero_demande,
dd.DATE_RECEPTION as date_demande,
dd.ID_AGENCE as id_agence_demande,
xx.NOM as nom_agence_demande,  xx.code as code_agence_demande,
dd.NBRE_BENEFICIAIRE as NBRE_BENEFICIAIRE,
d.SYMBOLE as devise,
d.id as id_devise,
d.code as code_devise, d.arrondi AS arrondi, C.TYPE_DUREE_CREDIT as terme_credit,
ca.NBRE_ECHEANCE as nb_echeance, ca.TAUX_ANNUEL as taux, ca.ID_PERIODICITE, tt.CLE_LIBELLE as periodicite,
CY.MONTANT as mtt_pret, c.DATE_EFFET as date_effet, cy.FIN_ECHEANCE as date_fin_echeance, cy.NUM_CYCLE as numero_cycle,
aq.NOM + ' ' + aq.PRENOMS as superviseur, dd.ID_PRODUIT_CREDIT as id_produit, w.LIBELLE as produit, ca.ID_PRDT_CRD_TRANCHE as id_produit_tranche, ca.ID_OBJET_FIN as id_objet_fin,
ob.LIBELLE as objet_fin, sc.LIBELLE as secteur_activite, sf.id as id_source_fin, sf.NOM_SOURCE_FIN as source_fin,
case when sf.TYPE = 'SRC_AFF' then 'A' else 'O' end as type_source_fin,
c.teg, c.date_perte, C.date_solde, C.DATE_REECH, CY.DATE_DEBUT as date_debut_cycle, CY.DATE_CLOTURE as date_cloture_cycle,
c.date_decaissement, (select min(date_echeance) from TABAMOR tb where tb.id_cycle_pret = CY.ID) as date_premiere_echeance


from CYCLES_PRET CY
inner join PRETS C on CY.ID_PRET = C.ID
inner join DEVISES d on c.ID_DEVISE = d.id
inner join DOSSIERS_CREDIT ca on ca.id = c.ID_DOSSIER_CREDIT
left join PERIODICITES tt on tt.id = ca.ID_PERIODICITE
left join GESTIONNAIRES g on g.id = ca.ID_GESTIONNAIRE
left join PERSONNES ae on ae.id = g.ID_PERSONNE
inner join DEMANDES_CREDIT dd on dd.id = ca.ID_DEMANDE
left join base_clients a on a.id_client = dd.ID_ADHERENT
left join SUPERVISEUR g2 on g2.id = g.ID_SUPERVISEUR
left join PERSONNES aq on aq.id = g2.ID_PERSONNE
left join PRODUITS_CRD w on w.id = dd.ID_PRODUIT_CREDIT
left join OBJETS_FIN ob on ob.id = ca.ID_OBJET_FIN
left join SECTEURS_ACTIVITE_CREDIT sc on sc.id = ob.ID_SECTEUR
left join SOURCES_FIN sf on sf.id = c.ID_SOURCE_FIN
left join POINTS_SERVICE xx on xx.id = dd.ID_AGENCE
left join COMPTES cpteC on cpteC.id = C.ID_COMPTE_CREDIT
left join COMPTES cpteS on cpteS.id = C.ID_COMPTE_SAIN

where a.client_perfect = 1
),
mouvements_comptables AS (
SELECT ID as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_VALEUR, NUM_LIGNE, MONTANT_REEL, REFERENCE_TIERS, ID_TIER
FROM hdpm

UNION

SELECT CODE as ID, DATE_OPERATION, DESCRIPTION, ID_OPERATION, LETTRE, MONTANT_OPERATION,
        NUM_TRANSACTION, NUMERO_RECU, RAPPROCHEMENT, SENS, VENTILATION, NUM_MOUVEMENT,
        ID_COMPTE, ID_DEVISE, ID_JOURNAL, ID_POINT_SERVICE, ID_TYPE_OPERATION, DATE_SAISIE,
        DATE_OPERATION as DATE_VALEUR, ID as NUM_LIGNE, MONTANT_OPERATION as MONTANT_REEL,
        NULL as REFERENCE_TIERS, NULL as ID_TIER
FROM hdpm_api
),
remboursements_echeance AS (
  SELECT
    rc.ID_TABAMORT AS ID_TABAMORT,
    SUM(ISNULL(rc.CAPITAL, 0)) AS capital_rembourse,
    SUM(ISNULL(rc.INTERET, 0)) AS interet_rembourse,
    SUM(ISNULL(rc.COMMISSION, 0)) AS commission_remboursee,
    SUM(ISNULL(rc.EPARGNE, 0)) AS epargne_remboursee,
    SUM(ISNULL(rc.CAPITAL, 0) + ISNULL(rc.INTERET, 0) + ISNULL(rc.COMMISSION, 0) + ISNULL(rc.EPARGNE, 0)) AS total_rembourse
  FROM dbo.REMBOURS_CRD AS rc
  INNER JOIN dbo.OPERATIONS_CRD AS oc
    ON oc.ID = rc.ID_OPERATION_CRD
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    rc.ID_TABAMORT
), echeances_impayees AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    t.DATE_ECHEANCE AS DATE_ECHEANCE,
    CASE
      WHEN ISNULL(t.CAPITAL, 0) > ISNULL(re.capital_rembourse, 0)
      THEN ISNULL(t.CAPITAL, 0) - ISNULL(re.capital_rembourse, 0)
      ELSE 0
    END AS capital_impaye,
    CASE
      WHEN ISNULL(t.INTERET, 0) > ISNULL(re.interet_rembourse, 0)
      THEN ISNULL(t.INTERET, 0) - ISNULL(re.interet_rembourse, 0)
      ELSE 0
    END AS interet_impaye,
    CASE
      WHEN ISNULL(t.COMMISSION, 0) > ISNULL(re.commission_remboursee, 0)
      THEN ISNULL(t.COMMISSION, 0) - ISNULL(re.commission_remboursee, 0)
      ELSE 0
    END AS commission_impayee,
    CASE
      WHEN ISNULL(t.EPARGNE, 0) > ISNULL(re.epargne_remboursee, 0)
      THEN ISNULL(t.EPARGNE, 0) - ISNULL(re.epargne_remboursee, 0)
      ELSE 0
    END AS epargne_impayee
  FROM dbo.TABAMOR AS t
  INNER JOIN dbo.CYCLES_PRET AS cp
    ON cp.ID = t.ID_CYCLE_PRET
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE <= @date_fin
    AND (
      ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)
      > ISNULL(re.total_rembourse, 0) + 0.01
    )
), impayes_pret AS (
  SELECT
    ei.ID_PRET AS ID_PRET,
    COUNT(*) AS nb_echeances_impayees,
    MIN(ei.DATE_ECHEANCE) AS premiere_echeance_impayee,
    MAX(ei.DATE_ECHEANCE) AS derniere_echeance_impayee,
    SUM(ei.capital_impaye) AS capital_impaye,
    SUM(ei.interet_impaye) AS interet_impaye,
    SUM(ei.commission_impayee) AS commission_impayee,
    SUM(ei.epargne_impayee) AS epargne_impayee,
    SUM(ei.capital_impaye + ei.interet_impaye + ei.commission_impayee + ei.epargne_impayee) AS montant_impaye
  FROM echeances_impayees AS ei
  GROUP BY
    ei.ID_PRET
), encours_pret AS (
  SELECT
    oc.ID_PRET AS ID_PRET,
    SUM(CASE WHEN oc.SENS_OPERATION = 'D' THEN 1 ELSE -1 END * ISNULL(oc.MONTANT, 0)) AS encours
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    o.DATE_OPERATION <= @date_fin
    AND ISNULL(o.ANNULE, 0) = 0
    AND (
      oc.ID_TYPE_OPERATION IN ('DCSM', 'REMB', 'RECR') OR o.ID_TYPE_OPERATION = 'CONS'
    )
  GROUP BY
    oc.ID_PRET
), echeances_periode AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    MIN(t.DATE_ECHEANCE) AS date_echeance,
    MAX(t.DATE_ECHEANCE) AS derniere_date_echeance_periode,
    COUNT_BIG(*) AS nb_echeances_periode,
    SUM(ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0)) AS total_echeance,
    SUM(ISNULL(t.INTERET, 0)) AS interet,
    SUM(ISNULL(t.CAPITAL, 0)) AS capital,
    SUM(
      CASE
        WHEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) > ISNULL(re.total_rembourse, 0)
        THEN ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) - ISNULL(re.total_rembourse, 0)
        ELSE 0
      END
    ) AS solde,
    SUM(ISNULL(re.total_rembourse, 0)) AS total_rembourse,
    SUM(ISNULL(t.COMMISSION, 0)) AS commission,
    SUM(ISNULL(t.EPARGNE, 0)) AS epargne
  FROM dbo.TABAMOR AS t
  INNER JOIN dbo.CYCLES_PRET AS cp
    ON cp.ID = t.ID_CYCLE_PRET
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  WHERE
    t.DATE_ECHEANCE BETWEEN @date_debut AND @date_fin
  GROUP BY
    cp.ID_PRET
), credits_cibles AS (
  SELECT
    cp.ID_PRET AS ID_PRET,
    MAX(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
          AND ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) > ISNULL(re.total_rembourse, 0) + 0.01
        THEN 1
        ELSE 0
      END
    ) AS avec_impaye,
    MAX(
      CASE
        WHEN t.DATE_ECHEANCE BETWEEN @date_debut AND @date_fin
        THEN 1
        ELSE 0
      END
    ) AS avec_echeance_periode
  FROM dbo.CYCLES_PRET AS cp
  INNER JOIN dbo.TABAMOR AS t
    ON t.ID_CYCLE_PRET = cp.ID
  LEFT JOIN remboursements_echeance AS re
    ON re.ID_TABAMORT = t.ID
  GROUP BY
    cp.ID_PRET
  HAVING
    MAX(
      CASE
        WHEN t.DATE_ECHEANCE <= @date_fin
          AND ISNULL(t.CAPITAL, 0) + ISNULL(t.INTERET, 0) + ISNULL(t.COMMISSION, 0) + ISNULL(t.EPARGNE, 0) > ISNULL(re.total_rembourse, 0) + 0.01
        THEN 1
        ELSE 0
      END
    ) = 1
    OR MAX(
      CASE
        WHEN t.DATE_ECHEANCE BETWEEN @date_debut AND @date_fin
        THEN 1
        ELSE 0
      END
    ) = 1
), credits_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_pret
      ORDER BY ecv.date_debut_cycle DESC, ecv.id_cycle_pret DESC
    ) AS rn
  FROM base_credits AS ecv
), comptes_clients_uniques AS (
  SELECT
    eev.*,
    ROW_NUMBER() OVER (
      PARTITION BY eev.id_compte
      ORDER BY eev.date_cloture DESC, eev.date_last_modified DESC, eev.id_client
    ) AS rn_compte_reporting
  FROM base_epargnes AS eev
), soldes_compte_remboursement AS (
  SELECT
    p.ID AS ID_PRET,
    SUM(
      CASE
        WHEN h.SENS = 'D' THEN -ISNULL(h.MONTANT_OPERATION, 0)
        WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0)
        ELSE 0
      END
    ) AS solde_compte
  FROM dbo.PRETS AS p
  LEFT JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = p.ID_COMPTE_REMB
    AND h.DATE_OPERATION <= @date_fin
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  GROUP BY
    p.ID
), soldes_comptes_ordinaires AS (
  SELECT
    eev.id_compte AS id_compte,
    SUM(
      CASE
        WHEN h.SENS = 'D' THEN -ISNULL(h.MONTANT_OPERATION, 0)
        WHEN h.SENS = 'C' THEN ISNULL(h.MONTANT_OPERATION, 0)
        ELSE 0
      END
    ) AS solde_comptable
  FROM comptes_clients_uniques AS eev
  LEFT JOIN mouvements_comptables AS h
    ON h.ID_COMPTE = eev.id_compte
    AND h.DATE_OPERATION <= @date_fin
    AND ISNULL(h.ID_TYPE_OPERATION, '') <> 'REPR'
  WHERE
    eev.type_compte = 'DAV'
    AND eev.rn_compte_reporting = 1
  GROUP BY
    eev.id_compte
)
SELECT
  @date_fin AS date_situation,
  cc.avec_impaye,
  cc.avec_echeance_periode,
  LTRIM(RTRIM(CONCAT(ISNULL(cu.nom_client, ''), ' ', ISNULL(cu.prenoms_client, '')))) AS nom_client,
  cu.telephone AS numero_telephone,
  cu.num_manuel,
  cu.numero_pret,
  cu.produit AS produit_credit,
  cu.code_devise AS devise_credit,
  cu.mtt_pret AS montant_credit,
  cu.date_effet,
  cu.date_fin_echeance AS date_fin,
  ISNULL(ep.encours, 0) AS encours,
  ISNULL(ip.montant_impaye, 0) AS impaye,
  ISNULL(ip.capital_impaye, 0) AS capital_impaye,
  ISNULL(ip.interet_impaye, 0) AS interet_impaye,
  ISNULL(ip.commission_impayee, 0) AS commission_impayee,
  ISNULL(ip.epargne_impayee, 0) AS epargne_impayee,
  ISNULL(ip.nb_echeances_impayees, 0) AS nb_echeances_impayees,
  ip.premiere_echeance_impayee,
  ip.derniere_echeance_impayee,
  cr_remb.NUM_CPTE AS compte_remboursement,
  ISNULL(scr.solde_compte, 0) AS solde_compte_remboursement,
  ech.date_echeance,
  ech.derniere_date_echeance_periode,
  ISNULL(ech.nb_echeances_periode, 0) AS nb_echeances_periode,
  ISNULL(ech.total_echeance, 0) AS total_echeance,
  ISNULL(ech.interet, 0) AS interet_echeance,
  ISNULL(ech.capital, 0) AS capital_echeance,
  ISNULL(ech.solde, 0) AS solde_echeance,
  ISNULL(ech.total_rembourse, 0) AS total_rembourse_echeance,
  ISNULL(ech.commission, 0) AS commission_echeance,
  ISNULL(ech.epargne, 0) AS epargne_echeance,
  cu.code_devise AS code_devise_echeance,
  eev.num_compte AS numero_compte_ordinaire,
  eev.produit AS produit_compte_ordinaire,
  eev.type_compte,
  eev.code_devise AS devise_compte,
  CASE
    WHEN eev.id_compte IS NULL THEN 'Aucun compte DAV actif trouve'
    WHEN eev.id_devise = cu.id_devise THEN 'Meme devise'
    ELSE 'Devise differente - conversion appliquee'
  END AS compatibilite_devise,
  CASE
    WHEN eev.id_compte IS NULL THEN NULL
    ELSE ISNULL(sco.solde_comptable, 0)
  END AS solde_comptable_compte,
  CASE
    WHEN eev.id_compte IS NULL THEN NULL
    WHEN ISNULL(sco.solde_comptable, 0) > 0 THEN ISNULL(sco.solde_comptable, 0)
    ELSE 0
  END AS montant_disponible_estime,
  @taux_usd_cdf AS taux_usd_cdf_applique,
  dispo.montant_disponible_estime_devise_credit,
  CASE
    WHEN dispo.montant_disponible_estime_devise_credit IS NULL THEN NULL
    WHEN dispo.montant_disponible_estime_devise_credit < ISNULL(ip.montant_impaye, 0)
    THEN dispo.montant_disponible_estime_devise_credit
    ELSE ISNULL(ip.montant_impaye, 0)
  END AS montant_recuperable_estime,
  CASE
    WHEN dispo.montant_disponible_estime_devise_credit IS NULL THEN ISNULL(ip.montant_impaye, 0)
    WHEN ISNULL(ip.montant_impaye, 0) > dispo.montant_disponible_estime_devise_credit
    THEN ROUND(ISNULL(ip.montant_impaye, 0) - dispo.montant_disponible_estime_devise_credit, 2)
    ELSE 0
  END AS reste_impaye_apres_recuperation,
  eev.status_compte,
  eev.date_ouverture,
  eev.date_cloture
FROM credits_cibles AS cc
INNER JOIN credits_uniques AS cu
  ON cu.id_pret = cc.ID_PRET AND cu.rn = 1
LEFT JOIN impayes_pret AS ip
  ON ip.ID_PRET = cu.id_pret
LEFT JOIN encours_pret AS ep
  ON ep.ID_PRET = cu.id_pret
LEFT JOIN echeances_periode AS ech
  ON ech.ID_PRET = cu.id_pret
LEFT JOIN soldes_compte_remboursement AS scr
  ON scr.ID_PRET = cu.id_pret
LEFT JOIN dbo.PRETS AS p_remb
  ON p_remb.ID = cu.id_pret
LEFT JOIN dbo.COMPTES AS cr_remb
  ON cr_remb.ID = p_remb.ID_COMPTE_REMB
LEFT JOIN comptes_clients_uniques AS eev
  ON eev.id_client = cu.id_client
  AND eev.rn_compte_reporting = 1
  AND eev.type_compte = 'DAV'
  AND eev.date_ouverture <= @date_fin
  AND (
    eev.date_cloture IS NULL OR eev.date_cloture > @date_fin
  )
  AND (
    eev.date_depart IS NULL OR eev.date_depart > @date_fin
  )
LEFT JOIN soldes_comptes_ordinaires AS sco
  ON sco.id_compte = eev.id_compte
OUTER APPLY (
  SELECT
    CASE
      WHEN eev.id_compte IS NULL THEN NULL
      WHEN eev.code_devise = cu.code_devise
      THEN ROUND(CASE WHEN ISNULL(sco.solde_comptable, 0) > 0 THEN ISNULL(sco.solde_comptable, 0) ELSE 0 END, 2)
      WHEN eev.code_devise = 'CDF' AND cu.code_devise = 'USD'
      THEN ROUND(
        CASE WHEN ISNULL(sco.solde_comptable, 0) > 0 THEN ISNULL(sco.solde_comptable, 0) ELSE 0 END
        / NULLIF(@taux_usd_cdf, 0),
        2
      )
      WHEN eev.code_devise = 'USD' AND cu.code_devise = 'CDF'
      THEN ROUND(
        CASE WHEN ISNULL(sco.solde_comptable, 0) > 0 THEN ISNULL(sco.solde_comptable, 0) ELSE 0 END
        * @taux_usd_cdf,
        2
      )
      ELSE NULL
    END AS montant_disponible_estime_devise_credit
) AS dispo
WHERE
  @id_devise_reporting IS NULL OR cu.id_devise = @id_devise_reporting
ORDER BY
  cc.avec_impaye DESC,
  nom_client,
  cu.numero_pret,
  eev.code_devise,
  eev.num_compte;

/*
 148. Cycle CRM clients - Liste unique des clients avec telephone et nombre de comptes
 Export : 148_cycle_crm_clients_liste_unique_des_clients_avec_telephone_et_nombre_de_comptes
 Objectif : restituer exactement une ligne par client avec ses coordonnees et le nombre de comptes qui lui sont rattaches.
 Lecture : la CTE locale base_clients est dedupliquee par id_client avant la jointure. Les comptes sont comptes distinctement dans COMPTES_ADHERENT.
 Niveau d'importance de la requete : 10
 Usage operationnel : restituer exactement une ligne par client avec ses coordonnees et le nombre de comptes qui lui sont rattaches.
 Periodicite recommandee : Hebdomadaire
 */
WITH base_clients AS (
select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id as id_client, a.code as code_client, a.num_manuel, p.nom as nom_client,
    p.prenoms as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when p.SEXE='SEXE_M' then 'M' when p.SEXE='SEXE_F' then 'F' else '' end as sexe,
case when p.CIVILITE='CIV_M' then 'M' when p.CIVILITE='CIV_MME' then 'Mme' when p.CIVILITE='CIV_MLLE' then 'Mlle' else '' end as civilite,
case when p.STATUT_MATRIMONIAL='ST_MATRI_M' then 'M' when p.STATUT_MATRIMONIAL='ST_MATRI_C' then 'C' when p.STATUT_MATRIMONIAL='ST_MATRI_D' then 'D'  when p.STATUT_MATRIMONIAL='ST_MATRI_V' then 'V' when p.STATUT_MATRIMONIAL='ST_MATRI_S' then 'S' else '' end as statut_matrimonial,
ad.TEL as telephone, a.DATE_INSCRIPTION as date_adhesion, p.DATE_NAISSANCE as date_naissance, p.LIEU_NAISSNACE as lieu_naissance,
py.LIBELLE as nationalite, pidt.CODE as code_type_piece, pidt.LIBELLE as type_piece_identite, pid.NUMERO_PIECE as numero_piece_identite,
ad.EMAIL as email, pr.code as code_profession, pr.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
p.ALPHABETISE as alphabetise, a.DIRIGEANT as dirigeant, i.PERSONNEL as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, case when p.SEXE='SEXE_M' then 1 else 0 end as nbre_homme, case when p.SEXE='SEXE_F' then 1 else 0 end as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, p.DATE_NAISSANCE, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join individus i on a.id=i.id
 left join personnes p on i.id_personne=p.id
 left join adresses ad on p.ID_ADRESSE=ad.id
 left join PROFESSIONS pr on p.ID_PROFESSION=pr.id
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
 left join PAYS py on p.ID_NATIONALITE=py.id
 left join PIECES_IDENTITE pid on p.ID_PIECE_IDENTITE=pid.id
 left join TYPES_PIECE_IDENTITE pidt on pidt.ID = pid.ID_TYPE_PIECE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IND'

 union

 select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
case when gpe.TYPE_GRPE='TYPE_GP_M' then 'Masculin' when gpe.TYPE_GRPE='TYPE_GP_F' then 'Feminin'
when gpe.TYPE_GRPE='TYPE_GP_X' then 'Mixte' else '' end as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, gpe.DATE_CREATION as date_naissance, gpe.LIEU_RENCONTRE as lieu_naissance,
'' as nationalite, '' as code_type_piece, '' as type_piece_identite, ''  as numero_piece_identite, ad.EMAIL as E_MAIL
, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, gpe.NBRE_HOMME as nbre_homme, gpe.NBRE_FEMME as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, gpe.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
 from adherents a
 left join groupes gpe on a.id=gpe.id
 left join adresses ad on gpe.ID_ADRESSE=ad.id
 left join SECTEURS_ACTIVITE s on s.ID=gpe.ID_SECTEUR
 left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'GPE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE_SOCIAL as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Carte operateur' as type_piece_identite, en.NUM_CARTE_OPERATEUR as numero_piece_identite,
ad.EMAIL as E_MAIL, s.code as code_profession, s.libelle as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join entreprises en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join SECTEURS_ACTIVITE s on s.ID=en.ID_SECTEUR_ACTIVITE
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'SCE'

union

select a.ID_CATEGORIE_ADHERENT as code_categorie_client, a.id, a.code as code_client, a.NUM_MANUEL, a.nom_adherent as nom_du_client,
null  as prenoms_client, a.id_agence as id_agence, ag.nom as nom_agence, ag.code as code_agence,
'' as sexe, '' as civilite, '' as statut_matrimonial,
ad.TEL as TELEPHONE, a.DATE_INSCRIPTION as date_adhesion, en.DATE_CREATION as date_naissance, en.SIEGE as lieu_naissance,
'' as nationalite, '' as code_type_piece, 'Num agrement' as type_piece_identite, en.NUM_AGREMENT as numero_piece_identite,
ad.EMAIL as E_MAIL, '' as code_profession, '' as profession,
ad.BP as bp, ad.VILLE as ville, ad.ADRESSE as adresse, ta.ID as code_type_client, ta.LIBELLE as type_client, ca.LIBELLE as categorie_client,
z.CODE as code_zone, z3.CODE as code_zone3, z2.CODE as code_zone2, z1.CODE as code_zone1,
z.LIBELLE as zone, z3.libelle as zone3, z2.libelle as zone2, z1.libelle as zone1,
null as alphabetise, a.DIRIGEANT as dirigeant, null as personnel,
gs.NOM +' '+gs.PRENOMS as gestionnaire, 0 as nbre_homme, 0 as nbre_femme,
da.DATE_DEPART as date_depart, dad.LIBELLE as motif_depart, DATEDIFF(YEAR, en.DATE_CREATION, a.DATE_INSCRIPTION) as age_adhesion,
a.DATE_LAST_MODIFIED as date_last_modified, a.EST_PERFECT as client_perfect, a.EST_TONTINE as client_tontine,
gsCol.NOM +' '+gsCol.PRENOMS as collecteur, zc.LIBELLE as zone_collecte
from adherents a
left join IMFS en on a.id=en.id
left join adresses ad on en.ID_ADRESSE=ad.id
left join DEPARTS_ADHERENT da on da.ID_ADHERENT = a.id
 left join MOTIFS_DEPART dad on dad.ID = da.ID_MOTIF_DEPART
 left join TYPES_ADHERENT ta on ta.id = a.ID_TYPE_ADHERENT
 left join CATEGORIES_ADHERENT ca on ca.id = a.ID_CATEGORIE_ADHERENT
 left join ZONES z on z.id = a.ID_ZONE
 left join ZONES z3 on z3.id = z.ID_ZONE_PARENT
 left join ZONES z2 on z2.id = z3.ID_ZONE_PARENT
 left join ZONES z1 on z1.id = z2.ID_ZONE_PARENT
 left join GESTIONNAIRES g on g.id = a.ID_GESTIONNAIRE
 left join PERSONNES gs on gs.id = g.ID_PERSONNE
 left join POINTS_SERVICE ag on ag.id = a.ID_AGENCE
left join COLLECTEURS col on col.id = a.ID_COLLECTEUR
left join PERSONNES gsCol on gsCol.id = col.ID_PERSONNE
left join ZONES_COLLECTE zc on zc.id = a.ID_ZONE_COLLECTE
WHERE A.ID_CATEGORIE_ADHERENT = 'IMF'
),
clients_uniques AS (
  SELECT
    ecv.*,
    ROW_NUMBER() OVER (
      PARTITION BY ecv.id_client
      ORDER BY
        CASE WHEN ecv.date_depart IS NULL THEN 0 ELSE 1 END,
        ecv.date_last_modified DESC,
        ecv.date_depart DESC,
        ecv.code_client
    ) AS rn_client
  FROM base_clients AS ecv
), comptes_par_client AS (
  SELECT
    ca.ID_ADHERENT AS id_client,
    COUNT(DISTINCT ca.ID) AS nombre_comptes,
    COUNT(DISTINCT CASE WHEN dv.CODE = 'USD' THEN ca.ID END) AS nombre_comptes_usd,
    COUNT(DISTINCT CASE WHEN dv.CODE = 'CDF' THEN ca.ID END) AS nombre_comptes_cdf,
    COUNT(DISTINCT CASE WHEN ca.TYPE_CPTE_ADH = 'DAV' THEN ca.ID END) AS nombre_comptes_ordinaires,
    COUNT(DISTINCT CASE WHEN ca.TYPE_CPTE_ADH = 'DAT' THEN ca.ID END) AS nombre_comptes_dat,
    MIN(c.DATE_OUVERTURE) AS date_premier_compte,
    MAX(c.DATE_OUVERTURE) AS date_dernier_compte
  FROM dbo.COMPTES_ADHERENT AS ca
  INNER JOIN dbo.COMPTES AS c
    ON c.ID = ca.ID
  LEFT JOIN dbo.DEVISES AS dv
    ON dv.ID = c.ID_DEVISE
  GROUP BY
    ca.ID_ADHERENT
)
SELECT
  cu.code_client,
  cu.num_manuel,
  LTRIM(RTRIM(CONCAT(ISNULL(cu.nom_client, ''), ' ', ISNULL(cu.prenoms_client, '')))) AS nom_client,
  COALESCE(
    NULLIF(LTRIM(RTRIM(cu.telephone)), ''),
    NULLIF(LTRIM(RTRIM(adresse_contact.TEL)), '')
  ) AS numero_telephone,
  cu.telephone AS telephone_principal,
  adresse_contact.TEL AS telephone_contact,
  cu.email,
  cu.adresse,
  cu.ville,
  cu.type_client,
  cu.categorie_client,
  cu.code_agence,
  cu.nom_agence,
  ISNULL(cpc.nombre_comptes, 0) AS nombre_comptes,
  ISNULL(cpc.nombre_comptes_usd, 0) AS nombre_comptes_usd,
  ISNULL(cpc.nombre_comptes_cdf, 0) AS nombre_comptes_cdf,
  ISNULL(cpc.nombre_comptes_ordinaires, 0) AS nombre_comptes_ordinaires,
  ISNULL(cpc.nombre_comptes_dat, 0) AS nombre_comptes_dat,
  cpc.date_premier_compte,
  cpc.date_dernier_compte
FROM clients_uniques AS cu
LEFT JOIN dbo.INDIVIDUS AS i
  ON i.ID = cu.id_client
LEFT JOIN dbo.PERSONNES AS p
  ON p.ID = i.ID_PERSONNE
LEFT JOIN dbo.ADRESSES AS adresse_contact
  ON adresse_contact.ID = p.ID_ADRESSE_CONTACT
LEFT JOIN comptes_par_client AS cpc
  ON cpc.id_client = cu.id_client
WHERE
  cu.rn_client = 1
ORDER BY
  nom_client,
  cu.code_client;

/*
 149. Reporting LBC-FT parametre par periode
 Export : 149_cycle_conformite_reporting_lbc_ft
 Objectif : alimenter les rubriques automatisees du reporting BCC LBC-FT a partir des tables sources reelles.
 Lecture : une ligne par rubrique Excel et par devise lorsque la rubrique est monetaire.
 Niveau d'importance de la requete : 10
 Usage operationnel : alimenter les rubriques automatisees du reporting BCC LBC-FT a partir des tables sources reelles.
 Periodicite recommandee : Mensuel et a chaque reporting LBC-FT

 Parametres obligatoires :
 - @date_debut et @date_fin : periode inclusive du reporting ;
 - @id_devise_reporting : 1 devise precise, ou NULL pour toutes les devises disponibles ;
 - @seuil_5k_usd_cdf et @seuil_10k_usd_cdf : equivalents CDF des seuils 5k/10k USD.

 Regle multi-devises : si @id_devise_reporting est NULL, la requete sort une ligne par devise
 et ne melange jamais les montants. Les seuils sont appliques par devise :
 - USD : 5000 et 10000 ;
 - CDF et autres devises : @seuil_5k_usd_cdf et @seuil_10k_usd_cdf.
 */
WITH devises_reporting AS (
  SELECT
    d.ID AS id_devise,
    d.CODE AS code_devise,
    CAST(
      CASE WHEN UPPER(ISNULL(d.CODE, '')) = 'USD' THEN 5000 ELSE @seuil_5k_usd_cdf END
      AS decimal(38, 2)
    ) AS seuil_5k,
    CAST(
      CASE WHEN UPPER(ISNULL(d.CODE, '')) = 'USD' THEN 10000 ELSE @seuil_10k_usd_cdf END
      AS decimal(38, 2)
    ) AS seuil_10k
  FROM dbo.DEVISES AS d
  WHERE @id_devise_reporting IS NULL OR d.ID = @id_devise_reporting
), mouvements AS (
  SELECT
    'BACK_OFFICE' AS source_mouvement,
    o.ID AS id_operation,
    o.DATE_OPERATION,
    o.ID_TYPE_OPERATION,
    MAX(CAST(ABS(ISNULL(h.MONTANT_OPERATION, 0)) AS decimal(38, 2))) AS montant_operation,
    h.ID_DEVISE
  FROM dbo.OPERATIONS AS o
  INNER JOIN dbo.HDPM AS h
    ON h.ID_OPERATION = o.ID
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = h.ID_DEVISE
  WHERE
    o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    o.ID,
    o.DATE_OPERATION,
    o.ID_TYPE_OPERATION,
    h.ID_DEVISE
  UNION ALL
  SELECT
    'API',
    oa.CODE,
    oa.DATE_OPERATION,
    oa.ID_TYPE_OPERATION,
    MAX(CAST(ABS(ISNULL(ha.MONTANT_OPERATION, 0)) AS decimal(38, 2))),
    ha.ID_DEVISE
  FROM dbo.OPERATIONS_API AS oa
  INNER JOIN dbo.HDPM_API AS ha
    ON ha.ID_OPERATION = oa.CODE
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = ha.ID_DEVISE
  WHERE
    oa.DATE_OPERATION >= @date_debut
    AND oa.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND ISNULL(oa.ANNULE, 0) = 0
  GROUP BY
    oa.CODE,
    oa.DATE_OPERATION,
    oa.ID_TYPE_OPERATION,
    ha.ID_DEVISE
), alertes AS (
  SELECT
    la.ID,
    COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) AS date_alerte,
    la.ETAT_ALERTE,
    la.ID_DEVISE,
    CAST(ABS(ISNULL(la.MONTANT, 0)) AS decimal(38, 2)) AS montant,
    UPPER(ISNULL(la.TYPE_ALERTE, '')) AS type_alerte,
    UPPER(ISNULL(la.DESCRIPTION_ALERTE, '')) AS description_alerte,
    CASE
      WHEN UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'TRAIT%'
        OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'CLOTUR%'
        OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'VALID%'
      THEN 1
      ELSE 0
    END AS est_traitee
  FROM dbo.LAB_ALERTES AS la
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = la.ID_DEVISE
  WHERE
    COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) >= @date_debut
    AND COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) < DATEADD(day, 1, @date_fin)
), remboursements_anticipes AS (
  SELECT
    oc.ID_PRET,
    oc.ID_DEVISE,
    MAX(CAST(ABS(ISNULL(oc.MONTANT, 0)) AS decimal(38, 2))) AS montant
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = oc.ID_DEVISE
  WHERE
    ISNULL(oc.REMB_ANTICIPER, 0) = 1
    AND ISNULL(o.ANNULE, 0) = 0
    AND o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
  GROUP BY
    oc.ID_PRET,
    oc.ID_DEVISE
), reactivations AS (
  SELECT
    r.ID AS id_reactivation,
    r.ID_DEVISE,
    CAST(ABS(ISNULL(r.MONTANT_A_PAYER, 0)) AS decimal(38, 2)) AS montant
  FROM dbo.REACTIVATION_COMPTE_EPG AS r
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = r.ID_OPERATION
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = r.ID_DEVISE
  WHERE
    ISNULL(o.ANNULE, 0) = 0
    AND o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
), indicateurs AS (
  SELECT '1. TAILLE' AS section, 26 AS ligne_excel, 'Total operations comptabilisees' AS rubrique,
    dr.id_devise, COUNT_BIG(m.id_operation) AS nombre, CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)) AS volume,
    'COUVERT' AS statut_couverture, 'dbo.OPERATIONS + dbo.HDPM et sources API' AS source_donnee,
    'Une operation est comptee une fois avec le montant absolu maximal de ses lignes HDPM.' AS commentaire
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '1. TAILLE', 27, 'Total operations en especes', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS + dbo.HDPM',
    'Definition operationnelle : depots et retraits DEPO/RETR ; faire valider les autres modes especes.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('DEPO', 'RETR')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '1. TAILLE', 38, 'Total depots', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS/HDPM + dbo.OPERATIONS_API/HDPM_API',
    'Flux de depots DEPO et MOB_DEPO sur la periode, distinct du stock d epargne.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('DEPO', 'MOB_DEPO')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 65, 'Clients enregistres durant la periode', NULL,
    COUNT_BIG(*), CAST(NULL AS decimal(38, 2)),
    'COUVERT', 'dbo.ADHERENTS',
    'Nombre de clients IMF distincts inscrits dans la periode ; aucun volume monetaire n est calcule.'
  FROM dbo.ADHERENTS AS a
  WHERE a.ID_CATEGORIE_ADHERENT = 'IMF'
    AND a.DATE_INSCRIPTION >= @date_debut
    AND a.DATE_INSCRIPTION < DATEADD(day, 1, @date_fin)
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 66, 'Clients actuellement classes a haut risque', NULL,
    COUNT_BIG(DISTINCT apr.ID_ADHERENT), CAST(NULL AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ADHERENT_PROFIL_RISQUES + dbo.LAB_PROFILS_DE_RISQUE',
    'La table ne porte pas de date de reclassement ; le resultat est un stock actuel, pas un flux de la periode.'
  FROM dbo.LAB_ADHERENT_PROFIL_RISQUES AS apr
  INNER JOIN dbo.LAB_PROFILS_DE_RISQUE AS pr
    ON pr.ID = apr.ID_RISQUE_DE_PROFIL
  WHERE UPPER(ISNULL(pr.LIBELLE_RISQUE, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pr.CODE, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pr.LIBELLE_COULEUR, '')) LIKE '%ROUGE%'
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 68, 'Clients sous surveillance renforcee', NULL,
    COUNT_BIG(DISTINCT apr.ID_ADHERENT), CAST(NULL AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ADHERENT_PROFIL_RISQUES + dbo.LAB_PROFILS_DE_RISQUE',
    'Approximation par profil de risque eleve ; faire valider la regle de surveillance renforcee.'
  FROM dbo.LAB_ADHERENT_PROFIL_RISQUES AS apr
  INNER JOIN dbo.LAB_PROFILS_DE_RISQUE AS pr
    ON pr.ID = apr.ID_RISQUE_DE_PROFIL
  WHERE UPPER(ISNULL(pr.LIBELLE_RISQUE, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pr.CODE, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pr.LIBELLE_COULEUR, '')) LIKE '%ROUGE%'
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 71, 'Depot >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements DEPO et MOB_DEPO', 'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('DEPO', 'MOB_DEPO') AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 72, 'Retrait >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements RETR et MOB_RETR', 'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('RETR', 'MOB_RETR') AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 73, 'Depot entre equivalents 5k et 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements DEPO et MOB_DEPO', 'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('DEPO', 'MOB_DEPO')
    AND m.montant_operation >= dr.seuil_5k AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 74, 'Retrait entre equivalents 5k et 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements RETR et MOB_RETR', 'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.ID_TYPE_OPERATION IN ('RETR', 'MOB_RETR')
    AND m.montant_operation >= dr.seuil_5k AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 142, 'Credits rembourses anticipativement', dr.id_devise,
    COUNT_BIG(ra.ID_PRET), CAST(ISNULL(SUM(ra.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS_CRD.REMB_ANTICIPER + dbo.OPERATIONS',
    'Nombre de prets distincts marques comme rembourses anticipativement dans la periode.'
  FROM devises_reporting AS dr
  LEFT JOIN remboursements_anticipes AS ra ON ra.ID_DEVISE = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 144, 'Total alertes generees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.LAB_ALERTES', 'Periode fondee sur DATE_CREATED puis DATE_OPERATION en repli.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 145, 'Total alertes traitees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES.ETAT_ALERTE',
    'Etats commencant par TRAIT, CLOTUR ou VALID ; nomenclature a valider par la Conformite.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise AND a.est_traitee = 1
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 146, 'Alertes especes >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Seuil applique par devise ; type especes reconnu par mots-clefs.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise AND a.montant >= dr.seuil_10k
    AND (a.type_alerte LIKE '%ESPEC%' OR a.description_alerte LIKE '%ESPEC%' OR a.type_alerte LIKE '%CASH%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 147, 'Alertes traitees especes >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Cumule le critere de seuil/especes et la regle provisoire des etats traites.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise AND a.est_traitee = 1 AND a.montant >= dr.seuil_10k
    AND (a.type_alerte LIKE '%ESPEC%' OR a.description_alerte LIKE '%ESPEC%' OR a.type_alerte LIKE '%CASH%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 148, 'Operations suspectes ou atypiques detectees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Detection par libelle/type contenant SUSPECT ou ATYPI.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise
    AND (a.type_alerte LIKE '%SUSPECT%' OR a.description_alerte LIKE '%SUSPECT%' OR a.type_alerte LIKE '%ATYPI%' OR a.description_alerte LIKE '%ATYPI%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 149, 'Comptes dormants reactives', dr.id_devise,
    COUNT_BIG(r.id_reactivation), CAST(ISNULL(SUM(r.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.REACTIVATION_COMPTE_EPG + dbo.OPERATIONS',
    'Le volume correspond au montant a payer de la reactivation, pas au solde du compte.'
  FROM devises_reporting AS dr
  LEFT JOIN reactivations AS r ON r.ID_DEVISE = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 150, 'Operations fractionnees detectees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Detection par mots-clefs FRACTION ou STRUCTUR dans les alertes officielles.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes AS a ON a.ID_DEVISE = dr.id_devise
    AND (a.type_alerte LIKE '%FRACTION%' OR a.description_alerte LIKE '%FRACTION%' OR a.type_alerte LIKE '%STRUCTUR%' OR a.description_alerte LIKE '%STRUCTUR%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 152, 'Operations effectuees par Mobile Banking', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS_API + dbo.HDPM_API', 'Operations API MOB_DEPO et MOB_RETR.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.source_mouvement = 'API' AND m.ID_TYPE_OPERATION IN ('MOB_DEPO', 'MOB_RETR')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 153, 'Bank to Wallet', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS_API + dbo.HDPM_API',
    'Hypothese : MOB_RETR debite le compte bancaire vers le wallet ; sens a confirmer.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.source_mouvement = 'API' AND m.ID_TYPE_OPERATION = 'MOB_RETR'
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 154, 'Wallet to Bank', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS_API + dbo.HDPM_API',
    'Hypothese : MOB_DEPO credite le compte bancaire depuis le wallet ; sens a confirmer.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.ID_DEVISE = dr.id_devise AND m.source_mouvement = 'API' AND m.ID_TYPE_OPERATION = 'MOB_DEPO'
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '5. DECLARATIONS DES SOUPCONS', 164, 'DOS enregistrees', NULL,
    COUNT_BIG(*), CAST(ISNULL(SUM(CAST(ABS(ISNULL(ds.montantTotal, 0)) AS decimal(38, 2))), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_DECLARATION_SOUPCONS',
    'La devise est stockee en texte dans chaque declaration ; consulter la requete detaillee avant consolidation.'
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE ISNULL(ds.annuleOui, 0) = 0
    AND ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
  UNION ALL
  SELECT '5. DECLARATIONS DES SOUPCONS', 163, 'Declarations automatiques', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Aucune source explicitement qualifiee automatique',
    'Ne pas assimiler automatiquement LAB_DECLARATION_CENTIF a une declaration automatique.'
  UNION ALL
  SELECT '6. SANCTIONS FINANCIERES CIBLEES', 166, 'Gels des avoirs', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Referentiel dbo.LAB_BLACKLISTS uniquement',
    'Aucune table d action de gel execute identifiee dans le schema.'
  UNION ALL
  SELECT '6. SANCTIONS FINANCIERES CIBLEES', 167, 'Transactions refusees pour sanctions', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Referentiel dbo.LAB_BLACKLISTS uniquement',
    'Aucune table de decision de refus liee a une correspondance blacklist identifiee.'
)
SELECT
  i.section,
  i.ligne_excel AS ligne_reporting,
  i.rubrique,
  @date_debut AS date_debut,
  @date_fin AS date_fin,
  dv.CODE AS code_devise,
  i.nombre,
  i.volume,
  i.statut_couverture,
  i.source_donnee AS origine_donnee,
  i.commentaire
FROM indicateurs AS i
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = i.id_devise
ORDER BY
  i.ligne_excel,
  i.id_devise;

/*
 150. Alertes LBC-FT detaillees pour traitement Conformite
 Export : 150_cycle_conformite_alertes_lbc_ft_detaillees
 Objectif : fournir la piste d audit des alertes generees, traitees et en attente sur la periode.
 Lecture : une ligne par alerte LAB avec client, operation, montant, devise, profil et etat.
 Niveau d'importance de la requete : 10
 Usage operationnel : fournir la piste d audit des alertes generees, traitees et en attente sur la periode.
 Periodicite recommandee : Hebdomadaire, voire quotidien si alertes sensibles
 */
SELECT
  la.NUM_ALERTE AS numero_alerte,
  COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) AS date_alerte,
  la.DATE_OPERATION AS date_operation,
  la.ID_ADHERENT AS code_adherent,
  la.NOM AS nom_client,
  la.ID_OPERATION_PERFECT AS numero_operation,
  la.ID_TYPE_OPERATION AS type_operation,
  la.TYPE_ALERTE AS type_alerte,
  la.DESCRIPTION_ALERTE AS description_alerte,
  la.MONTANT AS montant,
  dv.CODE AS devise,
  la.ETAT_ALERTE AS etat_alerte,
  la.MOTIF_ETAT_ALERTE AS motif_etat,
  pdr.LIBELLE_RISQUE AS niveau_risque,
  pr.LIBELLE AS profil_risque,
  la.ID_POINT_SERVICE AS point_service,
  CASE
    WHEN UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'TRAIT%'
      OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'CLOTUR%'
      OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'VALID%'
    THEN 'TRAITEE_SELON_REGLE_PROVISOIRE'
    ELSE 'A_REVOIR'
  END AS statut_revue_conformite
FROM dbo.LAB_ALERTES AS la
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = la.ID_DEVISE
LEFT JOIN dbo.LAB_PROFILS_DE_RISQUE AS pdr
  ON pdr.ID = la.ID_RISQUE_DE_PROFIL
LEFT JOIN dbo.LAB_PROFIL_RISQUES AS pr
  ON pr.ID = la.ID_PROFIL_RISQUE
WHERE
  COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) >= @date_debut
  AND COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) < DATEADD(day, 1, @date_fin)
  AND (@id_devise_reporting IS NULL OR la.ID_DEVISE = @id_devise_reporting)
ORDER BY
  date_alerte DESC,
  numero_alerte;

/*
 151. Declarations de soupcon et declarations CENTIF detaillees
 Export : 151_cycle_conformite_declarations_soupcon_centif
 Objectif : inventorier les declarations reglementaires sans additionner les deux formulaires.
 Lecture : une ligne par declaration, avec source explicite pour controler les doubles saisies.
 Niveau d'importance de la requete : 10
 Usage operationnel : inventorier les declarations reglementaires sans additionner les deux formulaires.
 Periodicite recommandee : Hebdomadaire pour suivi conformite, mensuel pour reporting
 */
WITH declarations AS (
  SELECT
    'LAB_DECLARATION_SOUPCONS' AS source_declaration,
    CAST(ds.ID AS varchar(255)) AS id_declaration,
    CAST(ds.dateDeclaration AS date) AS date_declaration,
    ds.referenceInterne AS reference_interne,
    ds.referenceCentif AS reference_externe,
    COALESCE(NULLIF(ds.nomPersonnePP, ''), NULLIF(ds.raisonSocialePM, ''), NULLIF(ds.nomPM, '')) AS personne_declaree,
    ds.numeroCompte AS numero_compte,
    CAST(ds.montantTotal AS decimal(38, 2)) AS montant,
    COALESCE(NULLIF(ds.devise, ''), NULLIF(ds.pays, '')) AS devise_texte,
    ISNULL(ds.annuleOui, 0) AS est_annulee,
    ISNULL(ds.operationFractionne, 0) AS operation_fractionnee,
    ISNULL(ds.operationGelFond, 0) AS operation_gel_fonds,
    ISNULL(ds.operationHautRisque, 0) AS operation_haut_risque,
    ISNULL(ds.blanchimentCapitaux, 0) AS soupcon_blanchiment,
    ISNULL(ds.financementTerrorisme, 0) AS soupcon_financement_terrorisme
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE
    ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
  UNION ALL
  SELECT
    'LAB_DECLARATION_CENTIF',
    CAST(dc.ID AS varchar(255)),
    CAST(dc.DATE_DECLARATION AS date),
    dc.NUMERO_REF_INT,
    dc.REF_CENTIF,
    COALESCE(NULLIF(dc.NOM, ''), NULLIF(dc.RAISON_SOCIAL, ''), NULLIF(dc.NOM_PM, '')),
    dc.NUM_COMPTE,
    CAST(dc.MONTANT_TOTAL AS decimal(38, 2)),
    dc.DEVISE,
    ISNULL(dc.ANNULEE_CLIENT_LE, 0),
    CAST(0 AS bit),
    CAST(0 AS bit),
    CAST(0 AS bit),
    ISNULL(dc.BLANCHIMENT_CAPITAUX, 0),
    ISNULL(dc.FNC_TERRORISME, 0)
  FROM dbo.LAB_DECLARATION_CENTIF AS dc
  WHERE
    dc.DATE_DECLARATION >= @date_debut
    AND dc.DATE_DECLARATION < DATEADD(day, 1, @date_fin)
)
SELECT
  source_declaration,
  date_declaration,
  reference_interne,
  reference_externe,
  personne_declaree,
  numero_compte,
  montant,
  devise_texte,
  est_annulee,
  operation_fractionnee,
  operation_gel_fonds,
  operation_haut_risque,
  soupcon_blanchiment,
  soupcon_financement_terrorisme
FROM declarations
ORDER BY
  date_declaration DESC,
  source_declaration,
  id_declaration;

/*
 152. Clients classes a risque et surveillance renforcee
 Export : 152_cycle_conformite_clients_profils_risque
 Objectif : fournir la population actuelle des clients profiles par le module LAB.
 Lecture : une ligne par affectation client/profil ; aucune date de reclassement n existe dans cette table.
 Niveau d'importance de la requete : 10
 Usage operationnel : fournir la population actuelle des clients profiles par le module LAB.
 Periodicite recommandee : Hebdomadaire pour surveillance renforcee, mensuel pour comite conformite
 */
SELECT
  a.CODE AS code_adherent,
  a.NOM_ADHERENT AS nom_adherent,
  a.DATE_INSCRIPTION AS date_inscription,
  apr.ID_POINT_SERVICE AS point_service_lab,
  pr.CODE AS code_profil,
  pr.LIBELLE AS profil_risque,
  pdr.CODE AS code_niveau_risque,
  pdr.LIBELLE_RISQUE AS niveau_risque,
  pdr.LIBELLE_COULEUR AS couleur_risque,
  apr.RISQUE_MANUEL AS risque_attribue_manuellement,
  apr.UTILISATEUR_MANUEL AS utilisateur_attribution,
  CASE WHEN a.ID IS NULL THEN 1 ELSE 0 END AS anomalie_adherent_introuvable
FROM dbo.LAB_ADHERENT_PROFIL_RISQUES AS apr
LEFT JOIN dbo.ADHERENTS AS a
  ON a.ID = apr.ID_ADHERENT OR a.CODE = apr.ID_ADHERENT
LEFT JOIN dbo.LAB_PROFIL_RISQUES AS pr
  ON pr.ID = apr.ID_PROFIL_RISQUE
LEFT JOIN dbo.LAB_PROFILS_DE_RISQUE AS pdr
  ON pdr.ID = apr.ID_RISQUE_DE_PROFIL
ORDER BY
  niveau_risque DESC,
  nom_adherent,
  code_adherent;

/*
 153. Referentiel des listes de sanctions et qualite d identification
 Export : 153_cycle_conformite_referentiel_listes_sanctions
 Objectif : controler la presence et l identifiabilite des personnes inscrites dans les blacklists.
 Lecture : une ligne par entree de liste ; ce resultat ne prouve ni screening, ni gel, ni refus.
 Niveau d'importance de la requete : 10
 Usage operationnel : controler la presence et l identifiabilite des personnes inscrites dans les blacklists.
 Periodicite recommandee : Mensuel, et apres toute mise a jour de liste de sanctions
 */
WITH noms AS (
  SELECT
    n.ID_BLACKLIST,
    STRING_AGG(CAST(n.NOM AS varchar(max)), ' | ') AS autres_noms
  FROM dbo.LAB_BLACKLIST_NAMES AS n
  GROUP BY n.ID_BLACKLIST
), pieces AS (
  SELECT
    p.ID_BLACKLIST,
    STRING_AGG(CAST(p.NUMERO_PIECE AS varchar(max)), ' | ') AS autres_pieces
  FROM dbo.LAB_BLACKLIST_PIECES AS p
  GROUP BY p.ID_BLACKLIST
), pseudos AS (
  SELECT
    p.ID_BLACKLIST,
    STRING_AGG(CAST(p.PSEUDO AS varchar(max)), ' | ') AS pseudos
  FROM dbo.LAB_BLACKLIST_PSEUDOS AS p
  GROUP BY p.ID_BLACKLIST
)
SELECT
  b.IDENTIFIANT AS reference_liste,
  b.TYPE_LISTE AS type_liste,
  b.REGIME_SANCTION AS regime_sanction,
  b.TYPE_PERSONNE AS type_personne,
  b.DESIGNATION AS designation,
  b.NOM AS nom_principal,
  n.autres_noms,
  ps.pseudos,
  b.NIN,
  p.autres_pieces,
  b.NATIONALITE AS nationalite,
  b.DATE_INSCRIPTION AS date_inscription,
  b.FONDEMENT_JURIDIQUE AS fondement_juridique,
  CASE
    WHEN NULLIF(LTRIM(RTRIM(ISNULL(b.NOM, ''))), '') IS NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(b.DESIGNATION, ''))), '') IS NULL
    THEN 1 ELSE 0
  END AS anomalie_identite_absente,
  'REFERENTIEL_SEULEMENT' AS limite_interpretation
FROM dbo.LAB_BLACKLISTS AS b
LEFT JOIN noms AS n ON n.ID_BLACKLIST = b.ID
LEFT JOIN pieces AS p ON p.ID_BLACKLIST = b.ID
LEFT JOIN pseudos AS ps ON ps.ID_BLACKLIST = b.ID
ORDER BY
  b.DATE_INSCRIPTION DESC,
  b.ID;

/*
 154. Comptes d epargne reactives sur la periode
 Export : 154_cycle_conformite_comptes_dormants_reactives
 Objectif : justifier la ligne 149 du reporting avec la piste d audit compte/operation.
 Lecture : une ligne par reactivation, avec dates de cloture/reouverture, compte, montant et devise.
 Niveau d'importance de la requete : 10
 Usage operationnel : justifier la ligne 149 du reporting avec la piste d audit compte/operation.
 Periodicite recommandee : Hebdomadaire pour reactivations, mensuel pour reporting LBC-FT
 */
SELECT
  o.DATE_OPERATION AS date_operation_reactivation,
  o.NUM_TRANSACTION AS numero_transaction,
  o.NUMERO_RECU AS numero_recu,
  c.ID_COMPTE AS numero_compte,
  c.DATE_CLOTURE AS date_cloture,
  c.DATE_REOUVERTURE AS date_reouverture,
  mc.LIBELLE AS motif_cloture,
  r.MONTANT_A_PAYER AS montant_reactivation,
  dv.CODE AS devise,
  o.ID_POINT_SERVICE AS point_service,
  o.ID_UTILISATEUR AS utilisateur_saisie,
  o.ID_UTILISATEUR_VALIDE AS utilisateur_validation
FROM dbo.REACTIVATION_COMPTE_EPG AS r
INNER JOIN dbo.OPERATIONS AS o
  ON o.ID = r.ID_OPERATION
LEFT JOIN dbo.CLOTURE_COMPTE AS c
  ON c.ID = r.ID_CLOTURE_COMPTE
LEFT JOIN dbo.MOTIFS_CLOTURE AS mc
  ON mc.ID = c.ID_MOTIF_CLOTURE
LEFT JOIN dbo.DEVISES AS dv
  ON dv.ID = r.ID_DEVISE
WHERE
  ISNULL(o.ANNULE, 0) = 0
  AND o.DATE_OPERATION >= @date_debut
  AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
  AND (@id_devise_reporting IS NULL OR r.ID_DEVISE = @id_devise_reporting)
ORDER BY
  o.DATE_OPERATION DESC,
  o.NUM_TRANSACTION;

/*
 155. Qualite des donnees du dispositif LBC-FT
 Export : 155_cycle_conformite_qualite_donnees_lbc_ft
 Objectif : mesurer les lacunes qui peuvent fausser le reporting ou empecher le traitement des alertes.
 Lecture : une ligne par controle, avec volume d anomalies, severite et action recommandee.
 Niveau d'importance de la requete : 10
 Usage operationnel : mesurer les lacunes qui peuvent fausser le reporting ou empecher le traitement des alertes.
 Periodicite recommandee : Mensuel, avant validation du reporting LBC-FT
 */
WITH alertes_periode AS (
  SELECT la.*
  FROM dbo.LAB_ALERTES AS la
  WHERE
    COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) >= @date_debut
    AND COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) < DATEADD(day, 1, @date_fin)
), declarations_periode AS (
  SELECT ds.*
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE
    ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
), controles AS (
  SELECT
    'ALERTE_SANS_NUMERO' AS controle,
    COUNT_BIG(*) AS nombre_anomalies,
    'ELEVEE' AS severite,
    'Rendre NUM_ALERTE obligatoire et unique pour assurer la piste d audit.' AS action_recommandee
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(NUM_ALERTE, ''))), '') IS NULL
  UNION ALL
  SELECT
    'ALERTE_SANS_CLIENT', COUNT_BIG(*), 'ELEVEE',
    'Completer ID_ADHERENT avant cloture de l alerte.'
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(ID_ADHERENT, ''))), '') IS NULL
  UNION ALL
  SELECT
    'ALERTE_SANS_DEVISE', COUNT_BIG(*), 'ELEVEE',
    'Rendre ID_DEVISE obligatoire pour eviter les consolidations multi-devises.'
  FROM alertes_periode
  WHERE ID_DEVISE IS NULL
  UNION ALL
  SELECT
    'ALERTE_SANS_ETAT', COUNT_BIG(*), 'ELEVEE',
    'Rendre ETAT_ALERTE obligatoire et normaliser les valeurs autorisees.'
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(ETAT_ALERTE, ''))), '') IS NULL
  UNION ALL
  SELECT
    'NUMERO_ALERTE_DUPLIQUE', COUNT_BIG(*), 'CRITIQUE',
    'Investiguer les numeros repetes et poser une contrainte d unicite si la regle metier le confirme.'
  FROM (
    SELECT NUM_ALERTE
    FROM alertes_periode
    WHERE NULLIF(LTRIM(RTRIM(ISNULL(NUM_ALERTE, ''))), '') IS NOT NULL
    GROUP BY NUM_ALERTE
    HAVING COUNT_BIG(*) > 1
  ) AS doublons
  UNION ALL
  SELECT
    'DOS_SANS_REFERENCE_INTERNE', COUNT_BIG(*), 'ELEVEE',
    'Renseigner referenceInterne pour relier la declaration au dossier de Conformite.'
  FROM declarations_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(referenceInterne, ''))), '') IS NULL
  UNION ALL
  SELECT
    'DOS_SANS_DEVISE', COUNT_BIG(*), 'ELEVEE',
    'Renseigner la devise avant toute consolidation des montants declares.'
  FROM declarations_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(devise, ''))), '') IS NULL
  UNION ALL
  SELECT
    'PROFIL_LAB_SANS_ADHERENT', COUNT_BIG(*), 'CRITIQUE',
    'Corriger la cle ID_ADHERENT ou CODE afin de garantir le rattachement au client Perfect Vision.'
  FROM dbo.LAB_ADHERENT_PROFIL_RISQUES AS apr
  LEFT JOIN dbo.ADHERENTS AS a
    ON a.ID = apr.ID_ADHERENT OR a.CODE = apr.ID_ADHERENT
  WHERE a.ID IS NULL
  UNION ALL
  SELECT
    'BLACKLIST_SANS_IDENTITE', COUNT_BIG(*), 'CRITIQUE',
    'Completer au minimum NOM ou DESIGNATION pour rendre le screening exploitable.'
  FROM dbo.LAB_BLACKLISTS AS b
  WHERE
    NULLIF(LTRIM(RTRIM(ISNULL(b.NOM, ''))), '') IS NULL
    AND NULLIF(LTRIM(RTRIM(ISNULL(b.DESIGNATION, ''))), '') IS NULL
)
SELECT
  @date_debut AS date_debut,
  @date_fin AS date_fin,
  controle,
  nombre_anomalies,
  severite,
  action_recommandee
FROM controles
ORDER BY
  CASE severite WHEN 'CRITIQUE' THEN 1 WHEN 'ELEVEE' THEN 2 ELSE 3 END,
  nombre_anomalies DESC,
  controle;

/*
 156. Socle unique cycle Conformite LBC-FT pour analyses 38, 39, 48, 57 et 149 a 155
 Export : 156_cycle_conformite_lbc_ft_socle_unique_analyses_38_39_48_57_149_155
 Objectif : produire un seul fichier a televerser dans l'application pour couvrir la synthese des flux,
 le fractionnement, les trous de couverture, les gros mouvements, le reporting, les alertes, declarations,
 profils de risque, sanctions, comptes reactives et controles qualite LBC-FT.
 Lecture : une ligne par element de controle, avec analyse_source pour distinguer les blocs 38, 39, 48, 57 et 149 a 155.
 Niveau d'importance de la requete : 10
 Usage operationnel : Televerser un fichier unique pour couvrir les analyses conformite LBC-FT prevues.
 Periodicite recommandee : Mensuel et a chaque televersement du cycle conformite

 Parametres :
 - @date_debut et @date_fin : periode inclusive ;
 - @id_devise_reporting : NULL pour les details multi-devises, ou 1/2 pour filtrer USD/CDF ;
 - @seuil_5k_usd_cdf et @seuil_10k_usd_cdf : seuils equivalents dans la devise de reporting.

 Garde-fou : les montants gardent toujours leur devise. Si @id_devise_reporting est NULL,
 les lignes monetaires sont produites par devise, sans consolidation multi-devises.
 */
DROP TABLE IF EXISTS #mouvements_conformite_156;

SELECT
  CAST('BACK_OFFICE' AS varchar(20)) AS source_mouvement,
  CAST(o.ID AS varchar(255)) AS id_operation,
  CAST(o.DATE_OPERATION AS date) AS date_operation,
  CAST(o.ID_TYPE_OPERATION AS varchar(255)) AS type_operation,
  MAX(CAST(ABS(ISNULL(h.MONTANT_OPERATION, 0)) AS decimal(38, 2))) AS montant_operation,
  h.ID_DEVISE AS id_devise
INTO #mouvements_conformite_156
FROM dbo.OPERATIONS AS o
INNER JOIN dbo.HDPM AS h
  ON h.ID_OPERATION = o.ID
WHERE
  o.DATE_OPERATION >= @date_debut
  AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
  AND ISNULL(o.ANNULE, 0) = 0
  AND (@id_devise_reporting IS NULL OR h.ID_DEVISE = @id_devise_reporting)
GROUP BY
  o.ID,
  CAST(o.DATE_OPERATION AS date),
  o.ID_TYPE_OPERATION,
  h.ID_DEVISE
UNION ALL
SELECT
  CAST('API' AS varchar(20)),
  CAST(oa.CODE AS varchar(255)),
  CAST(oa.DATE_OPERATION AS date),
  CAST(oa.ID_TYPE_OPERATION AS varchar(255)),
  MAX(CAST(ABS(ISNULL(ha.MONTANT_OPERATION, 0)) AS decimal(38, 2))),
  ha.ID_DEVISE
FROM dbo.OPERATIONS_API AS oa
INNER JOIN dbo.HDPM_API AS ha
  ON ha.ID_OPERATION = oa.CODE
WHERE
  oa.DATE_OPERATION >= @date_debut
  AND oa.DATE_OPERATION < DATEADD(day, 1, @date_fin)
  AND ISNULL(oa.ANNULE, 0) = 0
  AND (@id_devise_reporting IS NULL OR ha.ID_DEVISE = @id_devise_reporting)
GROUP BY
  oa.CODE,
  CAST(oa.DATE_OPERATION AS date),
  oa.ID_TYPE_OPERATION,
  ha.ID_DEVISE;

CREATE CLUSTERED INDEX IX_mouvements_conformite_156
  ON #mouvements_conformite_156 (id_devise, type_operation, date_operation, id_operation);

WITH devises_reporting AS (
  SELECT
    d.ID AS id_devise,
    d.CODE AS code_devise,
    CAST(CASE WHEN UPPER(ISNULL(d.CODE, '')) = 'USD' THEN 5000 ELSE @seuil_5k_usd_cdf END AS decimal(38, 2)) AS seuil_5k,
    CAST(CASE WHEN UPPER(ISNULL(d.CODE, '')) = 'USD' THEN 10000 ELSE @seuil_10k_usd_cdf END AS decimal(38, 2)) AS seuil_10k
  FROM dbo.DEVISES AS d
  WHERE @id_devise_reporting IS NULL OR d.ID = @id_devise_reporting
), mouvements AS (
  SELECT
    source_mouvement,
    id_operation,
    date_operation,
    type_operation,
    montant_operation,
    id_devise
  FROM #mouvements_conformite_156
), alertes_periode AS (
  SELECT
    la.ID,
    la.NUM_ALERTE,
    COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) AS date_alerte,
    la.DATE_OPERATION AS date_operation,
    la.ID_ADHERENT,
    la.NOM,
    la.ID_OPERATION_PERFECT,
    la.ID_OPERATION,
    la.ID_TYPE_OPERATION,
    la.TYPE_ALERTE,
    la.DESCRIPTION_ALERTE,
    CAST(ABS(ISNULL(la.MONTANT, 0)) AS decimal(38, 2)) AS montant,
    la.ID_DEVISE,
    la.ETAT_ALERTE,
    la.MOTIF_ETAT_ALERTE,
    la.ID_POINT_SERVICE,
    pdr.LIBELLE_RISQUE AS niveau_risque,
    pr.LIBELLE AS profil_risque,
    CASE
      WHEN UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'TRAIT%'
        OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'CLOTUR%'
        OR UPPER(ISNULL(la.ETAT_ALERTE, '')) LIKE 'VALID%'
      THEN 1
      ELSE 0
    END AS est_traitee
  FROM dbo.LAB_ALERTES AS la
  LEFT JOIN dbo.LAB_PROFILS_DE_RISQUE AS pdr
    ON pdr.ID = la.ID_RISQUE_DE_PROFIL
  LEFT JOIN dbo.LAB_PROFIL_RISQUES AS pr
    ON pr.ID = la.ID_PROFIL_RISQUE
  WHERE
    COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) >= @date_debut
    AND COALESCE(CAST(la.DATE_CREATED AS date), la.DATE_OPERATION) < DATEADD(day, 1, @date_fin)
    AND (@id_devise_reporting IS NULL OR la.ID_DEVISE = @id_devise_reporting)
), remboursements_anticipes AS (
  SELECT
    oc.ID_PRET,
    CAST(oc.ID_OPERATION AS varchar(255)) AS id_operation,
    CAST(o.DATE_OPERATION AS date) AS date_operation,
    oc.ID_DEVISE AS id_devise,
    MAX(CAST(ABS(ISNULL(oc.MONTANT, 0)) AS decimal(38, 2))) AS montant
  FROM dbo.OPERATIONS_CRD AS oc
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = oc.ID_OPERATION
  WHERE
    ISNULL(oc.REMB_ANTICIPER, 0) = 1
    AND ISNULL(o.ANNULE, 0) = 0
    AND o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND (@id_devise_reporting IS NULL OR oc.ID_DEVISE = @id_devise_reporting)
  GROUP BY
    oc.ID_PRET,
    oc.ID_OPERATION,
    CAST(o.DATE_OPERATION AS date),
    oc.ID_DEVISE
), reactivations (
  id_reactivation,
  id_devise,
  date_operation,
  NUM_TRANSACTION,
  NUMERO_RECU,
  numero_compte,
  DATE_CLOTURE,
  DATE_REOUVERTURE,
  motif_cloture,
  montant,
  ID_POINT_SERVICE,
  ID_UTILISATEUR,
  ID_UTILISATEUR_VALIDE
) AS (
  SELECT
    r.ID AS id_reactivation,
    r.ID_DEVISE AS id_devise,
    CAST(o.DATE_OPERATION AS date) AS date_operation,
    o.NUM_TRANSACTION,
    o.NUMERO_RECU,
    c.ID_COMPTE AS numero_compte,
    c.DATE_CLOTURE,
    c.DATE_REOUVERTURE,
    mc.LIBELLE AS motif_cloture,
    CAST(ABS(ISNULL(r.MONTANT_A_PAYER, 0)) AS decimal(38, 2)) AS montant,
    o.ID_POINT_SERVICE,
    o.ID_UTILISATEUR,
    o.ID_UTILISATEUR_VALIDE
  FROM dbo.REACTIVATION_COMPTE_EPG AS r
  INNER JOIN dbo.OPERATIONS AS o
    ON o.ID = r.ID_OPERATION
  LEFT JOIN dbo.CLOTURE_COMPTE AS c
    ON c.ID = r.ID_CLOTURE_COMPTE
  LEFT JOIN dbo.MOTIFS_CLOTURE AS mc
    ON mc.ID = c.ID_MOTIF_CLOTURE
  WHERE
    ISNULL(o.ANNULE, 0) = 0
    AND o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND (@id_devise_reporting IS NULL OR r.ID_DEVISE = @id_devise_reporting)
), declarations AS (
  SELECT
    'LAB_DECLARATION_SOUPCONS' AS source_declaration,
    CAST(ds.ID AS varchar(255)) AS id_declaration,
    CAST(ds.dateDeclaration AS date) AS date_declaration,
    ds.referenceInterne AS reference_interne,
    ds.referenceCentif AS reference_externe,
    COALESCE(NULLIF(ds.nomPersonnePP, ''), NULLIF(ds.raisonSocialePM, ''), NULLIF(ds.nomPM, '')) AS personne_declaree,
    ds.numeroCompte AS numero_compte,
    CAST(ABS(ISNULL(ds.montantTotal, 0)) AS decimal(38, 2)) AS montant,
    COALESCE(NULLIF(ds.devise, ''), NULLIF(ds.pays, '')) AS devise_texte,
    ISNULL(ds.annuleOui, 0) AS est_annulee,
    ISNULL(ds.operationFractionne, 0) AS operation_fractionnee,
    ISNULL(ds.operationGelFond, 0) AS operation_gel_fonds,
    ISNULL(ds.operationHautRisque, 0) AS operation_haut_risque,
    ISNULL(ds.blanchimentCapitaux, 0) AS soupcon_blanchiment,
    ISNULL(ds.financementTerrorisme, 0) AS soupcon_financement_terrorisme
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE
    ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
  UNION ALL
  SELECT
    'LAB_DECLARATION_CENTIF',
    CAST(dc.ID AS varchar(255)),
    CAST(dc.DATE_DECLARATION AS date),
    dc.NUMERO_REF_INT,
    dc.REF_CENTIF,
    COALESCE(NULLIF(dc.NOM, ''), NULLIF(dc.RAISON_SOCIAL, ''), NULLIF(dc.NOM_PM, '')),
    dc.NUM_COMPTE,
    CAST(ABS(ISNULL(dc.MONTANT_TOTAL, 0)) AS decimal(38, 2)),
    dc.DEVISE,
    ISNULL(dc.ANNULEE_CLIENT_LE, 0),
    CAST(0 AS bit),
    CAST(0 AS bit),
    CAST(0 AS bit),
    ISNULL(dc.BLANCHIMENT_CAPITAUX, 0),
    ISNULL(dc.FNC_TERRORISME, 0)
  FROM dbo.LAB_DECLARATION_CENTIF AS dc
  WHERE
    dc.DATE_DECLARATION >= @date_debut
    AND dc.DATE_DECLARATION < DATEADD(day, 1, @date_fin)
), profils_clients AS (
  SELECT
    apr.ID_ADHERENT AS id_adherent_lab,
    a.CODE AS code_adherent,
    a.NOM_ADHERENT AS nom_adherent,
    a.DATE_INSCRIPTION AS date_inscription,
    apr.ID_POINT_SERVICE AS point_service_lab,
    pr.CODE AS code_profil,
    pr.LIBELLE AS profil_risque,
    pdr.CODE AS code_niveau_risque,
    pdr.LIBELLE_RISQUE AS niveau_risque,
    pdr.LIBELLE_COULEUR AS couleur_risque,
    apr.RISQUE_MANUEL AS risque_attribue_manuellement,
    apr.UTILISATEUR_MANUEL AS utilisateur_attribution,
    CASE WHEN a.ID IS NULL THEN 1 ELSE 0 END AS anomalie_adherent_introuvable
  FROM dbo.LAB_ADHERENT_PROFIL_RISQUES AS apr
  LEFT JOIN dbo.ADHERENTS AS a
    ON a.ID = apr.ID_ADHERENT OR a.CODE = apr.ID_ADHERENT
  LEFT JOIN dbo.LAB_PROFIL_RISQUES AS pr
    ON pr.ID = apr.ID_PROFIL_RISQUE
  LEFT JOIN dbo.LAB_PROFILS_DE_RISQUE AS pdr
    ON pdr.ID = apr.ID_RISQUE_DE_PROFIL
), noms_blacklist AS (
  SELECT
    n.ID_BLACKLIST,
    STRING_AGG(CAST(n.NOM AS varchar(max)), ' | ') AS autres_noms
  FROM dbo.LAB_BLACKLIST_NAMES AS n
  GROUP BY n.ID_BLACKLIST
), pieces_blacklist AS (
  SELECT
    p.ID_BLACKLIST,
    STRING_AGG(CAST(p.NUMERO_PIECE AS varchar(max)), ' | ') AS autres_pieces
  FROM dbo.LAB_BLACKLIST_PIECES AS p
  GROUP BY p.ID_BLACKLIST
), pseudos_blacklist AS (
  SELECT
    p.ID_BLACKLIST,
    STRING_AGG(CAST(p.PSEUDO AS varchar(max)), ' | ') AS pseudos
  FROM dbo.LAB_BLACKLIST_PSEUDOS AS p
  GROUP BY p.ID_BLACKLIST
), blacklist AS (
  SELECT
    b.ID AS id_blacklist,
    b.IDENTIFIANT AS identifiant_liste,
    b.TYPE_LISTE AS type_liste,
    b.REGIME_SANCTION AS regime_sanction,
    b.TYPE_PERSONNE AS type_personne,
    b.DESIGNATION AS designation,
    b.NOM AS nom_principal,
    n.autres_noms,
    ps.pseudos,
    b.NIN,
    p.autres_pieces,
    b.NATIONALITE AS nationalite,
    CAST(b.DATE_INSCRIPTION AS date) AS date_inscription,
    b.FONDEMENT_JURIDIQUE AS fondement_juridique,
    CASE
      WHEN NULLIF(LTRIM(RTRIM(ISNULL(b.NOM, ''))), '') IS NULL
        AND NULLIF(LTRIM(RTRIM(ISNULL(b.DESIGNATION, ''))), '') IS NULL
      THEN 1 ELSE 0
    END AS anomalie_identite_absente
  FROM dbo.LAB_BLACKLISTS AS b
  LEFT JOIN noms_blacklist AS n ON n.ID_BLACKLIST = b.ID
  LEFT JOIN pieces_blacklist AS p ON p.ID_BLACKLIST = b.ID
  LEFT JOIN pseudos_blacklist AS ps ON ps.ID_BLACKLIST = b.ID
), synthese_038 AS (
  SELECT '1. ACTIVITE' AS section, 38 AS ligne_excel, 'Total Depots' AS rubrique,
    dr.id_devise, COUNT_BIG(m.id_operation) AS nombre,
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)) AS volume,
    'Alimente la ligne Total Depots du reporting.' AS commentaire
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation IN ('DEPO', 'MOB_DEPO')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 71, 'Depot >= 10k USD',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation IN ('DEPO', 'MOB_DEPO')
    AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 72, 'Retrait >= 10k USD',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation IN ('RETR', 'MOB_RETR')
    AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 73, 'Depot >= 5k USD et < 10k USD',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation IN ('DEPO', 'MOB_DEPO')
    AND m.montant_operation >= dr.seuil_5k
    AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 74, 'Retrait >= 5k USD et < 10k USD',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation IN ('RETR', 'MOB_RETR')
    AND m.montant_operation >= dr.seuil_5k
    AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 152, 'Operations effectuees par Mobile Banking',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Operations API mobiles : MOB_DEPO et MOB_RETR.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.source_mouvement = 'API'
    AND m.type_operation IN ('MOB_DEPO', 'MOB_RETR')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 154, 'Wallet to Bank',
    dr.id_devise, COUNT_BIG(m.id_operation),
    CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'Approximation : depots mobiles MOB_DEPO.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m
    ON m.id_devise = dr.id_devise
    AND m.type_operation = 'MOB_DEPO'
  GROUP BY dr.id_devise
), mouvements_fractionnement AS (
  SELECT
    'BACK_OFFICE' AS source_mouvement,
    CAST(o.ID AS varchar(255)) AS id_operation,
    CAST(o.DATE_OPERATION AS date) AS date_operation,
    CASE
      WHEN o.ID_TYPE_OPERATION = 'DEPO' THEN 'Depot'
      WHEN o.ID_TYPE_OPERATION = 'RETR' THEN 'Retrait'
    END AS type_mouvement,
    ca.ID_ADHERENT,
    a.CODE AS code_adherent,
    a.NOM_ADHERENT,
    a.ID_TYPE_ADHERENT AS code_type_client,
    ta.LIBELLE AS type_client,
    CAST(MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))) AS decimal(38, 2)) AS montant_operation,
    h.ID_DEVISE
  FROM dbo.OPERATIONS AS o
  INNER JOIN dbo.HDPM AS h
    ON h.ID_OPERATION = o.ID
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = h.ID_DEVISE
  LEFT JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.ID = h.ID_COMPTE
  LEFT JOIN dbo.ADHERENTS AS a
    ON a.ID = ca.ID_ADHERENT
  LEFT JOIN dbo.TYPES_ADHERENT AS ta
    ON ta.ID = a.ID_TYPE_ADHERENT
  WHERE
    o.DATE_OPERATION >= @date_debut
    AND o.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND o.ID_TYPE_OPERATION IN ('DEPO', 'RETR')
    AND ISNULL(o.ANNULE, 0) = 0
  GROUP BY
    o.ID,
    CAST(o.DATE_OPERATION AS date),
    o.ID_TYPE_OPERATION,
    ca.ID_ADHERENT,
    a.CODE,
    a.NOM_ADHERENT,
    a.ID_TYPE_ADHERENT,
    ta.LIBELLE,
    h.ID_DEVISE
  UNION ALL
  SELECT
    'API_MOBILE',
    CAST(oa.CODE AS varchar(255)),
    CAST(oa.DATE_OPERATION AS date),
    CASE
      WHEN oa.ID_TYPE_OPERATION = 'MOB_DEPO' THEN 'Depot'
      WHEN oa.ID_TYPE_OPERATION = 'MOB_RETR' THEN 'Retrait'
    END,
    ca.ID_ADHERENT,
    a.CODE,
    a.NOM_ADHERENT,
    a.ID_TYPE_ADHERENT,
    ta.LIBELLE,
    CAST(MAX(ABS(ISNULL(h.MONTANT_OPERATION, 0))) AS decimal(38, 2)),
    h.ID_DEVISE
  FROM dbo.OPERATIONS_API AS oa
  INNER JOIN dbo.HDPM_API AS h
    ON h.ID_OPERATION = oa.CODE
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = h.ID_DEVISE
  LEFT JOIN dbo.COMPTES_ADHERENT AS ca
    ON ca.ID = h.ID_COMPTE
  LEFT JOIN dbo.ADHERENTS AS a
    ON a.ID = ca.ID_ADHERENT
  LEFT JOIN dbo.TYPES_ADHERENT AS ta
    ON ta.ID = a.ID_TYPE_ADHERENT
  WHERE
    oa.DATE_OPERATION >= @date_debut
    AND oa.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND oa.ID_TYPE_OPERATION IN ('MOB_DEPO', 'MOB_RETR')
    AND ISNULL(oa.ANNULE, 0) = 0
  GROUP BY
    oa.CODE,
    CAST(oa.DATE_OPERATION AS date),
    oa.ID_TYPE_OPERATION,
    ca.ID_ADHERENT,
    a.CODE,
    a.NOM_ADHERENT,
    a.ID_TYPE_ADHERENT,
    ta.LIBELLE,
    h.ID_DEVISE
), fractionnements AS (
  SELECT
    m.date_operation,
    m.ID_ADHERENT,
    m.code_adherent,
    m.NOM_ADHERENT,
    m.code_type_client,
    m.type_client,
    m.type_mouvement,
    m.ID_DEVISE AS id_devise,
    COUNT_BIG(*) AS nb_operations,
    CAST(SUM(m.montant_operation) AS decimal(38, 2)) AS montant_cumule,
    CAST(MAX(m.montant_operation) AS decimal(38, 2)) AS montant_max_unitaire,
    dr.seuil_10k AS seuil_reference
  FROM mouvements_fractionnement AS m
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = m.ID_DEVISE
  WHERE
    m.montant_operation < dr.seuil_10k
  GROUP BY
    m.date_operation,
    m.ID_ADHERENT,
    m.code_adherent,
    m.NOM_ADHERENT,
    m.code_type_client,
    m.type_client,
    m.type_mouvement,
    m.ID_DEVISE,
    dr.seuil_10k
  HAVING
    COUNT_BIG(*) >= 2
    AND SUM(m.montant_operation) >= dr.seuil_10k
), couverture_conformite AS (
  SELECT
    CAST(rubrique_reporting AS varchar(255)) AS rubrique_reporting,
    CAST(statut_couverture AS varchar(255)) AS statut_couverture,
    CAST(source_identifiee AS varchar(1000)) AS source_identifiee,
    CAST(prerequis_mapping AS varchar(1000)) AS prerequis_mapping
  FROM (VALUES
    ('PPE', 'PARTIEL', 'dbo.LAB_DECLARATION_CENTIF.PPE / PPE_PM et profils LAB',
      'Le marqueur PPE existe dans les declarations, mais pas comme attribut date du referentiel client.'),
    ('Non-residents', 'PARTIEL', 'dbo.ADRESSES, dbo.PAYS et nationalite des tables LAB',
      'A mapper avec les donnees pays/adresse/statut resident du client.'),
    ('MPME', 'PARTIEL', 'dbo.SECTEURS_ACTIVITE, dbo.LAB_PROFILAGE et dbo.LAB_PERFECT_SECTEUR',
      'Faire valider la nomenclature sectorielle officielle par la Conformite.'),
    ('OBNL', 'PARTIEL', 'dbo.SECTEURS_ACTIVITE, dbo.TYPES_ADHERENT et dbo.LAB_PROFILAGE',
      'A mapper avec categorie/type adherent, secteur activite ou forme juridique.'),
    ('Secteur immobilier', 'PARTIEL', 'dbo.SECTEURS_ACTIVITE / dbo.SECTEURS_ACTIVITE_CREDIT',
      'A mapper avec SECTEURS_ACTIVITE / SECTEURS_ACTIVITE_CREDIT.'),
    ('Secteur minier', 'PARTIEL', 'dbo.SECTEURS_ACTIVITE / dbo.SECTEURS_ACTIVITE_CREDIT',
      'Faire valider les codes secteur et objets de financement retenus.'),
    ('Alertes LBC-FT', 'COUVERT', 'dbo.LAB_ALERTES et dbo.LAB_RECHERCHES_NON_FRUCTUEUSES',
      'Valider la liste des valeurs ETAT_ALERTE considerees comme traitees.'),
    ('DOS / declarations de soupcon', 'COUVERT', 'dbo.LAB_DECLARATION_SOUPCONS et dbo.LAB_DECLARATION_CENTIF',
      'Verifier si les deux tables representent deux formulaires ou deux etapes afin d eviter un double comptage.'),
    ('Listes de sanctions', 'COUVERT', 'dbo.LAB_BLACKLISTS et tables enfants noms, pieces et pseudos',
      'La base contient le referentiel des listes, pas la preuve d un gel ou d une transaction refusee.'),
    ('Gels et transactions refusees pour sanctions', 'NON_COUVERT', 'Aucune table d action de gel/refus identifiee',
      'Ne pas assimiler une inscription en blacklist a une mesure de gel effectivement executee.'),
    ('Credits rembourses anticipativement', 'COUVERT', 'dbo.OPERATIONS_CRD.REMB_ANTICIPER, dbo.OPERATIONS et dbo.PRETS',
      'La requete de reporting compte les prets distincts et les montants d operations sur la periode.'),
    ('Comptes dormants reactives', 'COUVERT', 'dbo.REACTIVATION_COMPTE_EPG, dbo.CLOTURE_COMPTE et dbo.OPERATIONS',
      'La date de l operation de reactivation definit la periode de reporting.')
  ) AS v(rubrique_reporting, statut_couverture, source_identifiee, prerequis_mapping)
), mouvements_comptables_057 AS (
  SELECT
    h.DATE_OPERATION,
    h.ID_DEVISE,
    h.ID_POINT_SERVICE,
    CAST(ABS(ISNULL(h.MONTANT_REEL, h.MONTANT_OPERATION)) AS decimal(38, 2)) AS montant_mouvement
  FROM dbo.HDPM AS h
  WHERE
    h.DATE_OPERATION >= @date_debut
    AND h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND (@id_devise_reporting IS NULL OR h.ID_DEVISE = @id_devise_reporting)
  UNION ALL
  SELECT
    h.DATE_OPERATION,
    h.ID_DEVISE,
    h.ID_POINT_SERVICE,
    CAST(ABS(h.MONTANT_OPERATION) AS decimal(38, 2))
  FROM dbo.HDPM_API AS h
  WHERE
    h.DATE_OPERATION >= @date_debut
    AND h.DATE_OPERATION < DATEADD(day, 1, @date_fin)
    AND (@id_devise_reporting IS NULL OR h.ID_DEVISE = @id_devise_reporting)
), gros_mouvements_057 AS (
  SELECT
    DATEFROMPARTS(YEAR(h.DATE_OPERATION), MONTH(h.DATE_OPERATION), 1) AS mois,
    ps.CODE AS code_point_service,
    ps.NOM AS nom_point_service,
    h.ID_DEVISE AS id_devise,
    dr.seuil_5k AS seuil_reference,
    COUNT_BIG(*) AS nb_gros_mouvements,
    CAST(SUM(h.montant_mouvement) AS decimal(38, 2)) AS volume_total,
    CAST(MAX(h.montant_mouvement) AS decimal(38, 2)) AS plus_gros_mouvement
  FROM mouvements_comptables_057 AS h
  INNER JOIN devises_reporting AS dr
    ON dr.id_devise = h.ID_DEVISE
  LEFT JOIN dbo.POINTS_SERVICE AS ps
    ON ps.ID = h.ID_POINT_SERVICE
  WHERE
    h.montant_mouvement >= dr.seuil_5k
  GROUP BY
    DATEFROMPARTS(YEAR(h.DATE_OPERATION), MONTH(h.DATE_OPERATION), 1),
    ps.CODE,
    ps.NOM,
    h.ID_DEVISE,
    dr.seuil_5k
), reporting AS (
  SELECT '1. TAILLE' AS section, 26 AS ligne_excel, 'Total operations comptabilisees' AS rubrique,
    dr.id_devise, COUNT_BIG(m.id_operation) AS nombre, CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)) AS volume,
    'COUVERT' AS statut_couverture, 'dbo.OPERATIONS + dbo.HDPM et sources API' AS source_donnee,
    'Une operation est comptee une fois avec le montant absolu maximal de ses lignes HDPM.' AS commentaire
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '1. TAILLE', 27, 'Total operations en especes', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS + dbo.HDPM',
    'Definition operationnelle : depots et retraits DEPO/RETR ; faire valider les autres modes especes.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('DEPO', 'RETR')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '1. TAILLE', 38, 'Total depots', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS/HDPM + dbo.OPERATIONS_API/HDPM_API',
    'Flux de depots DEPO et MOB_DEPO sur la periode, distinct du stock d epargne.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('DEPO', 'MOB_DEPO')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 65, 'Clients enregistres durant la periode', NULL,
    COUNT_BIG(*), CAST(NULL AS decimal(38, 2)),
    'COUVERT', 'dbo.ADHERENTS',
    'Nombre de clients IMF distincts inscrits dans la periode ; aucun volume monetaire n est calcule.'
  FROM dbo.ADHERENTS AS a
  WHERE a.ID_CATEGORIE_ADHERENT = 'IMF'
    AND a.DATE_INSCRIPTION >= @date_debut
    AND a.DATE_INSCRIPTION < DATEADD(day, 1, @date_fin)
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 66, 'Clients actuellement classes a haut risque', NULL,
    COUNT_BIG(DISTINCT pc.id_adherent_lab), CAST(NULL AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ADHERENT_PROFIL_RISQUES + dbo.LAB_PROFILS_DE_RISQUE',
    'La table ne porte pas de date de reclassement ; le resultat est un stock actuel, pas un flux de la periode.'
  FROM profils_clients AS pc
  WHERE UPPER(ISNULL(pc.niveau_risque, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pc.code_niveau_risque, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pc.couleur_risque, '')) LIKE '%ROUGE%'
  UNION ALL
  SELECT '2. PORTEFEUILLE CLIENT', 68, 'Clients sous surveillance renforcee', NULL,
    COUNT_BIG(DISTINCT pc.id_adherent_lab), CAST(NULL AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ADHERENT_PROFIL_RISQUES + dbo.LAB_PROFILS_DE_RISQUE',
    'Approximation par profil de risque eleve ; faire valider la regle de surveillance renforcee.'
  FROM profils_clients AS pc
  WHERE UPPER(ISNULL(pc.niveau_risque, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pc.code_niveau_risque, '')) LIKE '%HAUT%'
     OR UPPER(ISNULL(pc.couleur_risque, '')) LIKE '%ROUGE%'
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 71, 'Depot >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements DEPO et MOB_DEPO', 'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('DEPO', 'MOB_DEPO') AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 72, 'Retrait >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements RETR et MOB_RETR', 'Seuil applique par devise : USD=10000, CDF=@seuil_10k_usd_cdf.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('RETR', 'MOB_RETR') AND m.montant_operation >= dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 73, 'Depot entre equivalents 5k et 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements DEPO et MOB_DEPO', 'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('DEPO', 'MOB_DEPO')
    AND m.montant_operation >= dr.seuil_5k AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 74, 'Retrait entre equivalents 5k et 10k USD', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'Mouvements RETR et MOB_RETR', 'Seuils appliques par devise : USD=5000/10000, CDF=parametres CDF.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.type_operation IN ('RETR', 'MOB_RETR')
    AND m.montant_operation >= dr.seuil_5k AND m.montant_operation < dr.seuil_10k
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 142, 'Credits rembourses anticipativement', dr.id_devise,
    COUNT_BIG(ra.ID_PRET), CAST(ISNULL(SUM(ra.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS_CRD.REMB_ANTICIPER + dbo.OPERATIONS',
    'Nombre de prets distincts marques comme rembourses anticipativement dans la periode.'
  FROM devises_reporting AS dr
  LEFT JOIN remboursements_anticipes AS ra ON ra.id_devise = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 144, 'Total alertes generees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.LAB_ALERTES', 'Periode fondee sur DATE_CREATED puis DATE_OPERATION en repli.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 145, 'Total alertes traitees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES.ETAT_ALERTE',
    'Etats commencant par TRAIT, CLOTUR ou VALID ; nomenclature a valider par la Conformite.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise AND a.est_traitee = 1
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 146, 'Alertes especes >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Seuil applique par devise ; type especes reconnu par mots-clefs.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise AND a.montant >= dr.seuil_10k
    AND (UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%ESPEC%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%ESPEC%' OR UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%CASH%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 147, 'Alertes traitees especes >= equivalent 10k USD', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Cumule le critere de seuil/especes et la regle provisoire des etats traites.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise AND a.est_traitee = 1 AND a.montant >= dr.seuil_10k
    AND (UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%ESPEC%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%ESPEC%' OR UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%CASH%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 148, 'Operations suspectes ou atypiques detectees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Detection par libelle/type contenant SUSPECT ou ATYPI.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise
    AND (UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%SUSPECT%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%SUSPECT%'
      OR UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%ATYPI%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%ATYPI%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 149, 'Comptes dormants reactives', dr.id_devise,
    COUNT_BIG(r.id_reactivation), CAST(ISNULL(SUM(r.montant), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.REACTIVATION_COMPTE_EPG + dbo.OPERATIONS',
    'Le volume correspond au montant a payer de la reactivation, pas au solde du compte.'
  FROM devises_reporting AS dr
  LEFT JOIN reactivations AS r ON r.id_devise = dr.id_devise
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '3. PRODUIT - SERVICE - OPERATIONS', 150, 'Operations fractionnees detectees', dr.id_devise,
    COUNT_BIG(a.ID), CAST(ISNULL(SUM(a.montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_ALERTES', 'Detection par mots-clefs FRACTION ou STRUCTUR dans les alertes officielles.'
  FROM devises_reporting AS dr
  LEFT JOIN alertes_periode AS a ON a.ID_DEVISE = dr.id_devise
    AND (UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%FRACTION%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%FRACTION%'
      OR UPPER(ISNULL(a.TYPE_ALERTE, '')) LIKE '%STRUCTUR%' OR UPPER(ISNULL(a.DESCRIPTION_ALERTE, '')) LIKE '%STRUCTUR%')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 152, 'Operations effectuees par Mobile Banking', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'COUVERT', 'dbo.OPERATIONS_API + dbo.HDPM_API', 'Operations API MOB_DEPO et MOB_RETR.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.source_mouvement = 'API' AND m.type_operation IN ('MOB_DEPO', 'MOB_RETR')
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 153, 'Bank to Wallet', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS_API + dbo.HDPM_API',
    'Hypothese : MOB_RETR debite le compte bancaire vers le wallet ; sens a confirmer.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.source_mouvement = 'API' AND m.type_operation = 'MOB_RETR'
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '4. CANAUX DE DISTRIBUTION', 154, 'Wallet to Bank', dr.id_devise,
    COUNT_BIG(m.id_operation), CAST(ISNULL(SUM(m.montant_operation), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.OPERATIONS_API + dbo.HDPM_API',
    'Hypothese : MOB_DEPO credite le compte bancaire depuis le wallet ; sens a confirmer.'
  FROM devises_reporting AS dr
  LEFT JOIN mouvements AS m ON m.id_devise = dr.id_devise AND m.source_mouvement = 'API' AND m.type_operation = 'MOB_DEPO'
  GROUP BY dr.id_devise
  UNION ALL
  SELECT '5. DECLARATIONS DES SOUPCONS', 164, 'DOS enregistrees', NULL,
    COUNT_BIG(*), CAST(ISNULL(SUM(montant), 0) AS decimal(38, 2)),
    'PARTIEL', 'dbo.LAB_DECLARATION_SOUPCONS + dbo.LAB_DECLARATION_CENTIF',
    'La devise est stockee en texte dans chaque declaration ; controler devise_texte avant consolidation.'
  FROM declarations
  WHERE est_annulee = 0
  UNION ALL
  SELECT '5. DECLARATIONS DES SOUPCONS', 163, 'Declarations automatiques', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Aucune source explicitement qualifiee automatique',
    'Ne pas assimiler automatiquement LAB_DECLARATION_CENTIF a une declaration automatique.'
  UNION ALL
  SELECT '6. SANCTIONS FINANCIERES CIBLEES', 166, 'Gels des avoirs', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Referentiel dbo.LAB_BLACKLISTS uniquement',
    'Aucune table d action de gel execute identifiee dans le schema.'
  UNION ALL
  SELECT '6. SANCTIONS FINANCIERES CIBLEES', 167, 'Transactions refusees pour sanctions', NULL,
    CAST(NULL AS bigint), CAST(NULL AS decimal(38, 2)),
    'NON_COUVERT', 'Referentiel dbo.LAB_BLACKLISTS uniquement',
    'Aucune table de decision de refus liee a une correspondance blacklist identifiee.'
), controles_qualite AS (
  SELECT
    'ALERTE_SANS_NUMERO' AS controle,
    COUNT_BIG(*) AS nombre_anomalies,
    'ELEVEE' AS severite,
    'Rendre NUM_ALERTE obligatoire et unique pour assurer la piste d audit.' AS action_recommandee
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(NUM_ALERTE, ''))), '') IS NULL
  UNION ALL
  SELECT 'ALERTE_SANS_CLIENT', COUNT_BIG(*), 'ELEVEE',
    'Completer ID_ADHERENT avant cloture de l alerte.'
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(ID_ADHERENT, ''))), '') IS NULL
  UNION ALL
  SELECT 'ALERTE_SANS_DEVISE', COUNT_BIG(*), 'ELEVEE',
    'Rendre ID_DEVISE obligatoire pour eviter les consolidations multi-devises.'
  FROM alertes_periode
  WHERE ID_DEVISE IS NULL
  UNION ALL
  SELECT 'ALERTE_SANS_ETAT', COUNT_BIG(*), 'ELEVEE',
    'Rendre ETAT_ALERTE obligatoire et normaliser les valeurs autorisees.'
  FROM alertes_periode
  WHERE NULLIF(LTRIM(RTRIM(ISNULL(ETAT_ALERTE, ''))), '') IS NULL
  UNION ALL
  SELECT 'NUMERO_ALERTE_DUPLIQUE', COUNT_BIG(*), 'CRITIQUE',
    'Investiguer les numeros repetes et poser une contrainte d unicite si la regle metier le confirme.'
  FROM (
    SELECT NUM_ALERTE
    FROM alertes_periode
    WHERE NULLIF(LTRIM(RTRIM(ISNULL(NUM_ALERTE, ''))), '') IS NOT NULL
    GROUP BY NUM_ALERTE
    HAVING COUNT_BIG(*) > 1
  ) AS doublons
  UNION ALL
  SELECT 'DOS_SANS_REFERENCE_INTERNE', COUNT_BIG(*), 'ELEVEE',
    'Renseigner referenceInterne pour relier la declaration au dossier de Conformite.'
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE
    ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
    AND NULLIF(LTRIM(RTRIM(ISNULL(ds.referenceInterne, ''))), '') IS NULL
  UNION ALL
  SELECT 'DOS_SANS_DEVISE', COUNT_BIG(*), 'ELEVEE',
    'Renseigner la devise avant toute consolidation des montants declares.'
  FROM dbo.LAB_DECLARATION_SOUPCONS AS ds
  WHERE
    ds.dateDeclaration >= @date_debut
    AND ds.dateDeclaration < DATEADD(day, 1, @date_fin)
    AND NULLIF(LTRIM(RTRIM(ISNULL(ds.devise, ''))), '') IS NULL
  UNION ALL
  SELECT 'PROFIL_LAB_SANS_ADHERENT', COUNT_BIG(*), 'CRITIQUE',
    'Corriger la cle ID_ADHERENT ou CODE afin de garantir le rattachement au client Perfect Vision.'
  FROM profils_clients
  WHERE anomalie_adherent_introuvable = 1
  UNION ALL
  SELECT 'BLACKLIST_SANS_IDENTITE', COUNT_BIG(*), 'CRITIQUE',
    'Completer au minimum NOM ou DESIGNATION pour rendre le screening exploitable.'
  FROM blacklist
  WHERE anomalie_identite_absente = 1
), socle AS (
SELECT
  '149_REPORTING_LBC_FT' AS analyse_source,
  'REPORTING' AS type_ligne,
  CAST(r.section AS varchar(255)) AS section,
  CAST(r.ligne_excel AS int) AS ligne_excel,
  CAST(r.rubrique AS varchar(255)) AS rubrique,
