  CAST(NULL AS varchar(255)) AS reference_externe,
  CAST(NULL AS varchar(255)) AS id_operation,
  CAST(NULL AS varchar(255)) AS type_operation,
  CAST(NULL AS varchar(255)) AS type_alerte,
